/** Exact nine-card Energy motif proof plus the complete 21-card semantic guard. */
async function auditEnergyRadioactiveGraphics(cdp, mode) {
  const started = performance.now();
  const stage = (name) => console.error(
    `[energy-radioactive-graphics:${mode}] ${name} ${Math.round(performance.now() - started)}ms`,
  );
  const blank = await waitForStablePageCapture(
    cdp, `${mode} initial blank energy-radioactive framebuffer`,
  );
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.prepareEnergyRadioactiveGraphicsFixture !== 'function'
      || typeof audit.energyRadioactiveGraphicsAtlas !== 'function'
      || typeof audit.setEnergyIdentityStyling !== 'function'
      || typeof audit.setLiquidIdentityStyling !== 'function'
      || typeof audit.setGasIdentityStyling !== 'function') {
      throw new Error('Energy/radioactive graphics audit API unavailable');
    }
    audit.prepareEnergyRadioactiveGraphicsFixture();
    return true;
  })()`);
  const rawAtlas = await waitFor(() => evaluate(cdp, `(() => {
    const atlas = window.__ANIFOR_INPUT_AUDIT__.energyRadioactiveGraphicsAtlas();
    const cards = Array.isArray(atlas) ? atlas : atlas?.cards;
    return cards?.length === 21 ? atlas : false;
  })()`), 15_000, `${mode} energy/radioactive graphics fixture`);
  const atlas = normalizeEnergyRadioactiveGraphicsAtlas(rawAtlas);
  const expectedMaterials = [
    4, 20, 101, 103, 106, 107, 110, 197, 200, 98, 99, 100, 102, 104, 105,
    108, 109, 111, 112, 113, 114,
  ];
  const expectedCodes = [
    'FIRE', 'PLSM', 'ELEC', 'GRVT', 'NEUT', 'PHOT', 'PROT', 'BRAY', 'EMBR',
    'AMTR', 'BVBR', 'DEUT', 'EXOT', 'ISOZ', 'ISZS', 'PLUT', 'POLO', 'SING',
    'URAN', 'VIBR', 'WARP',
  ];
  assert(atlas.cards.length === 21 && atlas.energyCards.length === 9
      && atlas.radioactiveCards.length === 17
      && atlas.nativeProductCards.map(({ code }) => code).join(',') === 'BRAY,EMBR'
      && atlas.cards.every(({ material, code }, index) => (
        material === expectedMaterials[index] && code === expectedCodes[index]
      )),
  `${mode}: energy/radioactive atlas contract changed (${JSON.stringify(atlas.cards.map(
    ({ code, material, phase, family, nativeProduct }) => ({
      code, material, phase, family, nativeProduct,
    }),
  ))})`);

  const semanticState = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const snapshot = audit.energyRadioactiveGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const inside = (x, y, rect) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    return cards.map((entry) => {
      let bodyExact = true;
      for (let y = entry.body.y; y < entry.body.y + entry.body.height; y++) {
        for (let x = entry.body.x; x < entry.body.x + entry.body.width; x++) {
          const empty = inside(x, y, entry.authoredHole) || inside(x, y, entry.openChannel);
          bodyExact = bodyExact && audit.cell(x, y) === (empty ? 0 : entry.material);
        }
      }
      return {
        code: entry.code,
        material: entry.material,
        bodyExact,
        surfaceProbeExact: exactRect(entry.surfaceProbe, entry.material),
        coreProbeExact: exactRect(entry.coreProbe, entry.material),
        authoredHoleEmpty: exactRect(entry.authoredHole, 0),
        openChannelEmpty: exactRect(entry.openChannel, 0),
        sparseCarriersExact: entry.sparseCarriers.every(
          (point) => audit.cell(point.x, point.y) === entry.material,
        ),
        carrierGapEmpty: exactRect(entry.carrierGap, 0),
        isolated: audit.cell(entry.isolated.x, entry.isolated.y),
        guardedBlankEmpty: exactRect(entry.guardedBlank, 0),
        liquidOwnerExact: exactRect(entry.liquidContact.owner, entry.material),
        liquidUnlikeExact: exactRect(
          entry.liquidContact.unlike, entry.liquidContact.unlikeMaterial,
        ),
        liquidUnlikeMaterial: entry.liquidContact.unlikeMaterial,
        solidOwnerExact: exactRect(entry.solidContact.owner, entry.material),
        solidUnlikeExact: exactRect(
          entry.solidContact.unlike, entry.solidContact.unlikeMaterial,
        ),
        solidUnlikeMaterial: entry.solidContact.unlikeMaterial,
      };
    });
  })()`);
  assert(semanticState.every((entry) => entry.bodyExact && entry.surfaceProbeExact
      && entry.coreProbeExact && entry.authoredHoleEmpty && entry.openChannelEmpty
      && entry.sparseCarriersExact && entry.carrierGapEmpty
      && entry.isolated === entry.material && entry.guardedBlankEmpty
      && entry.liquidOwnerExact && entry.liquidUnlikeExact && entry.liquidUnlikeMaterial === 2
      && entry.solidOwnerExact && entry.solidUnlikeExact && entry.solidUnlikeMaterial === 23),
  `${mode}: energy/radioactive fixture lost authored semantics (${JSON.stringify(semanticState)})`);
  stage('fixture-ready');

  const setExactIdentityStyling = async (enabled) => evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.setEnergyIdentityStyling(${enabled});
    audit.setLiquidIdentityStyling(${enabled});
    audit.setGasIdentityStyling(${enabled});
    return true;
  })()`);
  await setExactIdentityStyling(false);
  const flat = await waitForStablePageCapture(cdp, `${mode} flat energy-identity framebuffer`);
  const flatBacking = await sampleEnergyRadioactiveBacking(cdp);
  await setExactIdentityStyling(true);
  const styled = await waitForStablePageCapture(cdp, `${mode} styled energy-identity framebuffer`);
  const styledBacking = await sampleEnergyRadioactiveBacking(cdp);
  await setExactIdentityStyling(false);
  const repeated = await waitForStablePageCapture(
    cdp, `${mode} repeated flat energy-identity framebuffer`,
  );
  const repeatedBacking = await sampleEnergyRadioactiveBacking(cdp);
  for (const [state, backing] of [
    ['flat', flatBacking], ['styled', styledBacking], ['repeated-flat', repeatedBacking],
  ]) assertEnergyRadioactiveBacking(backing, `${mode} ${state}`);

  assert(flatBacking.cards.every((card, index) => (
    card.semanticSignature === styledBacking.cards[index].semanticSignature
      && card.semanticSignature === repeatedBacking.cards[index].semanticSignature
      && card.alphaSignature === styledBacking.cards[index].alphaSignature
      && card.alphaSignature === repeatedBacking.cards[index].alphaSignature
      && card.supportSignature === styledBacking.cards[index].supportSignature
      && card.supportSignature === repeatedBacking.cards[index].supportSignature
  )), `${mode}: energy identity styling changed semantics/alpha/support (${JSON.stringify({
    flat: compactEnergyRadioactiveBacking(flatBacking),
    styled: compactEnergyRadioactiveBacking(styledBacking),
    repeated: compactEnergyRadioactiveBacking(repeatedBacking),
  })})`);
  const controlLeaks = flatBacking.cards.flatMap((card, index) => {
    const changed = styledBacking.cards[index];
    const returned = repeatedBacking.cards[index];
    const leaks = [];
    if (!arraysEqual(card.liquidUnlikeRgb, changed.liquidUnlikeRgb)
      || !arraysEqual(card.liquidUnlikeRgb, returned.liquidUnlikeRgb)) leaks.push('Water');
    if (!arraysEqual(card.solidUnlikeRgb, changed.solidUnlikeRgb)
      || !arraysEqual(card.solidUnlikeRgb, returned.solidUnlikeRgb)) leaks.push('Metal');
    return leaks.map((control) => ({ code: card.code, control }));
  });
  assert(controlLeaks.length === 0,
    `${mode}: energy identity styling leaked into contact controls (${JSON.stringify(controlLeaks)})`);

  const backingResponses = summarizeEnergyRadioactiveBackingResponses(
    flatBacking, styledBacking, repeatedBacking,
  );
  assert(backingResponses.every(({ rgbRms, rgbPeak, changedSampleRatio, repeatRgbPeak }) => (
    rgbRms >= 0.02 && rgbRms <= 32 && rgbPeak > 0 && rgbPeak <= 96
      && changedSampleRatio >= 0.002 && repeatRgbPeak === 0
  )), `${mode}: Energy motif response is absent, unbounded, or non-repeatable (${JSON.stringify(backingResponses)})`);
  assert(backingResponses.every(({ responseProfile }) => responseProfile.length === 16
      && Math.abs(responseProfile.reduce((sum, value) => sum + value, 0) - 1) <= 0.001),
  `${mode}: Energy response profiles are not normalized 4x4 fields (${JSON.stringify(backingResponses)})`);
  const exactGroups = [
    { name: 'Energy cores', codes: ['FIRE', 'PLSM', 'ELEC', 'GRVT', 'NEUT', 'PHOT', 'PROT', 'BRAY', 'EMBR'] },
    { name: 'radioactive bodies', codes: ['BVBR', 'ISZS', 'PLUT', 'POLO', 'SING', 'URAN', 'VIBR'] },
    { name: 'radioactive liquids', codes: ['DEUT', 'EXOT', 'ISOZ'] },
    { name: 'radioactive gases', codes: ['AMTR', 'WARP'] },
  ];
  for (const group of exactGroups) {
    const grouped = backingResponses.filter(({ code }) => group.codes.includes(code));
    assert(grouped.length === group.codes.length
        && new Set(grouped.map(({ responseSignature }) => responseSignature)).size === grouped.length,
    `${mode}: ${group.name} do not have distinct exact motifs (${JSON.stringify(grouped)})`);
  }

  const exactRegions = atlas.cards.map((entry) => ({
    name: `exact-identity-${entry.code}`,
    x: entry.body.x + entry.body.width / 2,
    y: entry.body.y + entry.body.height / 2,
    radiusX: entry.body.width / 2,
    radiusY: entry.body.height / 2,
    signature: true,
    silhouette: true,
    fastSupport: true,
  }));
  const atlasBounds = containingCellularRegion(atlas.cards.map(({ card }) => card));
  const responses = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: styled.capture.data,
    repeatedStraight: repeated.capture.data,
  }, [...exactRegions, { name: 'energy-radioactive-atlas', ...atlasBounds }], flat.canvasRect);
  const atlasResponse = responses.at(-1);
  assert(atlasResponse.repeatRgbPeak === 0,
    `${mode}: energy flat→styled→flat framebuffer was not exact (${JSON.stringify(atlasResponse)})`);
  assert(responses.slice(0, 21).every((sample) => sample.rgbRms > 0
      && sample.rgbRms <= 40 && sample.rgbPeak > 0 && sample.rgbPeak <= 128
      && sample.repeatRgbPeak === 0),
  `${mode}: an exact material identity has no bounded composed response (${JSON.stringify(responses.slice(0, 21))})`);
  const [flatSupport, styledSupport] = await Promise.all([
    samplePageRegions(
      cdp, flat.capture.data, exactRegions,
      blank.capture.data, blank.reference.data, flat.canvasRect,
    ),
    samplePageRegions(
      cdp, styled.capture.data, exactRegions,
      blank.capture.data, blank.reference.data, flat.canvasRect,
    ),
  ]);
  assert(flatSupport.every((sample, index) => (
    atlas.cards[index].code === 'WARP' || (sample.visible > 0 && sample.worldArea > 0)
  )) && styledSupport.every((sample) => sample.visible > 0 && sample.worldArea > 0),
  `${mode}: an exact material card is not visible (${JSON.stringify({ flatSupport, styledSupport })})`);
  stage('responses-ready');

  return {
    cards: atlas.cards.length,
    energyCards: atlas.energyCards.length,
    radioactiveCards: atlas.radioactiveCards.length,
    nativeProducts: atlas.nativeProductCards.map(({ code }) => code),
    authoredHoleCells: atlas.authoredHoles.length,
    openChannelCells: atlas.openChannels.length,
    sparseCarriers: atlas.sparseCarriers.length,
    carrierGaps: atlas.carrierGaps.length,
    isolatedControls: atlas.isolated.length,
    guardedBlanks: atlas.guardedBlanks.length,
    unlikeWaterContacts: atlas.liquidContacts.length,
    unlikeMetalContacts: atlas.solidContacts.length,
    exactRepeatedOff: atlasResponse.repeatRgbPeak === 0,
    cardSignatures: atlas.cards.map((entry, index) => ({
      index: entry.index,
      material: entry.material,
      code: entry.code,
      flatSignature: flatSupport[index].signature,
      styledSignature: styledSupport[index].signature,
      rgbRms: responses[index].rgbRms,
      rgbPeak: responses[index].rgbPeak,
      backingRgbRms: backingResponses[index].rgbRms,
      backingRgbPeak: backingResponses[index].rgbPeak,
      backingChangedSampleRatio: backingResponses[index].changedSampleRatio,
      backingRepeatRgbPeak: backingResponses[index].repeatRgbPeak,
      backingResponseSignature: backingResponses[index].responseSignature,
      backingResponseProfile: backingResponses[index].responseProfile,
    })),
  };
}

async function sampleEnergyRadioactiveBacking(cdp) {
  return evaluate(cdp, `(() => {
    const world = document.querySelector('.world-canvas');
    if (!(world instanceof HTMLCanvasElement)) throw new Error('World canvas unavailable');
    const copy = document.createElement('canvas');
    copy.width = world.width;
    copy.height = world.height;
    const context = copy.getContext('2d', { willReadFrequently: true });
    if (!context) throw new Error('Energy/radioactive backing sampler unavailable');
    context.drawImage(world, 0, 0);
    const pixels = context.getImageData(0, 0, copy.width, copy.height).data;
    const scaleX = copy.width / ${WORLD_WIDTH};
    const scaleY = copy.height / ${WORLD_HEIGHT};
    const rectPoints = (rect) => {
      const points = [];
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) points.push({ x, y });
      }
      return points;
    };
    const cellAlphaPeak = ({ x, y }) => {
      const left = Math.floor(x * scaleX);
      const top = Math.floor(y * scaleY);
      const right = Math.max(left + 1, Math.floor((x + 1) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((y + 1) * scaleY));
      let peak = 0;
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        peak = Math.max(peak, pixels[(py * copy.width + px) * 4 + 3]);
      }
      return peak;
    };
    const sampleRect = (rect, includeAlpha = false) => {
      const left = Math.floor(rect.x * scaleX);
      const top = Math.floor(rect.y * scaleY);
      const right = Math.max(left + 1, Math.floor((rect.x + rect.width) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((rect.y + rect.height) * scaleY));
      const rgb = [];
      const alpha = [];
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        const offset = (py * copy.width + px) * 4;
        rgb.push(pixels[offset], pixels[offset + 1], pixels[offset + 2]);
        if (includeAlpha) alpha.push(pixels[offset + 3]);
      }
      return { width: right - left, height: bottom - top, rgb, alpha };
    };
    const snapshot = window.__ANIFOR_INPUT_AUDIT__.energyRadioactiveGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    return {
      width: copy.width,
      height: copy.height,
      scaleX,
      scaleY,
      cards: cards.map((entry) => {
        const cardPixels = sampleRect(entry.card, true);
        let semanticSignature = 2166136261;
        for (let y = entry.card.y; y < entry.card.y + entry.card.height; y++) {
          for (let x = entry.card.x; x < entry.card.x + entry.card.width; x++) {
            semanticSignature = Math.imul(
              semanticSignature ^ window.__ANIFOR_INPUT_AUDIT__.cell(x, y), 16777619,
            ) >>> 0;
          }
        }
        let alphaSignature = 2166136261;
        let supportSignature = 2166136261;
        for (const alpha of cardPixels.alpha) {
          alphaSignature = Math.imul(alphaSignature ^ alpha, 16777619) >>> 0;
          supportSignature = Math.imul(
            supportSignature ^ Number(alpha > 0), 16777619,
          ) >>> 0;
        }
        const key = ({ x, y }) => x + ',' + y;
        const emptyKeys = new Set([
          ...rectPoints(entry.authoredHole), ...rectPoints(entry.openChannel),
        ].map(key));
        const bodyPoints = rectPoints(entry.body).filter((point) => !emptyKeys.has(key(point)));
        const body = sampleRect(entry.body);
        return {
          index: entry.index,
          material: entry.material,
          code: entry.code,
          phase: entry.phase,
          bodyExpected: bodyPoints.length,
          bodySupported: bodyPoints.filter((point) => cellAlphaPeak(point) > 0).length,
          sparseExpected: entry.sparseCarriers.length,
          sparseSupported: entry.sparseCarriers.filter(
            (point) => cellAlphaPeak(point) > 0,
          ).length,
          isolatedAlphaPeak: cellAlphaPeak(entry.isolated),
          semanticSignature,
          alphaSignature,
          supportSignature,
          width: body.width,
          height: body.height,
          rgb: body.rgb,
          liquidUnlikeRgb: sampleRect(entry.liquidContact.unlike).rgb,
          solidUnlikeRgb: sampleRect(entry.solidContact.unlike).rgb,
        };
      }),
    };
  })()`);
}

function assertEnergyRadioactiveBacking(backing, label) {
  assert(Number.isInteger(backing.scaleX) && Number.isInteger(backing.scaleY)
      && backing.scaleX > 0 && backing.scaleY > 0,
  `${label}: backing does not preserve integral world scaling (${backing.scaleX}x${backing.scaleY})`);
  assert(backing.cards.length === 21 && backing.cards.every((card) => (
    card.bodySupported === card.bodyExpected
      && card.sparseSupported === card.sparseExpected
      && card.isolatedAlphaPeak > 0
  )), `${label}: energy/radioactive backing lost semantic support (${JSON.stringify(
    compactEnergyRadioactiveBacking(backing),
  )})`);
}

function compactEnergyRadioactiveBacking(backing) {
  return {
    scale: `${backing.scaleX}x${backing.scaleY}`,
    cards: backing.cards.map(({
      rgb: _rgb, liquidUnlikeRgb: _liquidUnlikeRgb, solidUnlikeRgb: _solidUnlikeRgb,
      width: _width, height: _height, ...card
    }) => card),
  };
}

function summarizeEnergyRadioactiveBackingResponses(flat, styled, repeated) {
  assert(flat.cards.length === 21 && styled.cards.length === 21 && repeated.cards.length === 21,
    'Energy/radioactive backing response atlas is incomplete');
  return flat.cards.map((base, cardIndex) => {
    const changed = styled.cards[cardIndex];
    const returned = repeated.cards[cardIndex];
    assert(changed.material === base.material && returned.material === base.material
        && changed.width === base.width && returned.width === base.width
        && changed.height === base.height && returned.height === base.height
        && changed.rgb.length === base.rgb.length && returned.rgb.length === base.rgb.length,
    `Exact material backing response geometry changed for ${base.code}`);
    let squared = 0;
    let rgbPeak = 0;
    let repeatRgbPeak = 0;
    let changedSamples = 0;
    let responseSignature = 2166136261;
    const buckets = new Float64Array(16);
    for (let offset = 0; offset < base.rgb.length; offset += 3) {
      const sample = offset / 3;
      const x = sample % base.width;
      const y = Math.floor(sample / base.width);
      const bucket = Math.min(3, Math.floor(y * 4 / base.height)) * 4
        + Math.min(3, Math.floor(x * 4 / base.width));
      let sampleChanged = false;
      for (let channel = 0; channel < 3; channel++) {
        const delta = changed.rgb[offset + channel] - base.rgb[offset + channel];
        const repeat = returned.rgb[offset + channel] - base.rgb[offset + channel];
        squared += delta * delta;
        rgbPeak = Math.max(rgbPeak, Math.abs(delta));
        repeatRgbPeak = Math.max(repeatRgbPeak, Math.abs(repeat));
        buckets[bucket] += Math.abs(delta);
        sampleChanged ||= delta !== 0;
        responseSignature = Math.imul(responseSignature ^ (delta + 255), 16777619) >>> 0;
      }
      changedSamples += Number(sampleChanged);
    }
    const total = Math.max(1, buckets.reduce((sum, value) => sum + value, 0));
    return {
      material: base.material,
      code: base.code,
      rgbRms: round(Math.sqrt(squared / Math.max(1, base.rgb.length)), 4),
      rgbPeak,
      changedSampleRatio: round(changedSamples / Math.max(1, base.width * base.height), 5),
      repeatRgbPeak,
      responseSignature,
      responseProfile: Array.from(buckets, (value) => round(value / total, 5)),
    };
  });
}

/** Paired exact-material, growth-topology, and RGB-identity proof for six native organics. */
async function auditOrganicPlantGraphics(cdp, mode) {
  const started = performance.now();
  const stage = (name) => console.error(
    `[organic-plant-graphics:${mode}] ${name} ${Math.round(performance.now() - started)}ms`,
  );
  const blank = await waitForStablePageCapture(
    cdp, `${mode} initial blank organic/plant framebuffer`,
  );
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.prepareOrganicPlantGraphicsFixture !== 'function'
      || typeof audit.organicPlantGraphicsAtlas !== 'function'
      || typeof audit.setBotanicalIdentityStyling !== 'function'
      || typeof audit.setUnusualPowderStyling !== 'function') {
      throw new Error('Organic/plant graphics audit API unavailable');
    }
    audit.prepareOrganicPlantGraphicsFixture();
    if (typeof audit.setPowderRenderStyle === 'function') audit.setPowderRenderStyle('smooth');
    return true;
  })()`);
  const rawAtlas = await waitFor(() => evaluate(cdp, `(() => {
    const atlas = window.__ANIFOR_INPUT_AUDIT__.organicPlantGraphicsAtlas();
    const cards = Array.isArray(atlas) ? atlas : atlas?.cards;
    return cards?.length === 6 ? atlas : false;
  })()`), 15_000, `${mode} organic/plant graphics fixture`);
  const atlas = normalizeOrganicPlantGraphicsAtlas(rawAtlas);
  const expectedMaterials = [9, 10, 50, 52, 83, 198];
  const expectedCodes = ['WOOD', 'PLNT', 'SEED', 'YEST', 'VINE', 'DYST'];
  assert(atlas.cards.length === 6 && atlas.solidCards.length === 3
      && atlas.powderCards.length === 3
      && atlas.nativeProductCards.map(({ code }) => code).join(',') === 'DYST'
      && atlas.cards.every(({ material, code }, index) => (
        material === expectedMaterials[index] && code === expectedCodes[index]
      )),
  `${mode}: organic/plant atlas contract changed (${JSON.stringify(atlas.cards.map(
    ({ code, material, phase, nativeProduct }) => ({ code, material, phase, nativeProduct }),
  ))})`);

  const semanticState = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const snapshot = audit.organicPlantGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const inside = (x, y, rect) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    return cards.map((entry) => {
      let bodyExact = true;
      for (let y = entry.body.y; y < entry.body.y + entry.body.height; y++) {
        for (let x = entry.body.x; x < entry.body.x + entry.body.width; x++) {
          const empty = inside(x, y, entry.authoredCavity) || inside(x, y, entry.openGap);
          bodyExact = bodyExact && audit.cell(x, y) === (empty ? 0 : entry.material);
        }
      }
      return {
        code: entry.code,
        material: entry.material,
        bodyExact,
        surfaceProbeExact: exactRect(entry.surfaceProbe, entry.material),
        coreProbeExact: exactRect(entry.coreProbe, entry.material),
        authoredCavityEmpty: exactRect(entry.authoredCavity, 0),
        openGapEmpty: exactRect(entry.openGap, 0),
        stemExact: exactRect(entry.stem, entry.material),
        branchesExact: entry.branches.every(
          (point) => audit.cell(point.x, point.y) === entry.material,
        ),
        leavesExact: entry.leaves.every(
          (point) => audit.cell(point.x, point.y) === entry.material,
        ),
        canopyGapEmpty: exactRect(entry.canopyGap, 0),
        isolated: audit.cell(entry.isolatedSeedProduct.x, entry.isolatedSeedProduct.y),
        guardedBlankEmpty: exactRect(entry.guardedBlank, 0),
        soilOwnerExact: exactRect(entry.soilContact.owner, entry.material),
        soilNeighbourExact: exactRect(
          entry.soilContact.neighbour, entry.soilContact.neighbourMaterial,
        ),
        soilNeighbourMaterial: entry.soilContact.neighbourMaterial,
        waterOwnerExact: exactRect(entry.waterContact.owner, entry.material),
        waterNeighbourExact: exactRect(
          entry.waterContact.neighbour, entry.waterContact.neighbourMaterial,
        ),
        waterNeighbourMaterial: entry.waterContact.neighbourMaterial,
      };
    });
  })()`);
  assert(semanticState.every((entry) => entry.bodyExact && entry.surfaceProbeExact
      && entry.coreProbeExact && entry.authoredCavityEmpty && entry.openGapEmpty
      && entry.stemExact && entry.branchesExact && entry.leavesExact
      && entry.canopyGapEmpty && entry.isolated === entry.material
      && entry.guardedBlankEmpty && entry.soilOwnerExact && entry.soilNeighbourExact
      && entry.soilNeighbourMaterial === 1 && entry.waterOwnerExact
      && entry.waterNeighbourExact && entry.waterNeighbourMaterial === 2),
  `${mode}: organic/plant fixture lost authored body/growth/gap/contact semantics (${JSON.stringify(semanticState)})`);
  stage('fixture-ready');

  const setOrganicIdentityStyling = async (enabled) => evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.setBotanicalIdentityStyling(${enabled});
    audit.setUnusualPowderStyling(${enabled});
    return true;
  })()`);
  await setOrganicIdentityStyling(false);
  const flat = await waitForStablePageCapture(cdp, `${mode} flat organic/plant framebuffer`);
  const flatBacking = await sampleOrganicPlantBacking(cdp);
  await setOrganicIdentityStyling(true);
  const styled = await waitForStablePageCapture(cdp, `${mode} styled organic/plant framebuffer`);
  const styledBacking = await sampleOrganicPlantBacking(cdp);
  await setOrganicIdentityStyling(false);
  const repeated = await waitForStablePageCapture(
    cdp, `${mode} repeated flat organic/plant framebuffer`,
  );
  const repeatedBacking = await sampleOrganicPlantBacking(cdp);
  for (const [state, backing] of [
    ['flat', flatBacking], ['styled', styledBacking], ['repeated-flat', repeatedBacking],
  ]) assertOrganicPlantBacking(backing, `${mode} ${state}`);

  assert(flatBacking.cards.every((card, index) => (
    card.semanticSignature === styledBacking.cards[index].semanticSignature
      && card.semanticSignature === repeatedBacking.cards[index].semanticSignature
      && card.alphaSignature === styledBacking.cards[index].alphaSignature
      && card.alphaSignature === repeatedBacking.cards[index].alphaSignature
      && card.supportSignature === styledBacking.cards[index].supportSignature
      && card.supportSignature === repeatedBacking.cards[index].supportSignature
  )), `${mode}: organic identity styling changed semantics/alpha/support (${JSON.stringify({
    flat: compactOrganicPlantBacking(flatBacking),
    styled: compactOrganicPlantBacking(styledBacking),
    repeated: compactOrganicPlantBacking(repeatedBacking),
  })})`);
  const controlLeaks = flatBacking.cards.flatMap((card, index) => {
    const changed = styledBacking.cards[index];
    const returned = repeatedBacking.cards[index];
    const leaks = [];
    if (!arraysEqual(card.soilNeighbourRgb, changed.soilNeighbourRgb)
      || !arraysEqual(card.soilNeighbourRgb, returned.soilNeighbourRgb)) leaks.push('Sand');
    if (!arraysEqual(card.waterNeighbourRgb, changed.waterNeighbourRgb)
      || !arraysEqual(card.waterNeighbourRgb, returned.waterNeighbourRgb)) leaks.push('Water');
    return leaks.map((control) => ({ code: card.code, control }));
  });
  assert(controlLeaks.length === 0,
    `${mode}: organic identity styling leaked into contact controls (${JSON.stringify(controlLeaks)})`);

  const backingResponses = summarizeOrganicPlantBackingResponses(
    flatBacking, styledBacking, repeatedBacking,
  );
  assert(backingResponses.every(({
    rgbRms, rgbPeak, changedSampleRatio, growthRgbRms, growthChangedSampleRatio, repeatRgbPeak,
  }) => (
    rgbRms >= 0.02 && rgbRms <= 32 && rgbPeak > 0 && rgbPeak <= 96
      && changedSampleRatio >= 0.002 && growthRgbRms > 0
      && growthChangedSampleRatio > 0 && repeatRgbPeak === 0
  )), `${mode}: organic identity response is absent, unbounded, or non-repeatable (${JSON.stringify(backingResponses)})`);
  assert(new Set(backingResponses.map(({ responseSignature }) => responseSignature)).size === 6,
    `${mode}: organic materials do not have six distinct identity signatures (${JSON.stringify(backingResponses)})`);
  assert(backingResponses.every(({ responseProfile }) => responseProfile.length === 16
      && Math.abs(responseProfile.reduce((sum, value) => sum + value, 0) - 1) <= 0.001),
  `${mode}: organic response profiles are not normalized 4x4 fields (${JSON.stringify(backingResponses)})`);

  const bodyRegions = atlas.cards.map((entry) => ({
    name: `organic-identity-${entry.code}`,
    x: entry.body.x + entry.body.width / 2,
    y: entry.body.y + entry.body.height / 2,
    radiusX: entry.body.width / 2,
    radiusY: entry.body.height / 2,
    signature: true,
    silhouette: true,
    fastSupport: true,
  }));
  const atlasBounds = containingCellularRegion(atlas.cards.map(({ card }) => card));
  const responses = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: styled.capture.data,
    repeatedStraight: repeated.capture.data,
  }, [...bodyRegions, { name: 'organic-plant-atlas', ...atlasBounds }], flat.canvasRect);
  const atlasResponse = responses.at(-1);
  assert(atlasResponse.repeatRgbPeak === 0,
    `${mode}: organic flat→styled→flat framebuffer was not exact (${JSON.stringify(atlasResponse)})`);
  assert(responses.slice(0, 6).every((sample) => sample.rgbRms > 0
      && sample.rgbRms <= 40 && sample.rgbPeak > 0 && sample.rgbPeak <= 128
      && sample.repeatRgbPeak === 0),
  `${mode}: an organic material has no bounded composed response (${JSON.stringify(responses.slice(0, 6))})`);
  const [flatSupport, styledSupport] = await Promise.all([
    samplePageRegions(
      cdp, flat.capture.data, bodyRegions,
      blank.capture.data, blank.reference.data, flat.canvasRect,
    ),
    samplePageRegions(
      cdp, styled.capture.data, bodyRegions,
      blank.capture.data, blank.reference.data, flat.canvasRect,
    ),
  ]);
  assert(flatSupport.every((sample) => sample.visible > 0 && sample.worldArea > 0)
      && styledSupport.every((sample) => sample.visible > 0 && sample.worldArea > 0),
  `${mode}: an organic material body is not visible (${JSON.stringify({ flatSupport, styledSupport })})`);
  stage('responses-ready');

  return {
    cards: atlas.cards.length,
    solidCards: atlas.solidCards.length,
    powderCards: atlas.powderCards.length,
    nativeProducts: atlas.nativeProductCards.map(({ code }) => code),
    authoredCavityCells: atlas.cavities.length,
    openGapCells: atlas.openGaps.length,
    growthTopologyCells: atlas.growthTopology.length,
    canopyGaps: atlas.canopyGaps.length,
    isolatedProducts: atlas.isolatedSeedProducts.length,
    guardedBlanks: atlas.guardedBlanks.length,
    sandContacts: atlas.soilContacts.length,
    waterContacts: atlas.waterContacts.length,
    exactRepeatedOff: atlasResponse.repeatRgbPeak === 0,
    cardSignatures: atlas.cards.map((entry, index) => ({
      index: entry.index,
      material: entry.material,
      code: entry.code,
      flatSignature: flatSupport[index].signature,
      styledSignature: styledSupport[index].signature,
      rgbRms: responses[index].rgbRms,
      rgbPeak: responses[index].rgbPeak,
      backingRgbRms: backingResponses[index].rgbRms,
      backingRgbPeak: backingResponses[index].rgbPeak,
      backingChangedSampleRatio: backingResponses[index].changedSampleRatio,
      growthRgbRms: backingResponses[index].growthRgbRms,
      growthChangedSampleRatio: backingResponses[index].growthChangedSampleRatio,
      backingRepeatRgbPeak: backingResponses[index].repeatRgbPeak,
      backingResponseSignature: backingResponses[index].responseSignature,
      backingResponseProfile: backingResponses[index].responseProfile,
    })),
  };
}

async function sampleOrganicPlantBacking(cdp) {
  return evaluate(cdp, `(() => {
    const world = document.querySelector('.world-canvas');
    if (!(world instanceof HTMLCanvasElement)) throw new Error('World canvas unavailable');
    const copy = document.createElement('canvas');
    copy.width = world.width;
    copy.height = world.height;
    const context = copy.getContext('2d', { willReadFrequently: true });
    if (!context) throw new Error('Organic/plant backing sampler unavailable');
    context.drawImage(world, 0, 0);
    const pixels = context.getImageData(0, 0, copy.width, copy.height).data;
    const scaleX = copy.width / ${WORLD_WIDTH};
    const scaleY = copy.height / ${WORLD_HEIGHT};
    const rectPoints = (rect) => {
      const points = [];
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) points.push({ x, y });
      }
      return points;
    };
    const cellAlpha = ({ x, y }) => {
      const left = Math.floor(x * scaleX);
      const top = Math.floor(y * scaleY);
      const right = Math.max(left + 1, Math.floor((x + 1) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((y + 1) * scaleY));
      let minimum = 255;
      let peak = 0;
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        const alpha = pixels[(py * copy.width + px) * 4 + 3];
        minimum = Math.min(minimum, alpha);
        peak = Math.max(peak, alpha);
      }
      return { minimum, peak };
    };
    const sampleRect = (rect, includeAlpha = false) => {
      const left = Math.floor(rect.x * scaleX);
      const top = Math.floor(rect.y * scaleY);
      const right = Math.max(left + 1, Math.floor((rect.x + rect.width) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((rect.y + rect.height) * scaleY));
      const rgb = [];
      const alpha = [];
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        const offset = (py * copy.width + px) * 4;
        rgb.push(pixels[offset], pixels[offset + 1], pixels[offset + 2]);
        if (includeAlpha) alpha.push(pixels[offset + 3]);
      }
      return { width: right - left, height: bottom - top, rgb, alpha };
    };
    const samplePointRgb = (points) => {
      const rgb = [];
      for (const { x, y } of points) {
        const px = Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX));
        const py = Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY));
        const offset = (py * copy.width + px) * 4;
        rgb.push(pixels[offset], pixels[offset + 1], pixels[offset + 2]);
      }
      return rgb;
    };
    const snapshot = window.__ANIFOR_INPUT_AUDIT__.organicPlantGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    return {
      width: copy.width,
      height: copy.height,
      scaleX,
      scaleY,
      cards: cards.map((entry) => {
        const key = ({ x, y }) => x + ',' + y;
        const cavityPoints = rectPoints(entry.authoredCavity);
        const openGapPoints = rectPoints(entry.openGap);
        const emptyKeys = new Set([...cavityPoints, ...openGapPoints].map(key));
        const bodyPoints = rectPoints(entry.body).filter((point) => !emptyKeys.has(key(point)));
        const growthPoints = [...rectPoints(entry.stem), ...entry.branches, ...entry.leaves];
        const canopyGapPoints = rectPoints(entry.canopyGap);
        const guardPoints = rectPoints(entry.guardedBlank);
        const soilOwner = rectPoints(entry.soilContact.owner);
        const soilNeighbour = rectPoints(entry.soilContact.neighbour);
        const waterOwner = rectPoints(entry.waterContact.owner);
        const waterNeighbour = rectPoints(entry.waterContact.neighbour);
        const cardPixels = sampleRect(entry.card, true);
        let semanticSignature = 2166136261;
        for (let y = entry.card.y; y < entry.card.y + entry.card.height; y++) {
          for (let x = entry.card.x; x < entry.card.x + entry.card.width; x++) {
            semanticSignature = Math.imul(
              semanticSignature ^ window.__ANIFOR_INPUT_AUDIT__.cell(x, y), 16777619,
            ) >>> 0;
          }
        }
        let alphaSignature = 2166136261;
        let supportSignature = 2166136261;
        for (const alpha of cardPixels.alpha) {
          alphaSignature = Math.imul(alphaSignature ^ alpha, 16777619) >>> 0;
          supportSignature = Math.imul(supportSignature ^ Number(alpha > 0), 16777619) >>> 0;
        }
        const body = sampleRect(entry.body);
        return {
          index: entry.index,
          material: entry.material,
          code: entry.code,
          phase: entry.phase,
          bodyExpected: bodyPoints.length,
          bodySupported: bodyPoints.filter((point) => cellAlpha(point).peak > 0).length,
          cavityExpected: cavityPoints.length,
          cavityTransparent: cavityPoints.filter((point) => cellAlpha(point).peak === 0).length,
          openGapExpected: openGapPoints.length,
          openGapOpen: openGapPoints.filter((point) => cellAlpha(point).minimum === 0).length,
          growthExpected: growthPoints.length,
          growthSupported: growthPoints.filter((point) => cellAlpha(point).peak > 0).length,
          canopyGapExpected: canopyGapPoints.length,
          canopyGapTransparent: canopyGapPoints.filter((point) => cellAlpha(point).peak === 0).length,
          isolatedAlphaPeak: cellAlpha(entry.isolatedSeedProduct).peak,
          guardedBlankExpected: guardPoints.length,
          guardedBlankTransparent: guardPoints.filter((point) => cellAlpha(point).peak === 0).length,
          soilOwnerExpected: soilOwner.length,
          soilOwnerSupported: soilOwner.filter((point) => cellAlpha(point).peak > 0).length,
          waterOwnerExpected: waterOwner.length,
          waterOwnerSupported: waterOwner.filter((point) => cellAlpha(point).peak > 0).length,
          semanticSignature,
          alphaSignature,
          supportSignature,
          width: body.width,
          height: body.height,
          rgb: body.rgb,
          growthRgb: samplePointRgb(growthPoints),
          soilNeighbourRgb: samplePointRgb(soilNeighbour),
          waterNeighbourRgb: samplePointRgb(waterNeighbour),
        };
      }),
    };
  })()`);
}

function assertOrganicPlantBacking(backing, label) {
  assert(Number.isInteger(backing.scaleX) && Number.isInteger(backing.scaleY)
      && backing.scaleX > 0 && backing.scaleY > 0,
  `${label}: backing does not preserve integral world scaling (${backing.scaleX}x${backing.scaleY})`);
  assert(backing.cards.length === 6 && backing.cards.every((card) => (
    card.bodySupported === card.bodyExpected
      && card.cavityTransparent === card.cavityExpected
      && card.openGapOpen === card.openGapExpected
      && card.growthSupported === card.growthExpected
      && card.canopyGapTransparent === card.canopyGapExpected
      && card.isolatedAlphaPeak > 0
      && card.guardedBlankTransparent === card.guardedBlankExpected
      && card.soilOwnerSupported === card.soilOwnerExpected
      && card.waterOwnerSupported === card.waterOwnerExpected
  )), `${label}: organic backing changed body/cavity/gap/growth/blank/contact topology (${JSON.stringify(
    compactOrganicPlantBacking(backing),
  )})`);
}

function compactOrganicPlantBacking(backing) {
  return {
    scale: `${backing.scaleX}x${backing.scaleY}`,
    cards: backing.cards.map(({
      rgb: _rgb, growthRgb: _growthRgb, soilNeighbourRgb: _soilNeighbourRgb,
      waterNeighbourRgb: _waterNeighbourRgb, width: _width, height: _height, ...card
    }) => card),
  };
}

function summarizeOrganicPlantBackingResponses(flat, styled, repeated) {
  assert(flat.cards.length === 6 && styled.cards.length === 6 && repeated.cards.length === 6,
    'Organic/plant backing response atlas is incomplete');
  return flat.cards.map((base, cardIndex) => {
    const changed = styled.cards[cardIndex];
    const returned = repeated.cards[cardIndex];
    assert(changed.material === base.material && returned.material === base.material
        && changed.width === base.width && returned.width === base.width
        && changed.height === base.height && returned.height === base.height
        && changed.rgb.length === base.rgb.length && returned.rgb.length === base.rgb.length
        && changed.growthRgb.length === base.growthRgb.length
        && returned.growthRgb.length === base.growthRgb.length,
    `Organic/plant backing response geometry changed for ${base.code}`);
    let squared = 0;
    let rgbPeak = 0;
    let repeatRgbPeak = 0;
    let changedSamples = 0;
    let responseSignature = 2166136261;
    const buckets = new Float64Array(16);
    for (let offset = 0; offset < base.rgb.length; offset += 3) {
      const sample = offset / 3;
      const x = sample % base.width;
      const y = Math.floor(sample / base.width);
      const bucket = Math.min(3, Math.floor(y * 4 / base.height)) * 4
        + Math.min(3, Math.floor(x * 4 / base.width));
      let sampleChanged = false;
      for (let channel = 0; channel < 3; channel++) {
        const delta = changed.rgb[offset + channel] - base.rgb[offset + channel];
        const repeat = returned.rgb[offset + channel] - base.rgb[offset + channel];
        squared += delta * delta;
        rgbPeak = Math.max(rgbPeak, Math.abs(delta));
        repeatRgbPeak = Math.max(repeatRgbPeak, Math.abs(repeat));
        buckets[bucket] += Math.abs(delta);
        sampleChanged ||= delta !== 0;
        responseSignature = Math.imul(responseSignature ^ (delta + 255), 16777619) >>> 0;
      }
      changedSamples += Number(sampleChanged);
    }
    let growthSquared = 0;
    let growthChangedSamples = 0;
    for (let offset = 0; offset < base.growthRgb.length; offset += 3) {
      let sampleChanged = false;
      for (let channel = 0; channel < 3; channel++) {
        const delta = changed.growthRgb[offset + channel] - base.growthRgb[offset + channel];
        const repeat = returned.growthRgb[offset + channel] - base.growthRgb[offset + channel];
        growthSquared += delta * delta;
        repeatRgbPeak = Math.max(repeatRgbPeak, Math.abs(repeat));
        sampleChanged ||= delta !== 0;
      }
      growthChangedSamples += Number(sampleChanged);
    }
    const total = Math.max(1, buckets.reduce((sum, value) => sum + value, 0));
    return {
      material: base.material,
      code: base.code,
      rgbRms: round(Math.sqrt(squared / Math.max(1, base.rgb.length)), 4),
      rgbPeak,
      changedSampleRatio: round(changedSamples / Math.max(1, base.width * base.height), 5),
      growthRgbRms: round(Math.sqrt(growthSquared / Math.max(1, base.growthRgb.length)), 4),
      growthChangedSampleRatio: round(
        growthChangedSamples / Math.max(1, base.growthRgb.length / 3), 5,
      ),
      repeatRgbPeak,
      responseSignature,
      responseProfile: Array.from(buckets, (value) => round(value / total, 5)),
    };
  });
}

/** Focused semantic, topology, and paired porous-volume proof for SPNG. */
async function auditSpongeGraphics(cdp, mode) {
  const started = performance.now();
  const stage = (name) => console.error(
    `[sponge-graphics:${mode}] ${name} ${Math.round(performance.now() - started)}ms`,
  );
  const blank = await waitForStablePageCapture(cdp, `${mode} initial blank SPNG framebuffer`);
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.prepareSpongeGraphicsFixture !== 'function'
      || typeof audit.spongeGraphicsAtlas !== 'function'
      || typeof audit.setUnusualSolidStyling !== 'function') {
      throw new Error('SPNG graphics audit API unavailable');
    }
    audit.prepareSpongeGraphicsFixture();
    return true;
  })()`);
  const rawAtlas = await waitFor(() => evaluate(cdp, `(() => {
    const atlas = window.__ANIFOR_INPUT_AUDIT__.spongeGraphicsAtlas();
    const cards = Array.isArray(atlas) ? atlas : atlas?.cards;
    return cards?.length === 1 ? atlas : false;
  })()`), 15_000, `${mode} SPNG graphics fixture`);
  const atlas = normalizeSpongeGraphicsAtlas(rawAtlas);
  assert(atlas.cards.length === 1 && atlas.cards[0].material === 81
      && atlas.cards[0].code === 'SPNG' && atlas.holes.length === 232
      && atlas.openNotches.length === 208 && atlas.fineStructures.length === 344
      && atlas.contacts.length === 3 && atlas.porePairs.length === 271,
  `${mode}: SPNG atlas contract changed (${JSON.stringify({
    cards: atlas.cards.map(({ code, material }) => ({ code, material })),
    holes: atlas.holes.length,
    openNotches: atlas.openNotches.length,
    fineStructures: atlas.fineStructures.length,
    contacts: atlas.contacts.length,
    porePairs: atlas.porePairs.length,
  })})`);

  const semanticState = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const snapshot = audit.spongeGraphicsAtlas();
    const entry = (Array.isArray(snapshot) ? snapshot : snapshot.cards)[0];
    const inside = (x, y, rect) => x >= rect.x && y >= rect.y
      && x < rect.x + rect.width && y < rect.y + rect.height;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    let bodyExact = true;
    for (let y = entry.body.y; y < entry.body.y + entry.body.height; y++) {
      for (let x = entry.body.x; x < entry.body.x + entry.body.width; x++) {
        const empty = entry.holes.some((rect) => inside(x, y, rect))
          || entry.openNotches.some((rect) => inside(x, y, rect));
        bodyExact = bodyExact && audit.cell(x, y) === (empty ? 0 : entry.material);
      }
    }
    return {
      bodyExact,
      surfaceProbeExact: exactRect(entry.surfaceProbe, entry.material),
      coreProbeExact: exactRect(entry.coreProbe, entry.material),
      holesEmpty: entry.holes.every((rect) => exactRect(rect, 0)),
      openNotchesEmpty: entry.openNotches.every((rect) => exactRect(rect, 0)),
      ribsExact: entry.ribs.every((rect) => exactRect(rect, entry.material)),
      isolated: audit.cell(entry.isolated.x, entry.isolated.y),
      guardedBlankEmpty: exactRect(entry.guardedBlank, 0),
      contacts: entry.contacts.map((contact) => ({
        ownerExact: exactRect(contact.owner, entry.material),
        neighbourExact: exactRect(contact.neighbour, contact.neighbourMaterial),
        neighbourMaterial: contact.neighbourMaterial,
        abuts: contact.owner.x + contact.owner.width === contact.neighbour.x
          && contact.owner.y === contact.neighbour.y
          && contact.owner.height === contact.neighbour.height,
      })),
    };
  })()`);
  assert(semanticState.bodyExact && semanticState.surfaceProbeExact
      && semanticState.coreProbeExact && semanticState.holesEmpty
      && semanticState.openNotchesEmpty && semanticState.ribsExact
      && semanticState.isolated === 81 && semanticState.guardedBlankEmpty
      && semanticState.contacts.length === 3
      && semanticState.contacts.every((contact, index) => contact.ownerExact
        && contact.neighbourExact && contact.abuts
        && contact.neighbourMaterial === [2, 23, 1][index]),
  `${mode}: SPNG fixture lost authored body/hole/notch/rib/contact semantics (${JSON.stringify(semanticState)})`);
  stage('fixture-ready');

  const setSpongeStyling = async (enabled) => evaluate(
    cdp, `window.__ANIFOR_INPUT_AUDIT__.setUnusualSolidStyling(${enabled}); true`,
  );
  await setSpongeStyling(false);
  const flat = await waitForStablePageCapture(cdp, `${mode} flat SPNG framebuffer`);
  const flatBacking = await sampleSpongeBacking(cdp);
  await setSpongeStyling(true);
  const styled = await waitForStablePageCapture(cdp, `${mode} styled SPNG framebuffer`);
  const styledBacking = await sampleSpongeBacking(cdp);
  await setSpongeStyling(false);
  const repeated = await waitForStablePageCapture(cdp, `${mode} repeated flat SPNG framebuffer`);
  const repeatedBacking = await sampleSpongeBacking(cdp);
  for (const [state, backing] of [
    ['flat', flatBacking], ['styled', styledBacking], ['repeated-flat', repeatedBacking],
  ]) assertSpongeBacking(backing, `${mode} ${state}`);

  assert(flatBacking.semanticSignature === styledBacking.semanticSignature
      && flatBacking.semanticSignature === repeatedBacking.semanticSignature
      && flatBacking.alphaSignature === styledBacking.alphaSignature
      && flatBacking.alphaSignature === repeatedBacking.alphaSignature
      && flatBacking.supportSignature === styledBacking.supportSignature
      && flatBacking.supportSignature === repeatedBacking.supportSignature,
  `${mode}: SPNG identity styling changed semantic/alpha/support signatures (${JSON.stringify({
    flat: compactSpongeBacking(flatBacking),
    styled: compactSpongeBacking(styledBacking),
    repeated: compactSpongeBacking(repeatedBacking),
  })})`);
  assert(flatBacking.contacts.every((contact, index) => (
    arraysEqual(contact.neighbourRgb, styledBacking.contacts[index].neighbourRgb)
      && arraysEqual(contact.neighbourRgb, repeatedBacking.contacts[index].neighbourRgb)
  )), `${mode}: SPNG styling leaked into Water/Metal/Sand contact controls`);

  const backingResponse = summarizeSpongeBackingResponse(
    flatBacking, styledBacking, repeatedBacking,
  );
  assert(backingResponse.rgbRms >= 0.20 && backingResponse.rgbRms <= 18
      && backingResponse.rgbPeak > 0 && backingResponse.rgbPeak <= 40
      && backingResponse.changedSampleRatio >= 0.05
      && backingResponse.changedSampleRatio <= 0.80
      && backingResponse.surfaceRgbRms > 0 && backingResponse.coreRgbRms > 0
      && (mode === 'webgl' || backingResponse.ribRgbRms > 0)
      && backingResponse.contactOwnerRgbRms.every((value) => value > 0)
      && backingResponse.repeatRgbPeak === 0,
  `${mode}: SPNG response is absent, unbounded, localized incorrectly, or non-repeatable (${JSON.stringify(backingResponse)})`);
  assert(backingResponse.porePairPassRatio >= 0.70
      && backingResponse.poreContrastMean >= 1.5,
  `${mode}: SPNG lost recessed-core/lit-rim pore relief (${JSON.stringify(backingResponse)})`);
  assert(backingResponse.responseProfile.length === 16
      && Math.abs(backingResponse.responseProfile.reduce((sum, value) => sum + value, 0) - 1) <= 0.001,
  `${mode}: SPNG response profile is not a normalized 4x4 field (${JSON.stringify(backingResponse)})`);

  const bodyRegion = {
    name: 'sponge-normal-fit-body',
    x: atlas.cards[0].body.x + atlas.cards[0].body.width / 2,
    y: atlas.cards[0].body.y + atlas.cards[0].body.height / 2,
    radiusX: atlas.cards[0].body.width / 2,
    radiusY: atlas.cards[0].body.height / 2,
    signature: true,
    silhouette: true,
    fastSupport: true,
  };
  const [normalFitResponse] = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: styled.capture.data,
    repeatedStraight: repeated.capture.data,
  }, [bodyRegion], flat.canvasRect);
  assert(normalFitResponse.rgbRms > 0 && normalFitResponse.rgbRms <= 24
      && normalFitResponse.rgbPeak > 0 && normalFitResponse.rgbPeak <= 64
      && normalFitResponse.repeatRgbPeak === 0,
  `${mode}: SPNG has no bounded exact response at normal fit (${JSON.stringify(normalFitResponse)})`);
  const [flatSupport, styledSupport] = await Promise.all([
    samplePageRegions(
      cdp, flat.capture.data, [bodyRegion],
      blank.capture.data, blank.reference.data, flat.canvasRect,
    ),
    samplePageRegions(
      cdp, styled.capture.data, [bodyRegion],
      blank.capture.data, blank.reference.data, flat.canvasRect,
    ),
  ]);
  assert(flatSupport[0].visible > 0 && flatSupport[0].worldArea > 0
      && styledSupport[0].visible > 0 && styledSupport[0].worldArea > 0,
  `${mode}: SPNG body is not visible at normal fit (${JSON.stringify({ flatSupport, styledSupport })})`);
  stage('responses-ready');

  return {
    cards: atlas.cards.length,
    material: atlas.cards[0].material,
    holeCells: atlas.holes.length,
    openNotchCells: atlas.openNotches.length,
    fineStructureCells: atlas.fineStructures.length,
    isolatedControls: 1,
    contacts: atlas.contacts.map(({ neighbourMaterial }) => neighbourMaterial),
    porePairs: atlas.porePairs.length,
    exactRepeatedOff: normalFitResponse.repeatRgbPeak === 0,
    normalFitRgbRms: normalFitResponse.rgbRms,
    normalFitRgbPeak: normalFitResponse.rgbPeak,
    backingRgbRms: backingResponse.rgbRms,
    backingRgbPeak: backingResponse.rgbPeak,
    backingChangedSampleRatio: backingResponse.changedSampleRatio,
    backingRepeatRgbPeak: backingResponse.repeatRgbPeak,
    surfaceRgbRms: backingResponse.surfaceRgbRms,
    coreRgbRms: backingResponse.coreRgbRms,
    ribRgbRms: backingResponse.ribRgbRms,
    contactOwnerRgbRms: backingResponse.contactOwnerRgbRms,
    porePairPassRatio: backingResponse.porePairPassRatio,
    poreContrastMean: backingResponse.poreContrastMean,
    backingResponseProfile: backingResponse.responseProfile,
    supportSignature: flatBacking.supportSignature,
  };
}

async function auditVirusGraphics(cdp, mode) {
  const started = performance.now();
  const stage = (name) => console.error(
    `[virus-graphics:${mode}] ${name} ${Math.round(performance.now() - started)}ms`,
  );
  const blank = await waitForStablePageCapture(cdp, `${mode} initial blank virus framebuffer`);
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.prepareVirusGraphicsFixture !== 'function'
      || typeof audit.virusGraphicsAtlas !== 'function'
      || typeof audit.setLiquidIdentityStyling !== 'function'
      || typeof audit.setGasIdentityStyling !== 'function'
      || typeof audit.setUnusualSolidStyling !== 'function') {
      throw new Error('Virus graphics audit API unavailable');
    }
    audit.prepareVirusGraphicsFixture();
    return true;
  })()`);
  const rawAtlas = await waitFor(() => evaluate(cdp, `(() => {
    const atlas = window.__ANIFOR_INPUT_AUDIT__.virusGraphicsAtlas();
    const cards = Array.isArray(atlas) ? atlas : atlas?.cards;
    return cards?.length === 3 ? atlas : false;
  })()`), 15_000, `${mode} virus graphics fixture`);
  const atlas = normalizeVirusGraphicsAtlas(rawAtlas);
  assert(atlas.cards.map(({ material }) => material).join(',') === '62,215,216'
      && atlas.cards.map(({ code }) => code).join(',') === 'VIRS,VRSG,VRSS'
      && atlas.cards.map(({ phase }) => phase).join(',') === 'liquid,gas,solid'
      && atlas.cards.every(({ body }) => body.width === 112 && body.height === 112)
      && atlas.cards.every(({ motifProbes }) => motifProbes.length >= 35),
  `${mode}: virus atlas contract changed (${JSON.stringify(atlas.cards.map((entry) => ({
    material: entry.material, code: entry.code, phase: entry.phase,
    body: entry.body, motifProbes: entry.motifProbes.length,
  })))})`);

  const semanticState = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const snapshot = audit.virusGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const inside = (x, y, rect) => x >= rect.x && y >= rect.y
      && x < rect.x + rect.width && y < rect.y + rect.height;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    return cards.map((entry) => {
      let bodyExact = true;
      for (let y = entry.body.y; y < entry.body.y + entry.body.height; y++) {
        for (let x = entry.body.x; x < entry.body.x + entry.body.width; x++) {
          const empty = inside(x, y, entry.authoredCavity) || inside(x, y, entry.openChimney);
          bodyExact = bodyExact && audit.cell(x, y) === (empty ? 0 : entry.material);
        }
      }
      return {
        material: entry.material,
        bodyExact,
        cavityEmpty: exactRect(entry.authoredCavity, 0),
        chimneyEmpty: exactRect(entry.openChimney, 0),
        structureExact: entry.phaseStructure.every(({ x, y }) => audit.cell(x, y) === entry.material),
        isolated: audit.cell(entry.isolated.x, entry.isolated.y),
        guardedBlankEmpty: exactRect(entry.guardedBlank, 0),
        waterOwnerExact: exactRect(entry.waterContact.owner, entry.material),
        waterExact: exactRect(entry.waterContact.neighbour, entry.waterContact.neighbourMaterial),
        metalOwnerExact: exactRect(entry.metalContact.owner, entry.material),
        metalExact: exactRect(entry.metalContact.neighbour, entry.metalContact.neighbourMaterial),
        gasStyle: entry.material === 215
          ? audit.gasIdentityStyle(entry.body.x + 20, entry.body.y + 20) : 0,
      };
    });
  })()`);
  assert(semanticState.every((entry) => entry.bodyExact && entry.cavityEmpty
      && entry.chimneyEmpty && entry.structureExact && entry.isolated === entry.material
      && entry.guardedBlankEmpty && entry.waterOwnerExact && entry.waterExact
      && entry.metalOwnerExact && entry.metalExact)
      && semanticState[1].gasStyle === 17,
  `${mode}: virus fixture lost phase semantics, topology, contacts, or VRSG identity (${JSON.stringify(semanticState)})`);
  stage('fixture-ready');

  const setVirusStyling = async (enabled) => evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.setLiquidIdentityStyling(${enabled});
    audit.setGasIdentityStyling(${enabled});
    audit.setUnusualSolidStyling(${enabled});
    return true;
  })()`);
  await setVirusStyling(false);
  const flat = await waitForStablePageCapture(cdp, `${mode} flat virus framebuffer`);
  const flatBacking = await sampleVirusBacking(cdp);
  await setVirusStyling(true);
  const styled = await waitForStablePageCapture(cdp, `${mode} styled virus framebuffer`);
  const styledBacking = await sampleVirusBacking(cdp);
  await setVirusStyling(false);
  const repeated = await waitForStablePageCapture(cdp, `${mode} repeated flat virus framebuffer`);
  const repeatedBacking = await sampleVirusBacking(cdp);
  for (const [state, backing] of [
    ['flat', flatBacking], ['styled', styledBacking], ['repeated-flat', repeatedBacking],
  ]) assertVirusBacking(backing, `${mode} ${state}`);

  for (let index = 0; index < 3; index++) {
    const flatCard = flatBacking.cards[index];
    const styledCard = styledBacking.cards[index];
    const repeatedCard = repeatedBacking.cards[index];
    assert(flatCard.semanticSignature === styledCard.semanticSignature
        && flatCard.semanticSignature === repeatedCard.semanticSignature
        && flatCard.alphaSignature === styledCard.alphaSignature
        && flatCard.alphaSignature === repeatedCard.alphaSignature
        && flatCard.supportSignature === styledCard.supportSignature
        && flatCard.supportSignature === repeatedCard.supportSignature,
    `${mode}: ${flatCard.code} styling changed semantic/alpha/support signatures`);
    for (const contactName of ['waterContact', 'metalContact']) {
      assert(arraysEqual(flatCard[contactName].neighbourRgb, styledCard[contactName].neighbourRgb)
          && arraysEqual(flatCard[contactName].neighbourRgb, repeatedCard[contactName].neighbourRgb),
      `${mode}: ${flatCard.code} styling leaked into ${contactName}`);
    }
  }

  const responses = summarizeVirusBackingResponses(flatBacking, styledBacking, repeatedBacking);
  for (const response of responses) {
    assert(response.rgbRms >= 0.03 && response.rgbRms <= 24
        && response.rgbPeak > 0 && response.rgbPeak <= 64
        && response.changedSampleRatio >= 0.015 && response.changedSampleRatio <= 1
        && response.repeatRgbPeak === 0
        && response.profile.length === 16
        && Math.abs(response.profile.reduce((sum, value) => sum + value, 0) - 1) <= 0.001,
    `${mode}: ${response.code} family response is absent, unbounded, or non-repeatable (${JSON.stringify(response)})`);
    assert(response.motifAxis.attachment > response.motifAxis.interstitial + 0.35
        && response.motifAxis.membrane > response.motifAxis.interstitial + 0.20,
    `${mode}: ${response.code} lost membrane/node virus-axis ordering (${JSON.stringify(response.motifAxis)})`);
  }
  const phaseCorrelations = [
    virusPearson(responses[0].axisMap, responses[1].axisMap),
    virusPearson(responses[0].axisMap, responses[2].axisMap),
    virusPearson(responses[1].axisMap, responses[2].axisMap),
  ];
  assert(phaseCorrelations.every((value) => value >= 0.42),
    `${mode}: virus phases do not retain one spatial grammar (${JSON.stringify(phaseCorrelations)})`);

  const normalFitRegions = atlas.cards.map((entry) => ({
    name: `${entry.code}-normal-fit-body`,
    x: entry.body.x + entry.body.width / 2,
    y: entry.body.y + entry.body.height / 2,
    radiusX: entry.body.width / 2,
    radiusY: entry.body.height / 2,
    signature: true,
    silhouette: true,
    fastSupport: true,
  }));
  const normalFit = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: styled.capture.data,
    repeatedStraight: repeated.capture.data,
  }, normalFitRegions, flat.canvasRect);
  assert(normalFit.every((response) => response.rgbRms > 0 && response.rgbRms <= 32
      && response.rgbPeak > 0 && response.rgbPeak <= 64 && response.repeatRgbPeak === 0),
  `${mode}: virus family is absent, unbounded, or unstable at normal fit (${JSON.stringify(normalFit)})`);
  stage('responses-ready');

  return {
    cards: responses.map((response, index) => ({
      code: response.code,
      material: response.material,
      phase: atlas.cards[index].phase,
      rgbRms: response.rgbRms,
      rgbPeak: response.rgbPeak,
      changedSampleRatio: response.changedSampleRatio,
      repeatRgbPeak: response.repeatRgbPeak,
      motifAxis: response.motifAxis,
      profile: response.profile,
      axisMap: response.axisMap,
      normalFitRgbRms: normalFit[index].rgbRms,
      normalFitRgbPeak: normalFit[index].rgbPeak,
    })),
    phaseCorrelations,
    exactRepeatedOff: responses.every(({ repeatRgbPeak }) => repeatRgbPeak === 0),
    supportSignatures: flatBacking.cards.map(({ supportSignature }) => supportSignature),
  };
}

async function sampleVirusBacking(cdp) {
  return evaluate(cdp, `(() => {
    const world = document.querySelector('.world-canvas');
    if (!(world instanceof HTMLCanvasElement)) throw new Error('World canvas unavailable');
    const copy = document.createElement('canvas');
    copy.width = world.width;
    copy.height = world.height;
    const context = copy.getContext('2d', { willReadFrequently: true });
    if (!context) throw new Error('Virus backing sampler unavailable');
    context.drawImage(world, 0, 0);
    const pixels = context.getImageData(0, 0, copy.width, copy.height).data;
    const scaleX = copy.width / ${WORLD_WIDTH};
    const scaleY = copy.height / ${WORLD_HEIGHT};
    const snapshot = window.__ANIFOR_INPUT_AUDIT__.virusGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const rectPoints = (rect) => {
      const points = [];
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) points.push({ x, y });
      }
      return points;
    };
    const key = ({ x, y }) => x + ',' + y;
    const uniquePoints = (points) => [...new Map(points.map((point) => [key(point), point])).values()];
    const cellAlpha = ({ x, y }) => {
      const left = Math.floor(x * scaleX);
      const top = Math.floor(y * scaleY);
      const right = Math.max(left + 1, Math.floor((x + 1) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((y + 1) * scaleY));
      let minimum = 255;
      let peak = 0;
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        const alpha = pixels[(py * copy.width + px) * 4 + 3];
        minimum = Math.min(minimum, alpha);
        peak = Math.max(peak, alpha);
      }
      return { minimum, peak };
    };
    const cellCenterAlpha = ({ x, y }) => {
      const px = Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX));
      const py = Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY));
      return pixels[(py * copy.width + px) * 4 + 3];
    };
    const samplePointRgb = (points) => {
      const rgb = [];
      for (const { x, y } of points) {
        const px = Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX));
        const py = Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY));
        const offset = (py * copy.width + px) * 4;
        rgb.push(pixels[offset], pixels[offset + 1], pixels[offset + 2]);
      }
      return rgb;
    };
    const sampleGridRgb = (rect, step = 2) => {
      const points = [];
      for (let y = rect.y; y < rect.y + rect.height; y += step) {
        for (let x = rect.x; x < rect.x + rect.width; x += step) points.push({ x, y });
      }
      return { width: Math.ceil(rect.width / step), height: Math.ceil(rect.height / step), rgb: samplePointRgb(points) };
    };
    const sampleRectsRgb = (rects) => samplePointRgb(rects.flatMap(rectPoints));
    return {
      width: copy.width,
      height: copy.height,
      scaleX,
      scaleY,
      cards: cards.map((entry) => {
        const cavityKeys = new Set([
          ...rectPoints(entry.authoredCavity), ...rectPoints(entry.openChimney),
        ].map(key));
        const bodyPoints = rectPoints(entry.body).filter((point) => !cavityKeys.has(key(point)));
        const structurePoints = uniquePoints(entry.phaseStructure);
        const guardPoints = rectPoints(entry.guardedBlank);
        const cavityPoints = rectPoints(entry.authoredCavity);
        const chimneyPoints = rectPoints(entry.openChimney);
        const phaseGapPoints = entry.phaseGap ? rectPoints(entry.phaseGap) : [];
        const shellInteriorPoints = entry.shell ? rectPoints(entry.shell.interior) : [];
        const cardLeft = Math.floor(entry.card.x * scaleX);
        const cardTop = Math.floor(entry.card.y * scaleY);
        const cardRight = Math.floor((entry.card.x + entry.card.width) * scaleX);
        const cardBottom = Math.floor((entry.card.y + entry.card.height) * scaleY);
        let alphaSignature = 2166136261;
        let supportSignature = 2166136261;
        for (let py = cardTop; py < cardBottom; py++) for (let px = cardLeft; px < cardRight; px++) {
          const alpha = pixels[(py * copy.width + px) * 4 + 3];
          alphaSignature = Math.imul(alphaSignature ^ alpha, 16777619) >>> 0;
          supportSignature = Math.imul(supportSignature ^ Number(alpha > 0), 16777619) >>> 0;
        }
        let semanticSignature = 2166136261;
        for (let y = entry.card.y; y < entry.card.y + entry.card.height; y++) {
          for (let x = entry.card.x; x < entry.card.x + entry.card.width; x++) {
            semanticSignature = Math.imul(
              semanticSignature ^ window.__ANIFOR_INPUT_AUDIT__.cell(x, y), 16777619,
            ) >>> 0;
          }
        }
        const contact = (control) => {
          const owner = rectPoints(control.owner);
          const neighbour = rectPoints(control.neighbour);
          return {
            ownerExpected: owner.length,
            ownerSupported: owner.filter((point) => cellAlpha(point).peak > 0).length,
            neighbourExpected: neighbour.length,
            neighbourSupported: neighbour.filter((point) => cellAlpha(point).peak > 0).length,
            ownerRgb: samplePointRgb(owner),
            neighbourRgb: samplePointRgb(neighbour),
          };
        };
        const body = sampleGridRgb(entry.body);
        return {
          code: entry.code,
          material: entry.material,
          semanticSignature,
          alphaSignature,
          supportSignature,
          bodyExpected: bodyPoints.length,
          bodySupported: bodyPoints.filter((point) => cellAlpha(point).peak > 0).length,
          structureExpected: structurePoints.length,
          structureSupported: structurePoints.filter((point) => cellAlpha(point).peak > 0).length,
          isolatedAlphaPeak: cellAlpha(entry.isolated).peak,
          guardedBlankExpected: guardPoints.length,
          guardedBlankTransparent: guardPoints.filter((point) => cellAlpha(point).peak === 0).length,
          cavityExpected: cavityPoints.length,
          cavityCentreTransparent: cavityPoints.filter((point) => cellCenterAlpha(point) === 0).length,
          chimneyExpected: chimneyPoints.length,
          chimneyCentreTransparent: chimneyPoints.filter((point) => cellCenterAlpha(point) === 0).length,
          phaseGapExpected: phaseGapPoints.length,
          phaseGapCentreTransparent: phaseGapPoints.filter((point) => cellCenterAlpha(point) === 0).length,
          shellInteriorExpected: shellInteriorPoints.length,
          shellInteriorCentreTransparent: shellInteriorPoints.filter((point) => cellCenterAlpha(point) === 0).length,
          waterContact: contact(entry.waterContact),
          metalContact: contact(entry.metalContact),
          bodyWidth: body.width,
          bodyHeight: body.height,
          bodyRgb: body.rgb,
          motifRgb: {
            attachment: sampleRectsRgb(entry.motifProbes.map(({ attachment }) => attachment)),
            membrane: sampleRectsRgb(entry.motifProbes.map(({ membrane }) => membrane)),
            capsid: sampleRectsRgb(entry.motifProbes.map(({ capsid }) => capsid)),
            core: sampleRectsRgb(entry.motifProbes.map(({ core }) => core)),
            interstitial: sampleRectsRgb(entry.motifProbes.map(({ interstitial }) => interstitial)),
          },
        };
      }),
    };
  })()`);
}

function assertVirusBacking(backing, label) {
  assert(Number.isInteger(backing.scaleX) && Number.isInteger(backing.scaleY)
      && backing.scaleX > 0 && backing.scaleY > 0,
  `${label}: virus backing does not preserve integral world scaling (${backing.scaleX}x${backing.scaleY})`);
  assert(backing.cards.map(({ material }) => material).join(',') === '62,215,216'
      && backing.cards.every((card) => card.bodyExpected === 12_200
        && card.bodySupported === card.bodyExpected
        && card.structureExpected > 0 && card.structureSupported === card.structureExpected
        && card.isolatedAlphaPeak > 0
        && card.guardedBlankExpected === 2_288
        && card.guardedBlankTransparent === card.guardedBlankExpected
        && card.cavityExpected === 144
        && card.chimneyExpected === 200
        && (card.code === 'VRSG' || (
          card.cavityCentreTransparent / card.cavityExpected >= 0.80
          && card.chimneyCentreTransparent / card.chimneyExpected >= 0.75
        ))
        && card.phaseGapCentreTransparent === card.phaseGapExpected
        && card.shellInteriorCentreTransparent === card.shellInteriorExpected
        && card.waterContact.ownerExpected === 192
        && card.waterContact.ownerSupported === 192
        && card.waterContact.neighbourExpected === 256
        && card.waterContact.neighbourSupported === 256
        && card.metalContact.ownerExpected === 192
        && card.metalContact.ownerSupported === 192
        && card.metalContact.neighbourExpected === 256
        && card.metalContact.neighbourSupported === 256),
  `${label}: virus backing changed body/structure/isolated/guard/contact topology (${JSON.stringify(
    backing.cards.map(({ bodyRgb: _bodyRgb, motifRgb: _motifRgb, waterContact, metalContact, ...card }) => ({
      ...card,
      waterContact: { ...waterContact, ownerRgb: undefined, neighbourRgb: undefined },
      metalContact: { ...metalContact, ownerRgb: undefined, neighbourRgb: undefined },
    })),
  )})`);
}

function summarizeVirusBackingResponses(flat, styled, repeated) {
  return flat.cards.map((base, index) => {
    const changed = styled.cards[index];
    const returned = repeated.cards[index];
    assert(base.code === changed.code && base.code === returned.code
        && base.bodyRgb.length === changed.bodyRgb.length
        && base.bodyRgb.length === returned.bodyRgb.length,
    `Virus backing response geometry changed for ${base.code}`);
    let squared = 0;
    let peak = 0;
    let repeatPeak = 0;
    let changedSamples = 0;
    const profileBuckets = new Float64Array(16);
    const axisMap = [];
    for (let offset = 0; offset < base.bodyRgb.length; offset += 3) {
      const sample = offset / 3;
      const x = sample % base.bodyWidth;
      const y = Math.floor(sample / base.bodyWidth);
      const bucket = Math.min(3, Math.floor(y * 4 / base.bodyHeight)) * 4
        + Math.min(3, Math.floor(x * 4 / base.bodyWidth));
      const red = changed.bodyRgb[offset] - base.bodyRgb[offset];
      const green = changed.bodyRgb[offset + 1] - base.bodyRgb[offset + 1];
      const blue = changed.bodyRgb[offset + 2] - base.bodyRgb[offset + 2];
      axisMap.push((red + blue) * 0.5 - green);
      let sampleChanged = false;
      for (const delta of [red, green, blue]) {
        squared += delta * delta;
        peak = Math.max(peak, Math.abs(delta));
        profileBuckets[bucket] += Math.abs(delta);
        sampleChanged ||= delta !== 0;
      }
      for (let channel = 0; channel < 3; channel++) {
        repeatPeak = Math.max(repeatPeak, Math.abs(
          returned.bodyRgb[offset + channel] - base.bodyRgb[offset + channel],
        ));
      }
      changedSamples += Number(sampleChanged);
    }
    const profileTotal = profileBuckets.reduce((sum, value) => sum + value, 0);
    const motifAxis = {};
    for (const kind of ['attachment', 'membrane', 'capsid', 'core', 'interstitial']) {
      const before = base.motifRgb[kind];
      const after = changed.motifRgb[kind];
      let axis = 0;
      for (let offset = 0; offset < before.length; offset += 3) {
        const red = after[offset] - before[offset];
        const green = after[offset + 1] - before[offset + 1];
        const blue = after[offset + 2] - before[offset + 2];
        axis += (red + blue) * 0.5 - green;
      }
      motifAxis[kind] = axis / Math.max(1, before.length / 3);
    }
    return {
      code: base.code,
      material: base.material,
      rgbRms: Math.sqrt(squared / Math.max(1, base.bodyRgb.length)),
      rgbPeak: peak,
      changedSampleRatio: changedSamples / Math.max(1, base.bodyRgb.length / 3),
      repeatRgbPeak: repeatPeak,
      profile: Array.from(profileBuckets, (value) => profileTotal > 0 ? value / profileTotal : 0),
      axisMap,
      motifAxis,
    };
  });
}

function virusPearson(left, right) {
  assert(left.length === right.length && left.length > 0, 'Virus correlation geometry changed');
  const leftMean = left.reduce((sum, value) => sum + value, 0) / left.length;
  const rightMean = right.reduce((sum, value) => sum + value, 0) / right.length;
  let covariance = 0;
  let leftSquared = 0;
  let rightSquared = 0;
  for (let index = 0; index < left.length; index++) {
    const l = left[index] - leftMean;
    const r = right[index] - rightMean;
    covariance += l * r;
    leftSquared += l * l;
    rightSquared += r * r;
  }
  return covariance / Math.max(1e-9, Math.sqrt(leftSquared * rightSquared));
}

/** Focused phase-continuous WAX/MWAX topology and paired-renderer proof. */
async function auditWaxGraphics(cdp, mode) {
  const started = performance.now();
  const stage = (name) => console.error(
    `[wax-graphics:${mode}] ${name} ${Math.round(performance.now() - started)}ms`,
  );
  const blank = await waitForStablePageCapture(cdp, `${mode} initial blank wax framebuffer`);
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.prepareWaxGraphicsFixture !== 'function'
      || typeof audit.waxGraphicsAtlas !== 'function'
      || typeof audit.setLiquidIdentityStyling !== 'function'
      || typeof audit.setUnusualSolidStyling !== 'function') {
      throw new Error('Wax graphics audit API unavailable');
    }
    audit.prepareWaxGraphicsFixture();
    return true;
  })()`);
  const rawAtlas = await waitFor(() => evaluate(cdp, `(() => {
    const atlas = window.__ANIFOR_INPUT_AUDIT__.waxGraphicsAtlas();
    const cards = Array.isArray(atlas) ? atlas : atlas?.cards;
    return cards?.length === 2 ? atlas : false;
  })()`), 15_000, `${mode} wax graphics fixture`);
  const atlas = normalizeWaxGraphicsAtlas(rawAtlas);
  assert(atlas.cards.map(({ material }) => material).join(',') === '27,59'
      && atlas.cards.map(({ code }) => code).join(',') === 'WAX,MWAX'
      && atlas.cards.map(({ phase }) => phase).join(',') === 'solid,liquid'
      && atlas.cards.every(({ body }) => body.width === 160 && body.height === 128)
      && atlas.cards.every(({ motifProbes }) => motifProbes.length === 10)
      && atlas.cards[0].body.x % 32 === atlas.cards[1].body.x % 32
      && atlas.cards[0].body.y % 32 === atlas.cards[1].body.y % 32,
  `${mode}: wax atlas contract changed`);
  const semanticState = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const snapshot = audit.waxGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const inside = (x, y, rect) => x >= rect.x && y >= rect.y
      && x < rect.x + rect.width && y < rect.y + rect.height;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    return cards.map((entry) => {
      let bodyExact = true;
      for (let y = entry.body.y; y < entry.body.y + entry.body.height; y++) {
        for (let x = entry.body.x; x < entry.body.x + entry.body.width; x++) {
          const empty = inside(x, y, entry.authoredCavity) || inside(x, y, entry.openChimney);
          bodyExact = bodyExact && audit.cell(x, y) === (empty ? 0 : entry.material);
        }
      }
      return {
        material: entry.material,
        bodyExact,
        cavityEmpty: exactRect(entry.authoredCavity, 0),
        chimneyEmpty: exactRect(entry.openChimney, 0),
        structureExact: entry.phaseStructure.every(({ x, y }) => audit.cell(x, y) === entry.material),
        isolated: audit.cell(entry.isolated.x, entry.isolated.y),
        guardedBlankEmpty: exactRect(entry.guardedBlank, 0),
        waterOwnerExact: exactRect(entry.waterContact.owner, entry.material),
        waterExact: exactRect(entry.waterContact.neighbour, entry.waterContact.neighbourMaterial),
        metalOwnerExact: exactRect(entry.metalContact.owner, entry.material),
        metalExact: exactRect(entry.metalContact.neighbour, entry.metalContact.neighbourMaterial),
      };
    });
  })()`);
  assert(semanticState.every((entry) => entry.bodyExact && entry.cavityEmpty
      && entry.chimneyEmpty && entry.structureExact && entry.isolated === entry.material
      && entry.guardedBlankEmpty && entry.waterOwnerExact && entry.waterExact
      && entry.metalOwnerExact && entry.metalExact),
  `${mode}: wax fixture lost phase semantics, topology, or contacts (${JSON.stringify(semanticState)})`);
  stage('fixture-ready');

  const setWaxStyling = async (enabled) => evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.setUnusualSolidStyling(${enabled});
    audit.setLiquidIdentityStyling(${enabled});
    return true;
  })()`);
  await setWaxStyling(false);
  const flat = await waitForStablePageCapture(cdp, `${mode} flat wax framebuffer`);
  const flatBacking = await sampleWaxBacking(cdp);
  await setWaxStyling(true);
  const styled = await waitForStablePageCapture(cdp, `${mode} styled wax framebuffer`);
  const styledBacking = await sampleWaxBacking(cdp);
  await setWaxStyling(false);
  const repeated = await waitForStablePageCapture(cdp, `${mode} repeated flat wax framebuffer`);
  const repeatedBacking = await sampleWaxBacking(cdp);
  for (const [state, backing] of [
    ['flat', flatBacking], ['styled', styledBacking], ['repeated-flat', repeatedBacking],
  ]) assertWaxBacking(backing, `${mode} ${state}`);
  for (let index = 0; index < 2; index++) {
    const base = flatBacking.cards[index];
    const changed = styledBacking.cards[index];
    const returned = repeatedBacking.cards[index];
    assert(base.semanticSignature === changed.semanticSignature
        && base.semanticSignature === returned.semanticSignature
        && base.alphaSignature === changed.alphaSignature
        && base.alphaSignature === returned.alphaSignature
        && base.supportSignature === changed.supportSignature
        && base.supportSignature === returned.supportSignature,
    `${mode}: ${base.code} styling changed semantic/alpha/support signatures`);
    for (const contactName of ['waterContact', 'metalContact']) {
      assert(arraysEqual(base[contactName].neighbourRgb, changed[contactName].neighbourRgb)
          && arraysEqual(base[contactName].neighbourRgb, returned[contactName].neighbourRgb),
      `${mode}: ${base.code} styling leaked into ${contactName}`);
    }
  }
  const responses = summarizeWaxBackingResponses(flatBacking, styledBacking, repeatedBacking);
  for (const response of responses) {
    assert(response.rgbRms >= 0.05 && response.rgbRms <= 24
        && response.rgbPeak > 0 && response.rgbPeak <= 64
        && response.changedSampleRatio >= 0.02 && response.repeatRgbPeak === 0,
    `${mode}: ${response.code} wax response is absent, unbounded, or unstable (${JSON.stringify(response)})`);
    assert(response.motifAxis.ridge > response.motifAxis.interstitial
        && response.motifAxis.joint > response.motifAxis.interstitial,
    `${mode}: ${response.code} lost ridge/joint ordering (${JSON.stringify(response.motifAxis)})`);
  }
  const phaseCorrelation = virusPearson(responses[0].axisMap, responses[1].axisMap);
  // The shared wax grammar is intentionally softened by MWAX's liquid body optics;
  // retain a strong positive spatial relationship without requiring identical phase response.
  assert(phaseCorrelation >= 0.60,
    `${mode}: WAX/MWAX do not retain one spatial grammar (${phaseCorrelation})`);
  const normalFitRegions = atlas.cards.map((entry) => ({
    name: `${entry.code}-normal-fit-body`,
    x: entry.body.x + entry.body.width / 2,
    y: entry.body.y + entry.body.height / 2,
    radiusX: entry.body.width / 2,
    radiusY: entry.body.height / 2,
    signature: true, silhouette: true, fastSupport: true,
  }));
  const normalFit = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: styled.capture.data,
    repeatedStraight: repeated.capture.data,
  }, normalFitRegions, flat.canvasRect);
  assert(normalFit.every((response) => response.rgbRms > 0 && response.rgbRms <= 32
      && response.rgbPeak > 0 && response.rgbPeak <= 64 && response.repeatRgbPeak === 0),
  `${mode}: wax family is absent, unbounded, or unstable at normal fit (${JSON.stringify(normalFit)})`);
  stage('responses-ready');
  return {
    cards: responses.map((response, index) => ({
      ...response,
      phase: atlas.cards[index].phase,
      normalFitRgbRms: normalFit[index].rgbRms,
      normalFitRgbPeak: normalFit[index].rgbPeak,
    })),
    phaseCorrelation,
    exactRepeatedOff: responses.every(({ repeatRgbPeak }) => repeatRgbPeak === 0),
    supportSignatures: flatBacking.cards.map(({ supportSignature }) => supportSignature),
  };
}

async function sampleWaxBacking(cdp) {
  return evaluate(cdp, `(() => {
    const world = document.querySelector('.world-canvas');
    if (!(world instanceof HTMLCanvasElement)) throw new Error('World canvas unavailable');
    const copy = document.createElement('canvas');
    copy.width = world.width; copy.height = world.height;
    const context = copy.getContext('2d', { willReadFrequently: true });
    if (!context) throw new Error('Wax backing sampler unavailable');
    context.drawImage(world, 0, 0);
    const pixels = context.getImageData(0, 0, copy.width, copy.height).data;
    const scaleX = copy.width / ${WORLD_WIDTH};
    const scaleY = copy.height / ${WORLD_HEIGHT};
    const snapshot = window.__ANIFOR_INPUT_AUDIT__.waxGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const key = ({ x, y }) => x + ',' + y;
    const rectPoints = (rect) => {
      const points = [];
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) points.push({ x, y });
      }
      return points;
    };
    const uniquePoints = (points) => [...new Map(points.map((point) => [key(point), point])).values()];
    const cellAlpha = ({ x, y }) => {
      const left = Math.floor(x * scaleX), top = Math.floor(y * scaleY);
      const right = Math.max(left + 1, Math.floor((x + 1) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((y + 1) * scaleY));
      let peak = 0;
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        peak = Math.max(peak, pixels[(py * copy.width + px) * 4 + 3]);
      }
      return peak;
    };
    const centreAlpha = ({ x, y }) => {
      const px = Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX));
      const py = Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY));
      return pixels[(py * copy.width + px) * 4 + 3];
    };
    const samplePointRgb = (points) => {
      const rgb = [];
      for (const { x, y } of points) {
        const px = Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX));
        const py = Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY));
        const offset = (py * copy.width + px) * 4;
        rgb.push(pixels[offset], pixels[offset + 1], pixels[offset + 2]);
      }
      return rgb;
    };
    const sampleGrid = (rect, step = 2) => {
      const points = [];
      for (let y = rect.y; y < rect.y + rect.height; y += step) {
        for (let x = rect.x; x < rect.x + rect.width; x += step) points.push({ x, y });
      }
      return { width: Math.ceil(rect.width / step), height: Math.ceil(rect.height / step), rgb: samplePointRgb(points) };
    };
    return {
      scaleX, scaleY,
      cards: cards.map((entry) => {
        const emptyKeys = new Set([
          ...rectPoints(entry.authoredCavity), ...rectPoints(entry.openChimney),
        ].map(key));
        const bodyPoints = rectPoints(entry.body).filter((point) => !emptyKeys.has(key(point)));
        const structures = uniquePoints(entry.phaseStructure);
        const guard = rectPoints(entry.guardedBlank);
        const cavity = rectPoints(entry.authoredCavity);
        const chimney = rectPoints(entry.openChimney);
        let alphaSignature = 2166136261, supportSignature = 2166136261;
        const left = Math.floor(entry.card.x * scaleX), top = Math.floor(entry.card.y * scaleY);
        const right = Math.floor((entry.card.x + entry.card.width) * scaleX);
        const bottom = Math.floor((entry.card.y + entry.card.height) * scaleY);
        for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
          const alpha = pixels[(py * copy.width + px) * 4 + 3];
          alphaSignature = Math.imul(alphaSignature ^ alpha, 16777619) >>> 0;
          supportSignature = Math.imul(supportSignature ^ Number(alpha > 0), 16777619) >>> 0;
        }
        let semanticSignature = 2166136261;
        for (let y = entry.card.y; y < entry.card.y + entry.card.height; y++) {
          for (let x = entry.card.x; x < entry.card.x + entry.card.width; x++) {
            semanticSignature = Math.imul(
              semanticSignature ^ window.__ANIFOR_INPUT_AUDIT__.cell(x, y), 16777619,
            ) >>> 0;
          }
        }
        const contact = (control) => {
          const owner = rectPoints(control.owner), neighbour = rectPoints(control.neighbour);
          return {
            ownerExpected: owner.length,
            ownerSupported: owner.filter((point) => cellAlpha(point) > 0).length,
            neighbourExpected: neighbour.length,
            neighbourSupported: neighbour.filter((point) => cellAlpha(point) > 0).length,
            neighbourRgb: samplePointRgb(neighbour),
          };
        };
        const body = sampleGrid(entry.body);
        const motif = (kind) => samplePointRgb(entry.motifProbes.map((probe) => probe[kind]));
        return {
          code: entry.code, material: entry.material,
          semanticSignature, alphaSignature, supportSignature,
          bodyExpected: bodyPoints.length,
          bodySupported: bodyPoints.filter((point) => cellAlpha(point) > 0).length,
          structureExpected: structures.length,
          structureSupported: structures.filter((point) => cellAlpha(point) > 0).length,
          isolatedAlphaPeak: cellAlpha(entry.isolated),
          guardedBlankExpected: guard.length,
          guardedBlankTransparent: guard.filter((point) => cellAlpha(point) === 0).length,
          cavityExpected: cavity.length,
          cavityCentreTransparent: cavity.filter((point) => centreAlpha(point) === 0).length,
          chimneyExpected: chimney.length,
          chimneyCentreTransparent: chimney.filter((point) => centreAlpha(point) === 0).length,
          waterContact: contact(entry.waterContact), metalContact: contact(entry.metalContact),
          bodyWidth: body.width, bodyHeight: body.height, bodyRgb: body.rgb,
          motifRgb: {
            ridge: motif('ridge'), fold: motif('fold'), bloom: motif('bloom'),
            joint: motif('joint'), interstitial: motif('interstitial'),
          },
        };
      }),
    };
  })()`);
}

function assertWaxBacking(backing, label) {
  assert(Number.isInteger(backing.scaleX) && Number.isInteger(backing.scaleY)
      && backing.scaleX > 0 && backing.scaleY > 0,
  `${label}: wax backing does not preserve integral scaling`);
  assert(backing.cards.map(({ material }) => material).join(',') === '27,59'
      && backing.cards.every((card) => card.bodyExpected === 20_040
        && card.bodySupported === card.bodyExpected
        && card.structureSupported === card.structureExpected
        && card.isolatedAlphaPeak > 0
        && card.guardedBlankExpected === 3_600
        && card.guardedBlankTransparent === card.guardedBlankExpected
        && card.cavityExpected === 224
        && card.cavityCentreTransparent / card.cavityExpected >= 0.80
        && card.chimneyExpected === 216
        && card.chimneyCentreTransparent / card.chimneyExpected >= 0.75
        && card.waterContact.ownerExpected === 320 && card.waterContact.ownerSupported === 320
        && card.waterContact.neighbourExpected === 400 && card.waterContact.neighbourSupported === 400
        && card.metalContact.ownerExpected === 320 && card.metalContact.ownerSupported === 320
        && card.metalContact.neighbourExpected === 400 && card.metalContact.neighbourSupported === 400),
  `${label}: wax backing changed topology (${JSON.stringify(backing.cards.map((card) => ({
    ...card, bodyRgb: undefined, motifRgb: undefined,
    waterContact: { ...card.waterContact, neighbourRgb: undefined },
    metalContact: { ...card.metalContact, neighbourRgb: undefined },
  })))})`);
}

function summarizeWaxBackingResponses(flat, styled, repeated) {
  return flat.cards.map((base, index) => {
    const changed = styled.cards[index], returned = repeated.cards[index];
    let squared = 0, peak = 0, repeatPeak = 0, changedSamples = 0;
    const buckets = new Float64Array(16), axisMap = [];
    for (let offset = 0; offset < base.bodyRgb.length; offset += 3) {
      const sample = offset / 3;
      const x = sample % base.bodyWidth, y = Math.floor(sample / base.bodyWidth);
      const bucket = Math.min(3, Math.floor(y * 4 / base.bodyHeight)) * 4
        + Math.min(3, Math.floor(x * 4 / base.bodyWidth));
      const deltas = [0, 1, 2].map((channel) => changed.bodyRgb[offset + channel] - base.bodyRgb[offset + channel]);
      axisMap.push((deltas[0] + deltas[1]) * 0.5 - deltas[2]);
      let any = false;
      for (const delta of deltas) { squared += delta * delta; peak = Math.max(peak, Math.abs(delta)); buckets[bucket] += Math.abs(delta); any ||= delta !== 0; }
      for (let channel = 0; channel < 3; channel++) repeatPeak = Math.max(
        repeatPeak, Math.abs(returned.bodyRgb[offset + channel] - base.bodyRgb[offset + channel]),
      );
      changedSamples += Number(any);
    }
    const total = buckets.reduce((sum, value) => sum + value, 0);
    const motifAxis = {};
    for (const kind of ['ridge', 'fold', 'bloom', 'joint', 'interstitial']) {
      const before = base.motifRgb[kind], after = changed.motifRgb[kind];
      let axis = 0;
      for (let offset = 0; offset < before.length; offset += 3) {
        axis += ((after[offset] - before[offset]) + (after[offset + 1] - before[offset + 1])) * 0.5
          - (after[offset + 2] - before[offset + 2]);
      }
      motifAxis[kind] = axis / Math.max(1, before.length / 3);
    }
    return {
      code: base.code, material: base.material,
      rgbRms: Math.sqrt(squared / Math.max(1, base.bodyRgb.length)), rgbPeak: peak,
      changedSampleRatio: changedSamples / Math.max(1, base.bodyRgb.length / 3),
      repeatRgbPeak: repeatPeak,
      profile: Array.from(buckets, (value) => total > 0 ? value / total : 0),
      axisMap, motifAxis,
    };
  });
}

/** Exact paired phase-family proof for PSTE/PSTS and RSST/RSSS. */
async function auditPasteResistGraphics(cdp, mode) {
  const started = performance.now();
  const stage = (name) => console.error(
    `[paste-resist-graphics:${mode}] ${name} ${Math.round(performance.now() - started)}ms`,
  );
  await waitForStablePageCapture(cdp, `${mode} initial blank paste/resist framebuffer`);
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.preparePasteResistGraphicsFixture !== 'function'
      || typeof audit.pasteResistGraphicsAtlas !== 'function'
      || typeof audit.setLiquidIdentityStyling !== 'function'
      || typeof audit.setUnusualSolidStyling !== 'function') {
      throw new Error('Paste/resist graphics audit API unavailable');
    }
    audit.preparePasteResistGraphicsFixture();
    return true;
  })()`);
  const rawAtlas = await waitFor(() => evaluate(cdp, `(() => {
    const atlas = window.__ANIFOR_INPUT_AUDIT__.pasteResistGraphicsAtlas();
    const cards = Array.isArray(atlas) ? atlas : atlas?.cards;
    return cards?.length === 4 ? atlas : false;
  })()`), 15_000, `${mode} paste/resist graphics fixture`);
  const atlas = normalizePasteResistGraphicsAtlas(rawAtlas);
  const cardGeometry = atlas.cards.map(({ card }) => (
    `${card.x},${card.y},${card.width},${card.height}`
  )).join('|');
  const bodyGeometry = atlas.cards.map(({ body }) => (
    `${body.x},${body.y},${body.width},${body.height}`
  )).join('|');
  assert(atlas.cards.map(({ material }) => material).join(',') === '60,206,61,79'
      && atlas.cards.map(({ code }) => code).join(',') === 'PSTE,PSTS,RSST,RSSS'
      && atlas.cards.map(({ family }) => family).join(',') === 'paste,paste,resist,resist'
      && atlas.cards.map(({ phase }) => phase).join(',') === 'liquid,solid,liquid,solid'
      && atlas.cards.map(({ structureKind }) => structureKind).join(',')
        === 'paste-rivulet,pressed-column,resist-film,hardened-mask'
      && atlas.cards.map(({ phasePartnerMaterial }) => phasePartnerMaterial).join(',')
        === '206,60,79,61'
      && cardGeometry === '4,4,300,184|308,4,300,184|4,196,300,184|308,196,300,184'
      && bodyGeometry === '20,20,144,104|340,20,144,104|20,212,144,104|340,212,144,104'
      && atlas.cards.every(({ motifProbes }) => motifProbes.length === 8)
      && atlas.cards.every(({ body }) => body.x % 32 === 20 && body.y % 32 === 20),
  `${mode}: paste/resist atlas identity, family, or geometry contract changed`);
  const semanticState = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const snapshot = audit.pasteResistGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const inside = (x, y, rect) => x >= rect.x && y >= rect.y
      && x < rect.x + rect.width && y < rect.y + rect.height;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    return cards.map((entry) => {
      let bodyExact = true;
      for (let y = entry.body.y; y < entry.body.y + entry.body.height; y++) {
        for (let x = entry.body.x; x < entry.body.x + entry.body.width; x++) {
          const empty = inside(x, y, entry.authoredCavity) || inside(x, y, entry.openChimney);
          bodyExact = bodyExact && audit.cell(x, y) === (empty ? 0 : entry.material);
        }
      }
      return {
        material: entry.material,
        bodyExact,
        cavityEmpty: exactRect(entry.authoredCavity, 0),
        chimneyEmpty: exactRect(entry.openChimney, 0),
        structureExact: entry.phaseStructure.every(({ x, y }) => audit.cell(x, y) === entry.material),
        isolated: audit.cell(entry.isolated.x, entry.isolated.y),
        guardedBlankEmpty: exactRect(entry.guardedBlank, 0),
        familyOwnerExact: exactRect(entry.familyContact.owner, entry.material),
        familyNeighbourExact: exactRect(
          entry.familyContact.neighbour, entry.familyContact.neighbourMaterial,
        ),
        metalOwnerExact: exactRect(entry.metalContact.owner, entry.material),
        metalExact: exactRect(entry.metalContact.neighbour, entry.metalContact.neighbourMaterial),
      };
    });
  })()`);
  assert(semanticState.every((entry) => entry.bodyExact && entry.cavityEmpty
      && entry.chimneyEmpty && entry.structureExact && entry.isolated === entry.material
      && entry.guardedBlankEmpty && entry.familyOwnerExact && entry.familyNeighbourExact
      && entry.metalOwnerExact && entry.metalExact),
  `${mode}: paste/resist fixture lost exact semantics or topology (${JSON.stringify(semanticState)})`);
  stage('fixture-ready');

  const setPasteResistStyling = async (enabled) => evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.setLiquidIdentityStyling(${enabled});
    audit.setUnusualSolidStyling(${enabled});
    return true;
  })()`);
  await setPasteResistStyling(false);
  const flat = await waitForStablePageCapture(cdp, `${mode} flat paste/resist framebuffer`);
  const flatBacking = await samplePasteResistBacking(cdp);
  await setPasteResistStyling(true);
  const styled = await waitForStablePageCapture(cdp, `${mode} styled paste/resist framebuffer`);
  const styledBacking = await samplePasteResistBacking(cdp);
  await setPasteResistStyling(false);
  const repeated = await waitForStablePageCapture(cdp, `${mode} repeated flat paste/resist framebuffer`);
  const repeatedBacking = await samplePasteResistBacking(cdp);
  for (const [state, backing] of [
    ['flat', flatBacking], ['styled', styledBacking], ['repeated-flat', repeatedBacking],
  ]) assertPasteResistBacking(backing, `${mode} ${state}`);
  for (let index = 0; index < 4; index++) {
    const base = flatBacking.cards[index];
    const changed = styledBacking.cards[index];
    const returned = repeatedBacking.cards[index];
    assert(base.semanticSignature === changed.semanticSignature
        && base.semanticSignature === returned.semanticSignature
        && base.alphaSignature === changed.alphaSignature
        && base.alphaSignature === returned.alphaSignature
        && base.supportSignature === changed.supportSignature
        && base.supportSignature === returned.supportSignature,
    `${mode}: ${base.code} styling changed semantic/alpha/support signatures`);
    assert(arraysEqual(base.metalContact.neighbourRgb, changed.metalContact.neighbourRgb)
        && arraysEqual(base.metalContact.neighbourRgb, returned.metalContact.neighbourRgb),
    `${mode}: ${base.code} identity styling leaked into its Metal neighbour`);
    assert(arraysEqual(base.familyContact.ownerRgb, returned.familyContact.ownerRgb)
        && arraysEqual(base.familyContact.neighbourRgb, returned.familyContact.neighbourRgb),
    `${mode}: ${base.code} family contact did not return to its exact flat RGB`);
    const meanRgb = (rgb) => {
      const sum = [0, 0, 0];
      for (let offset = 0; offset < rgb.length; offset += 3) {
        sum[0] += rgb[offset]; sum[1] += rgb[offset + 1]; sum[2] += rgb[offset + 2];
      }
      const samples = Math.max(1, rgb.length / 3);
      return sum.map((value) => value / samples);
    };
    const contactSeparation = (contact) => {
      const owner = meanRgb(contact.ownerRgb), neighbour = meanRgb(contact.neighbourRgb);
      return Math.hypot(
        owner[0] - neighbour[0], owner[1] - neighbour[1], owner[2] - neighbour[2],
      );
    };
    const flatSeparation = contactSeparation(base.familyContact);
    const styledSeparation = contactSeparation(changed.familyContact);
    assert(styledSeparation >= 4 && styledSeparation >= flatSeparation * 0.50,
      `${mode}: ${base.code} phase-partner contact collapsed (${flatSeparation}/${styledSeparation})`);
  }
  const responses = summarizePasteResistBackingResponses(
    flatBacking, styledBacking, repeatedBacking,
  );
  for (const response of responses) {
    const motifValues = Object.values(response.motifResponse);
    const motifSpread = Math.max(...motifValues) - Math.min(...motifValues);
    assert(response.rgbRms >= 0.20 && response.rgbRms <= 16
        && response.rgbPeak > 0 && response.rgbPeak <= 32
        && response.changedSampleRatio >= 0.50 && response.repeatRgbPeak === 0,
    `${mode}: ${response.code} response is absent, unbounded, or unstable (${JSON.stringify(response)})`);
    assert(motifSpread >= 0.50 && Math.max(...motifValues) > 0,
      `${mode}: ${response.code} lost its spatial family motif (${JSON.stringify(response.motifResponse)})`);
  }
  const familyCorrelations = {
    paste: virusPearson(responses[0].axisMap, responses[1].axisMap),
    resist: virusPearson(responses[2].axisMap, responses[3].axisMap),
  };
  assert(familyCorrelations.paste >= 0.55 && familyCorrelations.resist >= 0.55,
    `${mode}: paste/resist phases lost within-family spatial continuity (${JSON.stringify(familyCorrelations)})`);
  const normalFitRegions = atlas.cards.map((entry) => ({
    name: `${entry.code}-normal-fit-body`,
    x: entry.body.x + entry.body.width / 2,
    y: entry.body.y + entry.body.height / 2,
    radiusX: entry.body.width / 2,
    radiusY: entry.body.height / 2,
    signature: true, silhouette: true, fastSupport: true,
  }));
  const normalFit = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: styled.capture.data,
    repeatedStraight: repeated.capture.data,
  }, normalFitRegions, flat.canvasRect);
  assert(normalFit.every((response) => response.rgbRms >= 0.20 && response.rgbRms <= 16
      && response.rgbPeak > 0 && response.rgbPeak <= 32 && response.repeatRgbPeak === 0),
  `${mode}: paste/resist styling is absent, unbounded, or unstable at normal fit (${JSON.stringify(normalFit)})`);
  stage('responses-ready');
  return {
    cards: responses.map((response, index) => ({
      ...response,
      family: atlas.cards[index].family,
      phase: atlas.cards[index].phase,
      normalFitRgbRms: normalFit[index].rgbRms,
      normalFitRgbPeak: normalFit[index].rgbPeak,
    })),
    familyCorrelations,
    exactRepeatedOff: responses.every(({ repeatRgbPeak }) => repeatRgbPeak === 0),
    supportSignatures: flatBacking.cards.map(({ supportSignature }) => supportSignature),
  };
}

async function samplePasteResistBacking(cdp) {
  return evaluate(cdp, `(() => {
    const world = document.querySelector('.world-canvas');
    if (!(world instanceof HTMLCanvasElement)) throw new Error('World canvas unavailable');
    const copy = document.createElement('canvas');
    copy.width = world.width; copy.height = world.height;
    const context = copy.getContext('2d', { willReadFrequently: true });
    if (!context) throw new Error('Paste/resist backing sampler unavailable');
    context.drawImage(world, 0, 0);
    const pixels = context.getImageData(0, 0, copy.width, copy.height).data;
    const scaleX = copy.width / ${WORLD_WIDTH};
    const scaleY = copy.height / ${WORLD_HEIGHT};
    const snapshot = window.__ANIFOR_INPUT_AUDIT__.pasteResistGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const key = ({ x, y }) => x + ',' + y;
    const rectPoints = (rect) => {
      const points = [];
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) points.push({ x, y });
      }
      return points;
    };
    const uniquePoints = (points) => [...new Map(points.map((point) => [key(point), point])).values()];
    const cellAlpha = ({ x, y }) => {
      const left = Math.floor(x * scaleX), top = Math.floor(y * scaleY);
      const right = Math.max(left + 1, Math.floor((x + 1) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((y + 1) * scaleY));
      let peak = 0;
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        peak = Math.max(peak, pixels[(py * copy.width + px) * 4 + 3]);
      }
      return peak;
    };
    const centreAlpha = ({ x, y }) => {
      const px = Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX));
      const py = Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY));
      return pixels[(py * copy.width + px) * 4 + 3];
    };
    const samplePointRgb = (points) => {
      const rgb = [];
      for (const { x, y } of points) {
        const px = Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX));
        const py = Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY));
        const offset = (py * copy.width + px) * 4;
        rgb.push(pixels[offset], pixels[offset + 1], pixels[offset + 2]);
      }
      return rgb;
    };
    const sampleGrid = (rect, step = 2) => {
      const points = [];
      for (let y = rect.y; y < rect.y + rect.height; y += step) {
        for (let x = rect.x; x < rect.x + rect.width; x += step) points.push({ x, y });
      }
      return {
        width: Math.ceil(rect.width / step),
        height: Math.ceil(rect.height / step),
        rgb: samplePointRgb(points),
      };
    };
    return {
      scaleX, scaleY,
      cards: cards.map((entry) => {
        const emptyKeys = new Set([
          ...rectPoints(entry.authoredCavity), ...rectPoints(entry.openChimney),
        ].map(key));
        const bodyPoints = rectPoints(entry.body).filter((point) => !emptyKeys.has(key(point)));
        const structures = uniquePoints(entry.phaseStructure);
        const guard = rectPoints(entry.guardedBlank);
        const cavity = rectPoints(entry.authoredCavity);
        const chimney = rectPoints(entry.openChimney);
        let alphaSignature = 2166136261, supportSignature = 2166136261;
        const left = Math.floor(entry.card.x * scaleX), top = Math.floor(entry.card.y * scaleY);
        const right = Math.floor((entry.card.x + entry.card.width) * scaleX);
        const bottom = Math.floor((entry.card.y + entry.card.height) * scaleY);
        for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
          const alpha = pixels[(py * copy.width + px) * 4 + 3];
          alphaSignature = Math.imul(alphaSignature ^ alpha, 16777619) >>> 0;
          supportSignature = Math.imul(supportSignature ^ Number(alpha > 0), 16777619) >>> 0;
        }
        let semanticSignature = 2166136261;
        for (let y = entry.card.y; y < entry.card.y + entry.card.height; y++) {
          for (let x = entry.card.x; x < entry.card.x + entry.card.width; x++) {
            semanticSignature = Math.imul(
              semanticSignature ^ window.__ANIFOR_INPUT_AUDIT__.cell(x, y), 16777619,
            ) >>> 0;
          }
        }
        const contact = (control) => {
          const owner = rectPoints(control.owner), neighbour = rectPoints(control.neighbour);
          return {
            ownerExpected: owner.length,
            ownerSupported: owner.filter((point) => cellAlpha(point) > 0).length,
            ownerRgb: samplePointRgb(owner),
            neighbourExpected: neighbour.length,
            neighbourSupported: neighbour.filter((point) => cellAlpha(point) > 0).length,
            neighbourRgb: samplePointRgb(neighbour),
          };
        };
        const body = sampleGrid(entry.body);
        const motif = (kind) => samplePointRgb(entry.motifProbes.map((probe) => probe[kind]));
        return {
          code: entry.code, material: entry.material,
          semanticSignature, alphaSignature, supportSignature,
          bodyExpected: bodyPoints.length,
          bodySupported: bodyPoints.filter((point) => cellAlpha(point) > 0).length,
          structureExpected: structures.length,
          structureSupported: structures.filter((point) => cellAlpha(point) > 0).length,
          isolatedAlphaPeak: cellAlpha(entry.isolated),
          guardedBlankExpected: guard.length,
          guardedBlankTransparent: guard.filter((point) => cellAlpha(point) === 0).length,
          cavityExpected: cavity.length,
          cavityCentreTransparent: cavity.filter((point) => centreAlpha(point) === 0).length,
          chimneyExpected: chimney.length,
          chimneyCentreTransparent: chimney.filter((point) => centreAlpha(point) === 0).length,
          familyContact: contact(entry.familyContact),
          metalContact: contact(entry.metalContact),
          bodyWidth: body.width, bodyHeight: body.height, bodyRgb: body.rgb,
          motifRgb: {
            ridge: motif('ridge'), fold: motif('fold'), bloom: motif('bloom'),
            joint: motif('joint'), interstitial: motif('interstitial'),
          },
        };
      }),
    };
  })()`);
}

function assertPasteResistBacking(backing, label) {
  const structureCounts = [85, 145, 133, 200];
  assert(Number.isInteger(backing.scaleX) && Number.isInteger(backing.scaleY)
      && backing.scaleX > 0 && backing.scaleY > 0,
  `${label}: paste/resist backing does not preserve integral scaling`);
  assert(backing.cards.map(({ material }) => material).join(',') === '60,206,61,79'
      && backing.cards.every((card, index) => card.bodyExpected === 14_676
        && card.bodySupported === card.bodyExpected
        && card.structureExpected === structureCounts[index]
        && card.structureSupported === card.structureExpected
        && card.isolatedAlphaPeak > 0
        && card.guardedBlankExpected === 2_800
        && card.guardedBlankTransparent === card.guardedBlankExpected
        && card.cavityExpected === 120
        && card.cavityCentreTransparent / card.cavityExpected >= 0.65
        && card.chimneyExpected === 180
        && card.chimneyCentreTransparent / card.chimneyExpected >= 0.75
        && card.familyContact.ownerExpected === 192
        && card.familyContact.ownerSupported === card.familyContact.ownerExpected
        && card.familyContact.neighbourExpected === 256
        && card.familyContact.neighbourSupported === card.familyContact.neighbourExpected
        && card.metalContact.ownerExpected === 192
        && card.metalContact.ownerSupported === card.metalContact.ownerExpected
        && card.metalContact.neighbourExpected === 256
        && card.metalContact.neighbourSupported === card.metalContact.neighbourExpected),
  `${label}: paste/resist backing changed topology (${JSON.stringify(backing.cards.map((card) => ({
    ...card, bodyRgb: undefined, motifRgb: undefined,
    familyContact: { ...card.familyContact, ownerRgb: undefined, neighbourRgb: undefined },
    metalContact: { ...card.metalContact, ownerRgb: undefined, neighbourRgb: undefined },
  })))})`);
}

function summarizePasteResistBackingResponses(flat, styled, repeated) {
  return flat.cards.map((base, index) => {
    const changed = styled.cards[index], returned = repeated.cards[index];
    let squared = 0, peak = 0, repeatPeak = 0, changedSamples = 0;
    const buckets = new Float64Array(16), axisMap = [], signedChromaMap = [];
    for (let offset = 0; offset < base.bodyRgb.length; offset += 3) {
      const sample = offset / 3;
      const x = sample % base.bodyWidth, y = Math.floor(sample / base.bodyWidth);
      const bucket = Math.min(3, Math.floor(y * 4 / base.bodyHeight)) * 4
        + Math.min(3, Math.floor(x * 4 / base.bodyWidth));
      let sampleSquared = 0, any = false;
      const deltas = [0, 0, 0];
      for (let channel = 0; channel < 3; channel++) {
        const delta = changed.bodyRgb[offset + channel] - base.bodyRgb[offset + channel];
        deltas[channel] = delta;
        squared += delta * delta; sampleSquared += delta * delta;
        peak = Math.max(peak, Math.abs(delta)); buckets[bucket] += Math.abs(delta);
        any ||= delta !== 0;
        repeatPeak = Math.max(
          repeatPeak, Math.abs(returned.bodyRgb[offset + channel] - base.bodyRgb[offset + channel]),
        );
      }
      axisMap.push(Math.sqrt(sampleSquared));
      signedChromaMap.push((deltas[0] + deltas[1]) * 0.5 - deltas[2]);
      changedSamples += Number(any);
    }
    const total = buckets.reduce((sum, value) => sum + value, 0);
    const motifResponse = {};
    for (const kind of ['ridge', 'fold', 'bloom', 'joint', 'interstitial']) {
      const before = base.motifRgb[kind], after = changed.motifRgb[kind];
      let motifSquared = 0;
      for (let offset = 0; offset < before.length; offset += 3) {
        for (let channel = 0; channel < 3; channel++) {
          const delta = after[offset + channel] - before[offset + channel];
          motifSquared += delta * delta;
        }
      }
      motifResponse[kind] = Math.sqrt(motifSquared / Math.max(1, before.length / 3));
    }
    return {
      code: base.code, material: base.material,
      rgbRms: Math.sqrt(squared / Math.max(1, base.bodyRgb.length)), rgbPeak: peak,
      changedSampleRatio: changedSamples / Math.max(1, base.bodyRgb.length / 3),
      repeatRgbPeak: repeatPeak,
      profile: Array.from(buckets, (value) => total > 0 ? value / total : 0),
      axisMap, signedChromaMap, motifResponse,
    };
  });
}

/** Paired real-framebuffer proof for the 16-bit VIBR/BVBR native state path. */
async function auditVibrStateGraphics(cdp, mode) {
  const started = performance.now();
  const stage = (name) => console.error(
    `[vibr-state-graphics:${mode}] ${name} ${Math.round(performance.now() - started)}ms`,
  );
  await waitForStablePageCapture(cdp, `${mode} initial blank VIBR-state framebuffer`);
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.prepareVibrStateGraphicsFixture !== 'function'
      || typeof audit.vibrStateGraphicsAtlas !== 'function'
      || typeof audit.setVibrStateStyling !== 'function') {
      throw new Error('VIBR/BVBR state graphics audit API unavailable');
    }
    audit.prepareVibrStateGraphicsFixture();
    return true;
  })()`);
  const rawAtlas = await waitFor(() => evaluate(cdp, `(() => {
    const atlas = window.__ANIFOR_INPUT_AUDIT__.vibrStateGraphicsAtlas();
    const cards = Array.isArray(atlas) ? atlas : atlas?.cards;
    return cards?.length === 10 ? atlas : false;
  })()`), 15_000, `${mode} VIBR/BVBR state graphics fixture`);
  const atlas = normalizeVibrStateGraphicsAtlas(rawAtlas);
  const expectedKeys = ['low', 'mid', 'high', 'exploding', 'alternate'];
  const expectedEncoded = [8, 54, 99, 100 | (192 << 7), 100 | (112 << 7) | 0x8000];
  assert(atlas.cards.length === 10
      && atlas.cards.map(({ material }) => material).join(',')
        === '113,113,113,113,113,99,99,99,99,99'
      && atlas.cards.map(({ code }) => code).join(',')
        === 'VIBR,VIBR,VIBR,VIBR,VIBR,BVBR,BVBR,BVBR,BVBR,BVBR'
      && atlas.cards.every((entry, index) => entry.stateKey === expectedKeys[index % 5]
        && entry.encodedState === expectedEncoded[index % 5]
        && entry.charge === [8, 54, 99, 100, 100][index % 5]
        && entry.life === [0, 0, 0, 192, 112][index % 5]
        && entry.alternate === (index % 5 === 4)),
  `${mode}: VIBR/BVBR state atlas contract changed (${JSON.stringify(atlas.cards.map(
    ({ code, material, stateKey, charge, life, alternate, encodedState }) => ({
      code, material, stateKey, charge, life, alternate, encodedState,
    }),
  ))})`);

  const semanticState = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const snapshot = audit.vibrStateGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const inside = (x, y, rect) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    return cards.map((entry) => {
      let bodyExact = true;
      for (let y = entry.body.y; y < entry.body.y + entry.body.height; y++) {
        for (let x = entry.body.x; x < entry.body.x + entry.body.width; x++) {
          const empty = inside(x, y, entry.authoredHole) || inside(x, y, entry.openNotch);
          bodyExact = bodyExact && audit.cell(x, y) === (empty ? 0 : entry.material);
        }
      }
      return {
        bodyExact,
        surfaceExact: exactRect(entry.surfaceProbe, entry.material),
        coreExact: exactRect(entry.coreProbe, entry.material),
        holeEmpty: exactRect(entry.authoredHole, 0),
        notchEmpty: exactRect(entry.openNotch, 0),
        thinExact: exactRect(entry.thinStructure, entry.material),
        isolated: audit.cell(entry.isolated.x, entry.isolated.y),
        zeroStateExact: exactRect(entry.zeroState, entry.material),
        wrongOwnerExact: exactRect(entry.wrongOwner, 1),
        waterExact: exactRect(entry.waterControl, 2),
        metalExact: exactRect(entry.metalControl, 23),
        guardEmpty: exactRect(entry.guardedBlank, 0),
      };
    });
  })()`);
  assert(semanticState.every((entry, index) => entry.bodyExact && entry.surfaceExact
      && entry.coreExact && entry.holeEmpty && entry.notchEmpty && entry.thinExact
      && entry.isolated === atlas.cards[index].material && entry.zeroStateExact
      && entry.wrongOwnerExact
      && entry.waterExact && entry.metalExact && entry.guardEmpty),
  `${mode}: VIBR/BVBR state fixture lost semantic topology (${JSON.stringify(semanticState)})`);
  stage('fixture-ready');

  const setStyling = async (enabled) => evaluate(cdp, `(() => {
    window.__ANIFOR_INPUT_AUDIT__.setVibrStateStyling(${enabled}); return true;
  })()`);
  await setStyling(false);
  await waitForStablePageCapture(cdp, `${mode} flat VIBR-state framebuffer`);
  const flat = await sampleVibrStateBacking(cdp);
  await setStyling(true);
  await waitForStablePageCapture(cdp, `${mode} styled VIBR-state framebuffer`);
  const styled = await sampleVibrStateBacking(cdp);
  await setStyling(false);
  await waitForStablePageCapture(cdp, `${mode} repeated flat VIBR-state framebuffer`);
  const repeated = await sampleVibrStateBacking(cdp);
  for (const [state, backing] of [
    ['flat', flat], ['styled', styled], ['repeated-flat', repeated],
  ]) assertVibrStateBacking(backing, `${mode} ${state}`);

  for (let index = 0; index < 10; index++) {
    const base = flat.cards[index], changed = styled.cards[index], returned = repeated.cards[index];
    assert(base.semanticSignature === changed.semanticSignature
        && base.semanticSignature === returned.semanticSignature
        && base.alphaSignature === changed.alphaSignature
        && base.alphaSignature === returned.alphaSignature
        && base.supportSignature === changed.supportSignature
        && base.supportSignature === returned.supportSignature,
    `${mode}: ${base.code}/${base.stateKey} state styling changed semantic/alpha/support`);
    for (const control of ['zeroStateRgb', 'wrongOwnerRgb', 'waterRgb', 'metalRgb']) {
      assert(arraysEqual(base[control], changed[control])
          && arraysEqual(base[control], returned[control]),
      `${mode}: ${base.code}/${base.stateKey} state leaked into ${control}`);
    }
  }

  const responses = summarizeVibrStateBackingResponses(flat, styled, repeated);
  assert(responses.every((response) => response.rgbRms >= 0.02 && response.rgbRms <= 36
      && response.rgbPeak > 0 && response.rgbPeak <= 96
      && response.changedSampleRatio >= 0.01 && response.repeatRgbPeak === 0
      && response.profile.length === 16
      && Math.abs(response.profile.reduce((sum, value) => sum + value, 0) - 1) <= 0.001),
  `${mode}: VIBR/BVBR state response is absent, unbounded, or unstable (${JSON.stringify(responses)})`);
  const stateOrder = [];
  for (const material of [113, 99]) {
    const cards = responses.filter((response) => response.material === material);
    const byState = Object.fromEntries(cards.map((card) => [card.stateKey, card]));
    const chargeScore = (card) => card.meanDeltaRgb[1] + card.meanDeltaRgb[2] * 0.5;
    const low = chargeScore(byState.low), mid = chargeScore(byState.mid);
    const high = chargeScore(byState.high);
    const exploding = byState.exploding, alternate = byState.alternate;
    const explosionGain = exploding.rgbRms / Math.max(0.01, byState.high.rgbRms);
    const explodingBlueGreen = exploding.meanDeltaRgb[2] - exploding.meanDeltaRgb[1];
    const alternateBlueGreen = alternate.meanDeltaRgb[2] - alternate.meanDeltaRgb[1];
    assert(low < mid && mid < high,
      `${mode}: ${material} charge response is not ordered (${JSON.stringify({ low, mid, high })})`);
    assert(explosionGain > 1.02,
      `${mode}: ${material} explosion response did not exceed high charge (${explosionGain})`);
    assert(alternateBlueGreen > explodingBlueGreen + 0.25,
      `${mode}: ${material} alternate explosion lost its blue spectral turn (${JSON.stringify({
        explodingBlueGreen, alternateBlueGreen,
      })})`);
    stateOrder.push({ material, low, mid, high, explosionGain,
      explodingBlueGreen, alternateBlueGreen });
  }
  stage('responses-ready');
  return { cards: responses, stateOrder, exactRepeatedOff: responses.every(
    ({ repeatRgbPeak }) => repeatRgbPeak === 0,
  ) };
}

async function sampleVibrStateBacking(cdp) {
  return evaluate(cdp, `(() => {
    const world = document.querySelector('.world-canvas');
    if (!(world instanceof HTMLCanvasElement)) throw new Error('World canvas unavailable');
    const copy = document.createElement('canvas'); copy.width = world.width; copy.height = world.height;
    const context = copy.getContext('2d', { willReadFrequently: true });
    if (!context) throw new Error('VIBR/BVBR state backing sampler unavailable');
    context.drawImage(world, 0, 0);
    const pixels = context.getImageData(0, 0, copy.width, copy.height).data;
    const scaleX = copy.width / ${WORLD_WIDTH}, scaleY = copy.height / ${WORLD_HEIGHT};
    const snapshot = window.__ANIFOR_INPUT_AUDIT__.vibrStateGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const key = ({ x, y }) => x + ',' + y;
    const inside = (point, rect) => point.x >= rect.x && point.x < rect.x + rect.width
      && point.y >= rect.y && point.y < rect.y + rect.height;
    const rectPoints = (rect, step = 1) => { const points = [];
      for (let y = rect.y; y < rect.y + rect.height; y += step) {
        for (let x = rect.x; x < rect.x + rect.width; x += step) points.push({ x, y });
      }
      return points;
    };
    const cellAlpha = ({ x, y }) => { let peak = 0;
      const left = Math.floor(x * scaleX), top = Math.floor(y * scaleY);
      const right = Math.max(left + 1, Math.floor((x + 1) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((y + 1) * scaleY));
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        peak = Math.max(peak, pixels[(py * copy.width + px) * 4 + 3]);
      }
      return peak;
    };
    const centreAlpha = ({ x, y }) => pixels[(Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY))
      * copy.width + Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX))) * 4 + 3];
    const sampleRgb = (points) => { const rgb = [];
      for (const { x, y } of points) {
        const px = Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX));
        const py = Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY));
        const offset = (py * copy.width + px) * 4;
        rgb.push(pixels[offset], pixels[offset + 1], pixels[offset + 2]);
      }
      return rgb;
    };
    return { scaleX, scaleY, cards: cards.map((entry) => {
      const emptyKeys = new Set([...rectPoints(entry.authoredHole), ...rectPoints(entry.openNotch)].map(key));
      const bodyPoints = rectPoints(entry.body).filter((point) => !emptyKeys.has(key(point)));
      const bodySamples = rectPoints(entry.body, 2).filter((point) => !emptyKeys.has(key(point)));
      const bodyBuckets = bodySamples.map((point) => Math.min(3, Math.floor(
        (point.y - entry.body.y) * 4 / entry.body.height,
      )) * 4 + Math.min(3, Math.floor((point.x - entry.body.x) * 4 / entry.body.width)));
      const thin = rectPoints(entry.thinStructure), guard = rectPoints(entry.guardedBlank);
      const hole = rectPoints(entry.authoredHole), notch = rectPoints(entry.openNotch);
      const wrongOwner = rectPoints(entry.wrongOwner), water = rectPoints(entry.waterControl);
      const metal = rectPoints(entry.metalControl);
      const zeroState = rectPoints(entry.zeroState);
      let alphaSignature = 2166136261, supportSignature = 2166136261;
      let semanticSignature = 2166136261;
      const left = Math.floor(entry.card.x * scaleX), top = Math.floor(entry.card.y * scaleY);
      const right = Math.floor((entry.card.x + entry.card.width) * scaleX);
      const bottom = Math.floor((entry.card.y + entry.card.height) * scaleY);
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        const alpha = pixels[(py * copy.width + px) * 4 + 3];
        alphaSignature = Math.imul(alphaSignature ^ alpha, 16777619) >>> 0;
        supportSignature = Math.imul(supportSignature ^ Number(alpha > 0), 16777619) >>> 0;
      }
      for (let y = entry.card.y; y < entry.card.y + entry.card.height; y++) {
        for (let x = entry.card.x; x < entry.card.x + entry.card.width; x++) {
          semanticSignature = Math.imul(
            semanticSignature ^ window.__ANIFOR_INPUT_AUDIT__.cell(x, y), 16777619,
          ) >>> 0;
        }
      }
      return { code: entry.code, material: entry.material, stateKey: entry.stateKey,
        encodedState: entry.encodedState, semanticSignature, alphaSignature, supportSignature,
        bodyExpected: bodyPoints.length,
        bodySupported: bodyPoints.filter((point) => cellAlpha(point) > 0).length,
        thinExpected: thin.length, thinSupported: thin.filter((point) => cellAlpha(point) > 0).length,
        isolatedAlphaPeak: cellAlpha(entry.isolated),
        zeroStateExpected: zeroState.length,
        zeroStateSupported: zeroState.filter((point) => cellAlpha(point) > 0).length,
        guardExpected: guard.length, guardTransparent: guard.filter((point) => cellAlpha(point) === 0).length,
        holeExpected: hole.length, holeCentreTransparent: hole.filter((point) => centreAlpha(point) === 0).length,
        notchExpected: notch.length,
        notchCentreTransparent: notch.filter((point) => centreAlpha(point) < 128).length,
        wrongOwnerExpected: wrongOwner.length,
        wrongOwnerSupported: wrongOwner.filter((point) => cellAlpha(point) > 0).length,
        waterExpected: water.length, waterSupported: water.filter((point) => cellAlpha(point) > 0).length,
        metalExpected: metal.length, metalSupported: metal.filter((point) => cellAlpha(point) > 0).length,
        bodyRgb: sampleRgb(bodySamples), bodyBuckets,
        zeroStateRgb: sampleRgb(zeroState), wrongOwnerRgb: sampleRgb(wrongOwner),
        waterRgb: sampleRgb(water), metalRgb: sampleRgb(metal),
      };
    }) };
  })()`);
}

function assertVibrStateBacking(backing, label) {
  assert(Number.isInteger(backing.scaleX) && Number.isInteger(backing.scaleY)
      && backing.scaleX > 0 && backing.scaleY > 0,
  `${label}: VIBR/BVBR state backing does not preserve integral scaling`);
  assert(backing.cards.map(({ material }) => material).join(',')
      === '113,113,113,113,113,99,99,99,99,99'
      && backing.cards.every((card) => card.bodyExpected === 3_000
        && card.bodySupported === card.bodyExpected
        && card.thinExpected === 24 && card.thinSupported === card.thinExpected
        && card.isolatedAlphaPeak > 0
        && card.zeroStateExpected === 144 && card.zeroStateSupported === 144
        && card.guardExpected === 1_248 && card.guardTransparent === card.guardExpected
        && card.holeExpected === 36 && card.holeCentreTransparent >= 16
        && card.notchExpected === 96 && card.notchCentreTransparent >= 90
        && card.wrongOwnerExpected === 360 && card.wrongOwnerSupported === 360
        && card.waterExpected === 280 && card.waterSupported === 280
        && card.metalExpected === 280 && card.metalSupported === 280),
  `${label}: VIBR/BVBR state backing changed topology (${JSON.stringify(backing.cards.map(
    (card) => ({ ...card, bodyRgb: undefined, bodyBuckets: undefined,
      zeroStateRgb: undefined, wrongOwnerRgb: undefined, waterRgb: undefined, metalRgb: undefined }),
  ))})`);
}

function summarizeVibrStateBackingResponses(flat, styled, repeated) {
  return flat.cards.map((base, index) => {
    const changed = styled.cards[index], returned = repeated.cards[index];
    let squared = 0, peak = 0, repeatPeak = 0, changedSamples = 0;
    const signed = [0, 0, 0], buckets = new Float64Array(16), axisMap = [];
    for (let offset = 0; offset < base.bodyRgb.length; offset += 3) {
      let any = false, sampleSquared = 0;
      const sample = offset / 3, bucket = base.bodyBuckets[sample];
      for (let channel = 0; channel < 3; channel++) {
        const delta = changed.bodyRgb[offset + channel] - base.bodyRgb[offset + channel];
        squared += delta * delta; sampleSquared += delta * delta; signed[channel] += delta;
        peak = Math.max(peak, Math.abs(delta)); buckets[bucket] += Math.abs(delta); any ||= delta !== 0;
        repeatPeak = Math.max(
          repeatPeak, Math.abs(returned.bodyRgb[offset + channel] - base.bodyRgb[offset + channel]),
        );
      }
      axisMap.push(Math.sqrt(sampleSquared)); changedSamples += Number(any);
    }
    const samples = Math.max(1, base.bodyRgb.length / 3);
    const total = buckets.reduce((sum, value) => sum + value, 0);
    return { code: base.code, material: base.material, stateKey: base.stateKey,
      encodedState: base.encodedState,
      rgbRms: Math.sqrt(squared / Math.max(1, base.bodyRgb.length)), rgbPeak: peak,
      changedSampleRatio: changedSamples / samples, repeatRgbPeak: repeatPeak,
      meanDeltaRgb: signed.map((value) => value / samples),
      profile: Array.from(buckets, (value) => total > 0 ? value / total : 0), axisMap };
  });
}

/** Paired real-framebuffer proof for authoritative DEUT concentration graphics. */
async function auditDeutStateGraphics(cdp, mode) {
  const started = performance.now();
  const stage = (name) => console.error(
    `[deut-state-graphics:${mode}] ${name} ${Math.round(performance.now() - started)}ms`,
  );
  await waitForStablePageCapture(cdp, `${mode} initial blank DEUT-state framebuffer`);
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.prepareDeutStateGraphicsFixture !== 'function'
      || typeof audit.deutStateGraphicsAtlas !== 'function'
      || typeof audit.setDeutStateStyling !== 'function') {
      throw new Error('DEUT state graphics audit API unavailable');
    }
    audit.prepareDeutStateGraphicsFixture();
    return true;
  })()`);
  const rawAtlas = await waitFor(() => evaluate(cdp, `(() => {
    const atlas = window.__ANIFOR_INPUT_AUDIT__.deutStateGraphicsAtlas();
    const cards = Array.isArray(atlas) ? atlas : atlas?.cards;
    return cards?.length === 7 ? atlas : false;
  })()`), 15_000, `${mode} DEUT state graphics fixture`);
  const atlas = normalizeDeutStateGraphicsAtlas(rawAtlas);
  const expectedKeys = ['zero', 'default', 'low', 'medium', 'preGlow', 'glow', 'compressed'];
  const expectedStates = [0, 10, 80, 160, 239, 240, 6000];
  assert(atlas.cards.length === 7
      && atlas.cards.every((entry, index) => entry.material === 100 && entry.code === 'DEUT'
        && entry.stateKey === expectedKeys[index]
        && entry.concentration === expectedStates[index]
        && entry.encodedState === expectedStates[index]),
  `${mode}: DEUT state atlas contract changed (${JSON.stringify(atlas.cards.map(
    ({ stateKey, concentration, encodedState }) => ({ stateKey, concentration, encodedState }),
  ))})`);

  const semanticState = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const snapshot = audit.deutStateGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const inside = (x, y, rect) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    return cards.map((entry) => {
      let bodyExact = true;
      for (let y = entry.body.y; y < entry.body.y + entry.body.height; y++) {
        for (let x = entry.body.x; x < entry.body.x + entry.body.width; x++) {
          const empty = inside(x, y, entry.authoredHole) || inside(x, y, entry.openNotch);
          bodyExact = bodyExact && audit.cell(x, y) === (empty ? 0 : entry.material);
        }
      }
      return {
        bodyExact,
        state: audit.presentationState(entry.surfaceProbe.x, entry.surfaceProbe.y),
        holeEmpty: exactRect(entry.authoredHole, 0),
        notchEmpty: exactRect(entry.openNotch, 0),
        thinExact: exactRect(entry.thinStructure, entry.material),
        isolated: audit.cell(entry.isolated.x, entry.isolated.y),
        zeroStateExact: exactRect(entry.zeroState, entry.material),
        zeroStateWord: audit.presentationState(entry.zeroState.x, entry.zeroState.y),
        wrongOwnerExact: exactRect(entry.wrongOwner, 1),
        waterExact: exactRect(entry.waterControl, 2),
        metalExact: exactRect(entry.metalControl, 23),
        exotExact: exactRect(entry.exotControl, 102),
        isozExact: exactRect(entry.isozControl, 104),
        wallCoexistenceExact: exactRect(entry.wallCoexistence, 100),
        wallCoexistenceWall: (() => {
          for (let y = entry.wallCoexistence.y;
            y < entry.wallCoexistence.y + entry.wallCoexistence.height; y++) {
            for (let x = entry.wallCoexistence.x;
              x < entry.wallCoexistence.x + entry.wallCoexistence.width; x++) {
              if (audit.wall(x, y) !== 1) return false;
            }
          }
          return true;
        })(),
        liquidOwner: exactRect(entry.liquidContact.owner, entry.material),
        liquidNeighbour: exactRect(entry.liquidContact.neighbour, 2),
        solidOwner: exactRect(entry.solidContact.owner, entry.material),
        solidNeighbour: exactRect(entry.solidContact.neighbour, 23),
        guardEmpty: exactRect(entry.guardedBlank, 0),
      };
    });
  })()`);
  assert(semanticState.every((entry, index) => entry.bodyExact
      && entry.state === expectedStates[index] && entry.holeEmpty && entry.notchEmpty
      && entry.thinExact && entry.isolated === 100 && entry.zeroStateExact
      && entry.zeroStateWord === 0 && entry.wrongOwnerExact && entry.waterExact
      && entry.metalExact && entry.exotExact && entry.isozExact
      && entry.wallCoexistenceExact && entry.wallCoexistenceWall
      && entry.liquidOwner && entry.liquidNeighbour && entry.solidOwner
      && entry.solidNeighbour && entry.guardEmpty),
  `${mode}: DEUT state fixture lost semantic/state topology (${JSON.stringify(semanticState)})`);
  const highRangeState = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    return audit.deutStateGraphicsAtlas().highRange.map((entry) => ({
      stateKey: entry.stateKey,
      cell: audit.cell(entry.rect.x, entry.rect.y),
      state: audit.presentationState(entry.rect.x, entry.rect.y),
      encodedState: entry.encodedState,
    }));
  })()`);
  assert(highRangeState.length === 2
      && highRangeState[0].stateKey === 'reactionYield'
      && highRangeState[0].state === 17_000
      && highRangeState[1].stateKey === 'maximum'
      && highRangeState[1].state === 65_535
      && highRangeState.every(({ cell, state, encodedState }) => (
        cell === 100 && state === encodedState
      )),
  `${mode}: DEUT high-word state transport changed (${JSON.stringify(highRangeState)})`);
  stage('fixture-ready');

  const setStyling = async (enabled) => evaluate(cdp, `(() => {
    window.__ANIFOR_INPUT_AUDIT__.setDeutStateStyling(${enabled}); return true;
  })()`);
  await setStyling(false);
  await waitForStablePageCapture(cdp, `${mode} flat DEUT-state framebuffer`);
  const flat = await sampleDeutStateBacking(cdp);
  await setStyling(true);
  await waitForStablePageCapture(cdp, `${mode} styled DEUT-state framebuffer`);
  const styled = await sampleDeutStateBacking(cdp);
  await setStyling(false);
  await waitForStablePageCapture(cdp, `${mode} repeated flat DEUT-state framebuffer`);
  const repeated = await sampleDeutStateBacking(cdp);
  for (const [state, backing] of [
    ['flat', flat], ['styled', styled], ['repeated-flat', repeated],
  ]) assertDeutStateBacking(backing, `${mode} ${state}`);

  for (let index = 0; index < atlas.cards.length; index++) {
    const base = flat.cards[index], changed = styled.cards[index], returned = repeated.cards[index];
    assert(base.semanticSignature === changed.semanticSignature
        && base.semanticSignature === returned.semanticSignature
        && base.alphaSignature === changed.alphaSignature
        && base.alphaSignature === returned.alphaSignature
        && base.supportSignature === changed.supportSignature
        && base.supportSignature === returned.supportSignature,
    `${mode}: DEUT/${base.stateKey} styling changed semantic/alpha/support`);
    for (const control of [
      'zeroStateRgb', 'wrongOwnerRgb', 'waterRgb', 'metalRgb', 'exotRgb', 'isozRgb',
      'wallCoexistenceRgb', 'liquidNeighbourRgb', 'solidNeighbourRgb',
    ]) {
      assert(arraysEqual(base[control], changed[control])
          && arraysEqual(base[control], returned[control]),
      `${mode}: DEUT/${base.stateKey} state leaked into ${control}`);
    }
  }

  const responses = summarizeVibrStateBackingResponses(flat, styled, repeated);
  const byState = Object.fromEntries(responses.map((response) => [response.stateKey, response]));
  assert(byState.zero.rgbPeak === 0 && byState.zero.rgbRms === 0,
    `${mode}: DEUT state zero was not an exact no-op (${JSON.stringify(byState.zero)})`);
  assert(responses.filter(({ stateKey }) => stateKey !== 'zero').every((response) => (
    response.rgbRms >= 0.02 && response.rgbRms <= 36
    && response.rgbPeak > 0 && response.rgbPeak <= 96
    && response.changedSampleRatio >= 0.01 && response.repeatRgbPeak === 0
    && response.profile.length === 16
    && Math.abs(response.profile.reduce((sum, value) => sum + value, 0) - 1) <= 0.001
  )), `${mode}: DEUT concentration response is absent, unbounded, or unstable (${JSON.stringify(responses)})`);
  const ordered = ['default', 'low', 'medium', 'preGlow', 'glow', 'compressed']
    .map((key) => byState[key].rgbRms);
  assert(ordered.every((value, index) => index === 0 || value > ordered[index - 1]),
    `${mode}: DEUT concentration response is not strictly ordered (${JSON.stringify(ordered)})`);
  const glowGain = byState.glow.rgbRms / Math.max(0.01, byState.preGlow.rgbRms);
  assert(glowGain >= 1.35,
    `${mode}: DEUT 239/240 native glow threshold is not legible (${glowGain})`);
  const highRange = flat.highRange.map((base, index) => {
    const changed = styled.highRange[index], returned = repeated.highRange[index];
    let squared = 0, peak = 0, repeatPeak = 0;
    for (let offset = 0; offset < base.rgb.length; offset++) {
      const delta = changed.rgb[offset] - base.rgb[offset];
      squared += delta * delta;
      peak = Math.max(peak, Math.abs(delta));
      repeatPeak = Math.max(repeatPeak, Math.abs(returned.rgb[offset] - base.rgb[offset]));
    }
    return { stateKey: base.stateKey, encodedState: base.encodedState,
      rgbRms: Math.sqrt(squared / Math.max(1, base.rgb.length)), rgbPeak: peak, repeatRgbPeak: repeatPeak };
  });
  assert(highRange.length === 2
      && highRange.every(({ rgbRms, rgbPeak, repeatRgbPeak }) => (
        rgbRms >= 8 && rgbRms <= 36 && rgbPeak <= 96 && repeatRgbPeak === 0
      ))
      && highRange[1].rgbRms / highRange[0].rgbRms >= 0.95
      && highRange[1].rgbRms / highRange[0].rgbRms <= 1.05,
  `${mode}: DEUT high-word decode is absent, unstable, or not visually saturated (${JSON.stringify(highRange)})`);
  stage('responses-ready');
  return { cards: responses, ordered, glowGain, highRange,
    exactRepeatedOff: responses.every(({ repeatRgbPeak }) => repeatRgbPeak === 0) };
}

async function sampleDeutStateBacking(cdp) {
  return evaluate(cdp, `(() => {
    const world = document.querySelector('.world-canvas');
    if (!(world instanceof HTMLCanvasElement)) throw new Error('World canvas unavailable');
    const copy = document.createElement('canvas'); copy.width = world.width; copy.height = world.height;
    const context = copy.getContext('2d', { willReadFrequently: true });
    if (!context) throw new Error('DEUT state backing sampler unavailable');
    context.drawImage(world, 0, 0);
    const pixels = context.getImageData(0, 0, copy.width, copy.height).data;
    const scaleX = copy.width / ${WORLD_WIDTH}, scaleY = copy.height / ${WORLD_HEIGHT};
    const snapshot = window.__ANIFOR_INPUT_AUDIT__.deutStateGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const key = ({ x, y }) => x + ',' + y;
    const rectPoints = (rect, step = 1) => { const points = [];
      for (let y = rect.y; y < rect.y + rect.height; y += step) {
        for (let x = rect.x; x < rect.x + rect.width; x += step) points.push({ x, y });
      }
      return points;
    };
    const cellAlpha = ({ x, y }) => { let peak = 0;
      const left = Math.floor(x * scaleX), top = Math.floor(y * scaleY);
      const right = Math.max(left + 1, Math.floor((x + 1) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((y + 1) * scaleY));
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        peak = Math.max(peak, pixels[(py * copy.width + px) * 4 + 3]);
      }
      return peak;
    };
    const centreAlpha = ({ x, y }) => pixels[(Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY))
      * copy.width + Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX))) * 4 + 3];
    const sampleRgb = (points) => { const rgb = [];
      for (const { x, y } of points) {
        const px = Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX));
        const py = Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY));
        const offset = (py * copy.width + px) * 4;
        rgb.push(pixels[offset], pixels[offset + 1], pixels[offset + 2]);
      }
      return rgb;
    };
    const highRange = (snapshot.highRange ?? []).map((entry) => ({
      stateKey: entry.stateKey, encodedState: entry.encodedState,
      rgb: sampleRgb(rectPoints(entry.rect)),
    }));
    return { scaleX, scaleY, highRange, cards: cards.map((entry) => {
      const emptyKeys = new Set([...rectPoints(entry.authoredHole), ...rectPoints(entry.openNotch)].map(key));
      const bodyPoints = rectPoints(entry.body).filter((point) => !emptyKeys.has(key(point)));
      const bodySamples = rectPoints(entry.body, 2).filter((point) => !emptyKeys.has(key(point)));
      const bodyBuckets = bodySamples.map((point) => Math.min(3, Math.floor(
        (point.y - entry.body.y) * 4 / entry.body.height,
      )) * 4 + Math.min(3, Math.floor((point.x - entry.body.x) * 4 / entry.body.width)));
      const thin = rectPoints(entry.thinStructure), guard = rectPoints(entry.guardedBlank);
      const hole = rectPoints(entry.authoredHole), notch = rectPoints(entry.openNotch);
      const zeroState = rectPoints(entry.zeroState), wrongOwner = rectPoints(entry.wrongOwner);
      const water = rectPoints(entry.waterControl), metal = rectPoints(entry.metalControl);
      const exot = rectPoints(entry.exotControl), isoz = rectPoints(entry.isozControl);
      const wallCoexistence = rectPoints(entry.wallCoexistence);
      const liquidOwner = rectPoints(entry.liquidContact.owner);
      const liquidNeighbour = rectPoints(entry.liquidContact.neighbour);
      const solidOwner = rectPoints(entry.solidContact.owner);
      const solidNeighbour = rectPoints(entry.solidContact.neighbour);
      let alphaSignature = 2166136261, supportSignature = 2166136261;
      let semanticSignature = 2166136261;
      const left = Math.floor(entry.card.x * scaleX), top = Math.floor(entry.card.y * scaleY);
      const right = Math.floor((entry.card.x + entry.card.width) * scaleX);
      const bottom = Math.floor((entry.card.y + entry.card.height) * scaleY);
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        const alpha = pixels[(py * copy.width + px) * 4 + 3];
        alphaSignature = Math.imul(alphaSignature ^ alpha, 16777619) >>> 0;
        supportSignature = Math.imul(supportSignature ^ Number(alpha > 0), 16777619) >>> 0;
      }
      for (let y = entry.card.y; y < entry.card.y + entry.card.height; y++) {
        for (let x = entry.card.x; x < entry.card.x + entry.card.width; x++) {
          semanticSignature = Math.imul(
            semanticSignature ^ window.__ANIFOR_INPUT_AUDIT__.cell(x, y), 16777619,
          ) >>> 0;
        }
      }
      return { code: entry.code, material: entry.material, stateKey: entry.stateKey,
        encodedState: entry.encodedState, semanticSignature, alphaSignature, supportSignature,
        bodyExpected: bodyPoints.length,
        bodySupported: bodyPoints.filter((point) => cellAlpha(point) > 0).length,
        thinExpected: thin.length, thinSupported: thin.filter((point) => cellAlpha(point) > 0).length,
        isolatedAlphaPeak: cellAlpha(entry.isolated),
        zeroStateExpected: zeroState.length,
        zeroStateSupported: zeroState.filter((point) => cellAlpha(point) > 0).length,
        guardExpected: guard.length, guardTransparent: guard.filter((point) => cellAlpha(point) === 0).length,
        holeExpected: hole.length, holeCentreTransparent: hole.filter((point) => centreAlpha(point) === 0).length,
        notchExpected: notch.length,
        notchCentreTransparent: notch.filter((point) => centreAlpha(point) < 128).length,
        wrongOwnerExpected: wrongOwner.length,
        wrongOwnerSupported: wrongOwner.filter((point) => cellAlpha(point) > 0).length,
        waterExpected: water.length, waterSupported: water.filter((point) => cellAlpha(point) > 0).length,
        metalExpected: metal.length, metalSupported: metal.filter((point) => cellAlpha(point) > 0).length,
        exotExpected: exot.length, exotSupported: exot.filter((point) => cellAlpha(point) > 0).length,
        isozExpected: isoz.length, isozSupported: isoz.filter((point) => cellAlpha(point) > 0).length,
        liquidOwnerExpected: liquidOwner.length,
        liquidOwnerSupported: liquidOwner.filter((point) => cellAlpha(point) > 0).length,
        liquidNeighbourExpected: liquidNeighbour.length,
        liquidNeighbourSupported: liquidNeighbour.filter((point) => cellAlpha(point) > 0).length,
        solidOwnerExpected: solidOwner.length,
        solidOwnerSupported: solidOwner.filter((point) => cellAlpha(point) > 0).length,
        solidNeighbourExpected: solidNeighbour.length,
        solidNeighbourSupported: solidNeighbour.filter((point) => cellAlpha(point) > 0).length,
        bodyRgb: sampleRgb(bodySamples), bodyBuckets,
        zeroStateRgb: sampleRgb(zeroState), wrongOwnerRgb: sampleRgb(wrongOwner),
        waterRgb: sampleRgb(water), metalRgb: sampleRgb(metal),
        exotRgb: sampleRgb(exot), isozRgb: sampleRgb(isoz),
        wallCoexistenceRgb: sampleRgb(wallCoexistence),
        liquidNeighbourRgb: sampleRgb(liquidNeighbour), solidNeighbourRgb: sampleRgb(solidNeighbour),
      };
    }) };
  })()`);
}

function assertDeutStateBacking(backing, label) {
  assert(Number.isInteger(backing.scaleX) && Number.isInteger(backing.scaleY)
      && backing.scaleX > 0 && backing.scaleY > 0,
  `${label}: DEUT state backing does not preserve integral scaling`);
  assert(backing.highRange.length === 2
      && backing.highRange.map(({ encodedState }) => encodedState).join(',') === '17000,65535'
      && backing.cards.length === 7 && backing.cards.every((card) => (
    card.material === 100 && card.bodyExpected === 3_000
    && card.bodySupported === card.bodyExpected
    && card.thinExpected === 24 && card.thinSupported === card.thinExpected
    && card.isolatedAlphaPeak > 0
    && card.zeroStateExpected === 144 && card.zeroStateSupported === 144
    && card.guardExpected === 1_872 && card.guardTransparent === card.guardExpected
    && card.holeExpected === 36 && card.holeCentreTransparent >= 16
    && card.notchExpected === 96 && card.notchCentreTransparent >= 90
    && card.wrongOwnerExpected === 360 && card.wrongOwnerSupported === 360
    && card.waterExpected === 280 && card.waterSupported === 280
    && card.metalExpected === 280 && card.metalSupported === 280
    && card.exotExpected === 280 && card.exotSupported === 280
    && card.isozExpected === 280 && card.isozSupported === 280
    && card.liquidOwnerExpected === 320 && card.liquidOwnerSupported === 320
    && card.liquidNeighbourExpected === 320 && card.liquidNeighbourSupported === 320
    && card.solidOwnerExpected === 320 && card.solidOwnerSupported === 320
    && card.solidNeighbourExpected === 320 && card.solidNeighbourSupported === 320
  )), `${label}: DEUT state backing changed topology (${JSON.stringify(backing.cards.map(
    (card) => ({ ...card, bodyRgb: undefined, bodyBuckets: undefined,
      zeroStateRgb: undefined, wrongOwnerRgb: undefined, waterRgb: undefined,
      metalRgb: undefined, exotRgb: undefined, isozRgb: undefined,
      wallCoexistenceRgb: undefined,
      liquidNeighbourRgb: undefined, solidNeighbourRgb: undefined }),
  ))})`);
}

/** Focused exact-owner graphics proof for DRIC, NICE, QRTZ, and RIME. */
async function auditCrystallineGraphics(cdp, mode) {
  const started = performance.now();
  const stage = (name) => console.error(
    `[crystalline-graphics:${mode}] ${name} ${Math.round(performance.now() - started)}ms`,
  );
  await waitForStablePageCapture(cdp, `${mode} initial blank crystalline framebuffer`);
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.prepareCrystallineGraphicsFixture !== 'function'
      || typeof audit.crystallineGraphicsAtlas !== 'function'
      || typeof audit.setUnusualSolidStyling !== 'function') {
      throw new Error('Crystalline graphics audit API unavailable');
    }
    audit.prepareCrystallineGraphicsFixture();
    return true;
  })()`);
  const rawAtlas = await waitFor(() => evaluate(cdp, `(() => {
    const atlas = window.__ANIFOR_INPUT_AUDIT__.crystallineGraphicsAtlas();
    const cards = Array.isArray(atlas) ? atlas : atlas?.cards;
    return cards?.length === 4 ? atlas : false;
  })()`), 15_000, `${mode} crystalline graphics fixture`);
  const atlas = normalizeCrystallineGraphicsAtlas(rawAtlas);
  assert(atlas.cards.map(({ material }) => material).join(',') === '68,74,76,77'
      && atlas.cards.map(({ code }) => code).join(',') === 'DRIC,NICE,QRTZ,RIME'
      && atlas.cards.every(({ body }) => body.width === 144 && body.height === 104)
      && atlas.cards.map(({ fineStructure }) => fineStructure.length).join(',') === '95,138,88,136'
      && atlas.cards.every(({ motifProbes }) => motifProbes.length === 8)
      && atlas.cards.every(({ body }) => body.x % 32 === 20 && body.y % 32 === 20),
  `${mode}: crystalline atlas contract changed`);
  const semanticState = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const snapshot = audit.crystallineGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const inside = (x, y, rect) => x >= rect.x && y >= rect.y
      && x < rect.x + rect.width && y < rect.y + rect.height;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) for (let x = rect.x; x < rect.x + rect.width; x++) {
        if (audit.cell(x, y) !== material) return false;
      }
      return true;
    };
    return cards.map((entry) => {
      let bodyExact = true;
      for (let y = entry.body.y; y < entry.body.y + entry.body.height; y++) {
        for (let x = entry.body.x; x < entry.body.x + entry.body.width; x++) {
          const empty = inside(x, y, entry.authoredCavity) || inside(x, y, entry.openChimney);
          bodyExact = bodyExact && audit.cell(x, y) === (empty ? 0 : entry.material);
        }
      }
      return {
        bodyExact,
        cavityEmpty: exactRect(entry.authoredCavity, 0),
        chimneyEmpty: exactRect(entry.openChimney, 0),
        fineExact: entry.fineStructure.every(({ x, y }) => audit.cell(x, y) === entry.material),
        isolated: audit.cell(entry.isolated.x, entry.isolated.y),
        guardEmpty: exactRect(entry.guardedBlank, 0),
        crystalOwner: exactRect(entry.crystalContact.owner, entry.material),
        crystalNeighbour: exactRect(entry.crystalContact.neighbour, entry.crystalContact.neighbourMaterial),
        metalOwner: exactRect(entry.metalContact.owner, entry.material),
        metalNeighbour: exactRect(entry.metalContact.neighbour, entry.metalContact.neighbourMaterial),
      };
    });
  })()`);
  assert(semanticState.every((entry, index) => entry.bodyExact && entry.cavityEmpty
      && entry.chimneyEmpty && entry.fineExact && entry.isolated === atlas.cards[index].material
      && entry.guardEmpty && entry.crystalOwner && entry.crystalNeighbour
      && entry.metalOwner && entry.metalNeighbour),
  `${mode}: crystalline fixture lost semantic topology (${JSON.stringify(semanticState)})`);
  stage('fixture-ready');

  const setStyling = async (enabled) => evaluate(cdp, `(() => {
    window.__ANIFOR_INPUT_AUDIT__.setUnusualSolidStyling(${enabled}); return true;
  })()`);
  await setStyling(false);
  const flat = await waitForStablePageCapture(cdp, `${mode} flat crystalline framebuffer`);
  const flatBacking = await sampleCrystallineBacking(cdp);
  await setStyling(true);
  const styled = await waitForStablePageCapture(cdp, `${mode} styled crystalline framebuffer`);
  const styledBacking = await sampleCrystallineBacking(cdp);
  await setStyling(false);
  const repeated = await waitForStablePageCapture(cdp, `${mode} repeated flat crystalline framebuffer`);
  const repeatedBacking = await sampleCrystallineBacking(cdp);
  for (const [state, backing] of [
    ['flat', flatBacking], ['styled', styledBacking], ['repeated-flat', repeatedBacking],
  ]) assertCrystallineBacking(backing, `${mode} ${state}`);
  for (let index = 0; index < 4; index++) {
    const base = flatBacking.cards[index], changed = styledBacking.cards[index];
    const returned = repeatedBacking.cards[index];
    assert(base.semanticSignature === changed.semanticSignature
        && base.semanticSignature === returned.semanticSignature
        && base.alphaSignature === changed.alphaSignature
        && base.alphaSignature === returned.alphaSignature
        && base.supportSignature === changed.supportSignature
        && base.supportSignature === returned.supportSignature,
    `${mode}: ${base.code} styling changed semantic/alpha/support signatures`);
    assert(arraysEqual(base.metalContact.neighbourRgb, changed.metalContact.neighbourRgb)
        && arraysEqual(base.metalContact.neighbourRgb, returned.metalContact.neighbourRgb),
    `${mode}: ${base.code} styling leaked into Metal`);
  }
  const responses = summarizeCrystallineBackingResponses(flatBacking, styledBacking, repeatedBacking);
  for (const response of responses) {
    assert(response.rgbRms >= 0.05 && response.rgbRms <= 24
        && response.rgbPeak > 0 && response.rgbPeak <= 64
        && response.changedSampleRatio >= 0.02 && response.repeatRgbPeak === 0,
    `${mode}: ${response.code} crystalline response is absent, unbounded, or unstable (${JSON.stringify(response)})`);
  }
  assert(new Set(responses.map(({ responseSignature }) => responseSignature)).size === 4,
    `${mode}: crystalline body responses are not distinct`);
  assert(new Set(responses.map(({ motifVector }) => motifVector.join(','))).size === 4,
    `${mode}: crystalline motif probes are not distinct`);
  const normalFitRegions = atlas.cards.map((entry) => ({
    name: `${entry.code}-normal-fit-body`, x: entry.body.x + entry.body.width / 2,
    y: entry.body.y + entry.body.height / 2, radiusX: entry.body.width / 2,
    radiusY: entry.body.height / 2, signature: true, silhouette: true, fastSupport: true,
  }));
  const normalFit = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data, refracted: styled.capture.data,
    repeatedStraight: repeated.capture.data,
  }, normalFitRegions, flat.canvasRect);
  assert(normalFit.every((response) => response.rgbRms > 0 && response.rgbRms <= 32
      && response.rgbPeak > 0 && response.rgbPeak <= 64 && response.repeatRgbPeak === 0),
  `${mode}: crystalline identity is absent, unbounded, or unstable at normal fit (${JSON.stringify(normalFit)})`);
  stage('responses-ready');
  return {
    cards: responses.map((response, index) => ({
      ...response, normalFitRgbRms: normalFit[index].rgbRms,
      normalFitRgbPeak: normalFit[index].rgbPeak,
    })),
    exactRepeatedOff: responses.every(({ repeatRgbPeak }) => repeatRgbPeak === 0),
  };
}

async function sampleCrystallineBacking(cdp) {
  return evaluate(cdp, `(() => {
    const world = document.querySelector('.world-canvas');
    if (!(world instanceof HTMLCanvasElement)) throw new Error('World canvas unavailable');
    const copy = document.createElement('canvas'); copy.width = world.width; copy.height = world.height;
    const context = copy.getContext('2d', { willReadFrequently: true });
    if (!context) throw new Error('Crystalline backing sampler unavailable');
    context.drawImage(world, 0, 0);
    const pixels = context.getImageData(0, 0, copy.width, copy.height).data;
    const scaleX = copy.width / ${WORLD_WIDTH}, scaleY = copy.height / ${WORLD_HEIGHT};
    const snapshot = window.__ANIFOR_INPUT_AUDIT__.crystallineGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const key = ({ x, y }) => x + ',' + y;
    const rectPoints = (rect) => { const points = []; for (let y = rect.y; y < rect.y + rect.height; y++) {
      for (let x = rect.x; x < rect.x + rect.width; x++) points.push({ x, y });
    } return points; };
    const unique = (points) => [...new Map(points.map((point) => [key(point), point])).values()];
    const cellAlpha = ({ x, y }) => { let peak = 0; const left = Math.floor(x * scaleX), top = Math.floor(y * scaleY);
      const right = Math.max(left + 1, Math.floor((x + 1) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((y + 1) * scaleY));
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) peak = Math.max(peak, pixels[(py * copy.width + px) * 4 + 3]);
      return peak; };
    const centreAlpha = ({ x, y }) => pixels[(Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY)) * copy.width
      + Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX))) * 4 + 3];
    const sampleRgb = (points) => { const rgb = []; for (const { x, y } of points) {
      const px = Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX));
      const py = Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY));
      const offset = (py * copy.width + px) * 4; rgb.push(pixels[offset], pixels[offset + 1], pixels[offset + 2]);
    } return rgb; };
    const grid = (rect, step = 2) => { const points = []; for (let y = rect.y; y < rect.y + rect.height; y += step) {
      for (let x = rect.x; x < rect.x + rect.width; x += step) points.push({ x, y });
    } return { width: Math.ceil(rect.width / step), height: Math.ceil(rect.height / step), rgb: sampleRgb(points) }; };
    const contact = (control) => { const owner = rectPoints(control.owner), neighbour = rectPoints(control.neighbour); return {
      ownerExpected: owner.length, ownerSupported: owner.filter((point) => cellAlpha(point) > 0).length,
      neighbourExpected: neighbour.length, neighbourSupported: neighbour.filter((point) => cellAlpha(point) > 0).length,
      neighbourRgb: sampleRgb(neighbour),
    }; };
    return { scaleX, scaleY, cards: cards.map((entry) => {
      const emptyKeys = new Set([...rectPoints(entry.authoredCavity), ...rectPoints(entry.openChimney)].map(key));
      const bodyPoints = rectPoints(entry.body).filter((point) => !emptyKeys.has(key(point)));
      const fine = unique(entry.fineStructure), guard = rectPoints(entry.guardedBlank);
      const cavity = rectPoints(entry.authoredCavity), chimney = rectPoints(entry.openChimney);
      let alphaSignature = 2166136261, supportSignature = 2166136261, semanticSignature = 2166136261;
      const left = Math.floor(entry.card.x * scaleX), top = Math.floor(entry.card.y * scaleY);
      const right = Math.floor((entry.card.x + entry.card.width) * scaleX);
      const bottom = Math.floor((entry.card.y + entry.card.height) * scaleY);
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        const alpha = pixels[(py * copy.width + px) * 4 + 3];
        alphaSignature = Math.imul(alphaSignature ^ alpha, 16777619) >>> 0;
        supportSignature = Math.imul(supportSignature ^ Number(alpha > 0), 16777619) >>> 0;
      }
      for (let y = entry.card.y; y < entry.card.y + entry.card.height; y++) for (let x = entry.card.x; x < entry.card.x + entry.card.width; x++) {
        semanticSignature = Math.imul(semanticSignature ^ window.__ANIFOR_INPUT_AUDIT__.cell(x, y), 16777619) >>> 0;
      }
      const body = grid(entry.body);
      const motif = (kind) => sampleRgb(entry.motifProbes.map((probe) => probe[kind]));
      return { code: entry.code, material: entry.material, semanticSignature, alphaSignature, supportSignature,
        bodyExpected: bodyPoints.length, bodySupported: bodyPoints.filter((point) => cellAlpha(point) > 0).length,
        fineExpected: fine.length, fineSupported: fine.filter((point) => cellAlpha(point) > 0).length,
        isolatedAlphaPeak: cellAlpha(entry.isolated), guardExpected: guard.length,
        guardTransparent: guard.filter((point) => cellAlpha(point) === 0).length,
        cavityExpected: cavity.length, cavityCentreTransparent: cavity.filter((point) => centreAlpha(point) === 0).length,
        chimneyExpected: chimney.length, chimneyCentreTransparent: chimney.filter((point) => centreAlpha(point) === 0).length,
        crystalContact: contact(entry.crystalContact), metalContact: contact(entry.metalContact),
        bodyWidth: body.width, bodyHeight: body.height, bodyRgb: body.rgb,
        motifRgb: { key: motif('key'), facet: motif('facet'), joint: motif('joint'),
          shadow: motif('shadow'), interstitial: motif('interstitial') },
      };
    }) };
  })()`);
}

function assertCrystallineBacking(backing, label) {
  const fineCounts = [95, 138, 88, 136];
  assert(Number.isInteger(backing.scaleX) && Number.isInteger(backing.scaleY)
      && backing.scaleX > 0 && backing.scaleY > 0,
  `${label}: crystalline backing does not preserve integral scaling`);
  assert(backing.cards.map(({ material }) => material).join(',') === '68,74,76,77'
      && backing.cards.every((card, index) => card.bodyExpected === 14_704
        && card.bodySupported === card.bodyExpected
        && card.fineExpected === fineCounts[index] && card.fineSupported === card.fineExpected
        && card.isolatedAlphaPeak > 0 && card.guardExpected === 2_800
        && card.guardTransparent === card.guardExpected
        && card.cavityExpected === 120 && card.cavityCentreTransparent / card.cavityExpected >= 0.65
        && card.chimneyExpected === 152 && card.chimneyCentreTransparent / card.chimneyExpected >= 0.75
        && card.crystalContact.ownerExpected === 192 && card.crystalContact.ownerSupported === 192
        && card.crystalContact.neighbourExpected === 256 && card.crystalContact.neighbourSupported === 256
        && card.metalContact.ownerExpected === 192 && card.metalContact.ownerSupported === 192
        && card.metalContact.neighbourExpected === 256 && card.metalContact.neighbourSupported === 256),
  `${label}: crystalline backing changed topology (${JSON.stringify(backing.cards.map((card) => ({
    ...card, bodyRgb: undefined, motifRgb: undefined,
    crystalContact: { ...card.crystalContact, neighbourRgb: undefined },
    metalContact: { ...card.metalContact, neighbourRgb: undefined },
  })))})`);
}

function summarizeCrystallineBackingResponses(flat, styled, repeated) {
  return flat.cards.map((base, index) => {
    const changed = styled.cards[index], returned = repeated.cards[index];
    let squared = 0, peak = 0, repeatPeak = 0, changedSamples = 0, signature = 2166136261;
    const buckets = new Float64Array(16), axisMap = [];
    for (let offset = 0; offset < base.bodyRgb.length; offset += 3) {
      const sample = offset / 3, x = sample % base.bodyWidth, y = Math.floor(sample / base.bodyWidth);
      const bucket = Math.min(3, Math.floor(y * 4 / base.bodyHeight)) * 4
        + Math.min(3, Math.floor(x * 4 / base.bodyWidth));
      let any = false, axis = 0;
      for (let channel = 0; channel < 3; channel++) {
        const delta = changed.bodyRgb[offset + channel] - base.bodyRgb[offset + channel];
        squared += delta * delta; peak = Math.max(peak, Math.abs(delta));
        buckets[bucket] += Math.abs(delta); any ||= delta !== 0; axis += delta / 3;
        signature = Math.imul(signature ^ (delta + 128), 16777619) >>> 0;
        repeatPeak = Math.max(repeatPeak, Math.abs(returned.bodyRgb[offset + channel] - base.bodyRgb[offset + channel]));
      }
      axisMap.push(axis); changedSamples += Number(any);
    }
    const total = buckets.reduce((sum, value) => sum + value, 0), motifAxis = {};
    for (const kind of ['key', 'facet', 'joint', 'shadow', 'interstitial']) {
      const before = base.motifRgb[kind], after = changed.motifRgb[kind]; let sum = 0;
      for (let offset = 0; offset < before.length; offset += 3) sum += (
        after[offset] - before[offset] + after[offset + 1] - before[offset + 1]
          + after[offset + 2] - before[offset + 2]
      ) / 3;
      motifAxis[kind] = sum / Math.max(1, before.length / 3);
    }
    return { code: base.code, material: base.material,
      rgbRms: Math.sqrt(squared / Math.max(1, base.bodyRgb.length)), rgbPeak: peak,
      changedSampleRatio: changedSamples / Math.max(1, base.bodyRgb.length / 3),
      repeatRgbPeak: repeatPeak, responseSignature: signature,
      profile: Array.from(buckets, (value) => total > 0 ? value / total : 0),
      axisMap, motifAxis, motifVector: ['key', 'facet', 'joint', 'shadow', 'interstitial'].map((kind) => motifAxis[kind]),
    };
  });
}

async function sampleSpongeBacking(cdp) {
  return evaluate(cdp, `(() => {
    const world = document.querySelector('.world-canvas');
    if (!(world instanceof HTMLCanvasElement)) throw new Error('World canvas unavailable');
    const copy = document.createElement('canvas');
    copy.width = world.width;
    copy.height = world.height;
    const context = copy.getContext('2d', { willReadFrequently: true });
    if (!context) throw new Error('SPNG backing sampler unavailable');
    context.drawImage(world, 0, 0);
    const pixels = context.getImageData(0, 0, copy.width, copy.height).data;
    const scaleX = copy.width / ${WORLD_WIDTH};
    const scaleY = copy.height / ${WORLD_HEIGHT};
    const snapshot = window.__ANIFOR_INPUT_AUDIT__.spongeGraphicsAtlas();
    const entry = (Array.isArray(snapshot) ? snapshot : snapshot.cards)[0];
    const key = ({ x, y }) => x + ',' + y;
    const rectPoints = (rect) => {
      const points = [];
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) points.push({ x, y });
      }
      return points;
    };
    const uniquePoints = (points) => [...new Map(points.map((point) => [key(point), point])).values()];
    const cellAlpha = ({ x, y }) => {
      const left = Math.floor(x * scaleX);
      const top = Math.floor(y * scaleY);
      const right = Math.max(left + 1, Math.floor((x + 1) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((y + 1) * scaleY));
      let minimum = 255;
      let peak = 0;
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        const alpha = pixels[(py * copy.width + px) * 4 + 3];
        minimum = Math.min(minimum, alpha);
        peak = Math.max(peak, alpha);
      }
      return { minimum, peak };
    };
    const samplePointRgb = (points) => {
      const rgb = [];
      for (const { x, y } of points) {
        const px = Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX));
        const py = Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY));
        const offset = (py * copy.width + px) * 4;
        rgb.push(pixels[offset], pixels[offset + 1], pixels[offset + 2]);
      }
      return rgb;
    };
    const sampleGridRgb = (rect, step = 1) => {
      const points = [];
      for (let y = rect.y; y < rect.y + rect.height; y += step) {
        for (let x = rect.x; x < rect.x + rect.width; x += step) points.push({ x, y });
      }
      return {
        width: Math.ceil(rect.width / step),
        height: Math.ceil(rect.height / step),
        rgb: samplePointRgb(points),
      };
    };
    const holePoints = entry.holes.flatMap(rectPoints);
    const notchPoints = entry.openNotches.flatMap(rectPoints);
    const emptyKeys = new Set([...holePoints, ...notchPoints].map(key));
    const bodyPoints = rectPoints(entry.body).filter((point) => !emptyKeys.has(key(point)));
    const protectedHolePoints = entry.holes.flatMap((rect) => rectPoints({
      x: rect.x + 1, y: rect.y + 1,
      width: Math.max(0, rect.width - 2), height: Math.max(0, rect.height - 2),
    }));
    const ribPoints = uniquePoints(entry.ribs.flatMap(rectPoints));
    const guardPoints = rectPoints(entry.guardedBlank);
    const cardLeft = Math.floor(entry.card.x * scaleX);
    const cardTop = Math.floor(entry.card.y * scaleY);
    const cardRight = Math.floor((entry.card.x + entry.card.width) * scaleX);
    const cardBottom = Math.floor((entry.card.y + entry.card.height) * scaleY);
    let alphaSignature = 2166136261;
    let supportSignature = 2166136261;
    for (let py = cardTop; py < cardBottom; py++) for (let px = cardLeft; px < cardRight; px++) {
      const alpha = pixels[(py * copy.width + px) * 4 + 3];
      alphaSignature = Math.imul(alphaSignature ^ alpha, 16777619) >>> 0;
      supportSignature = Math.imul(supportSignature ^ Number(alpha > 0), 16777619) >>> 0;
    }
    let semanticSignature = 2166136261;
    for (let y = entry.card.y; y < entry.card.y + entry.card.height; y++) {
      for (let x = entry.card.x; x < entry.card.x + entry.card.width; x++) {
        semanticSignature = Math.imul(
          semanticSignature ^ window.__ANIFOR_INPUT_AUDIT__.cell(x, y), 16777619,
        ) >>> 0;
      }
    }
    const body = sampleGridRgb(entry.body, 2);
    return {
      width: copy.width,
      height: copy.height,
      scaleX,
      scaleY,
      material: entry.material,
      bodyExpected: bodyPoints.length,
      bodySupported: bodyPoints.filter((point) => cellAlpha(point).peak > 0).length,
      holeExpected: holePoints.length,
      holeOpen: holePoints.filter((point) => cellAlpha(point).minimum === 0).length,
      protectedHoleExpected: protectedHolePoints.length,
      protectedHoleTransparent: protectedHolePoints.filter((point) => cellAlpha(point).peak === 0).length,
      notchExpected: notchPoints.length,
      notchOpen: notchPoints.filter((point) => cellAlpha(point).minimum === 0).length,
      ribExpected: ribPoints.length,
      ribSupported: ribPoints.filter((point) => cellAlpha(point).peak > 0).length,
      isolatedAlphaPeak: cellAlpha(entry.isolated).peak,
      guardedBlankExpected: guardPoints.length,
      guardedBlankTransparent: guardPoints.filter((point) => cellAlpha(point).peak === 0).length,
      contacts: entry.contacts.map((contact) => {
        const owner = rectPoints(contact.owner);
        const neighbour = rectPoints(contact.neighbour);
        return {
          neighbourMaterial: contact.neighbourMaterial,
          ownerExpected: owner.length,
          ownerSupported: owner.filter((point) => cellAlpha(point).peak > 0).length,
          neighbourExpected: neighbour.length,
          neighbourSupported: neighbour.filter((point) => cellAlpha(point).peak > 0).length,
          ownerRgb: samplePointRgb(owner),
          neighbourRgb: samplePointRgb(neighbour),
        };
      }),
      semanticSignature,
      alphaSignature,
      supportSignature,
      bodyWidth: body.width,
      bodyHeight: body.height,
      bodyRgb: body.rgb,
      surfaceRgb: samplePointRgb(rectPoints(entry.surfaceProbe)),
      coreRgb: samplePointRgb(rectPoints(entry.coreProbe)),
      ribRgb: samplePointRgb(ribPoints),
      poreCoreRgb: samplePointRgb(entry.porePairs.map(({ core }) => core)),
      poreRimRgb: samplePointRgb(entry.porePairs.map(({ litRim }) => litRim)),
    };
  })()`);
}

function assertSpongeBacking(backing, label) {
  assert(Number.isInteger(backing.scaleX) && Number.isInteger(backing.scaleY)
      && backing.scaleX > 0 && backing.scaleY > 0,
  `${label}: backing does not preserve integral world scaling (${backing.scaleX}x${backing.scaleY})`);
  assert(backing.material === 81 && backing.bodyExpected === 48_840
      && backing.bodySupported === backing.bodyExpected
      && backing.holeExpected === 232 && backing.holeOpen === backing.holeExpected
      && backing.protectedHoleExpected === 134
      && backing.protectedHoleTransparent === backing.protectedHoleExpected
      && backing.notchExpected === 208 && backing.notchOpen === backing.notchExpected
      && backing.ribExpected === 344 && backing.ribSupported === backing.ribExpected
      && backing.isolatedAlphaPeak > 0
      && backing.guardedBlankExpected === 12_544
      && backing.guardedBlankTransparent === backing.guardedBlankExpected
      && backing.contacts.length === 3
      && backing.contacts.every((contact, index) => contact.neighbourMaterial === [2, 23, 1][index]
        && contact.ownerExpected === 560 && contact.ownerSupported === contact.ownerExpected
        && contact.neighbourExpected === 728
        && contact.neighbourSupported === contact.neighbourExpected),
  `${label}: SPNG backing changed body/hole/notch/rib/isolated/contact topology (${JSON.stringify(
    compactSpongeBacking(backing),
  )})`);
}

function compactSpongeBacking(backing) {
  const {
    bodyRgb: _bodyRgb, surfaceRgb: _surfaceRgb, coreRgb: _coreRgb, ribRgb: _ribRgb,
    poreCoreRgb: _poreCoreRgb, poreRimRgb: _poreRimRgb, contacts, ...summary
  } = backing;
  return {
    ...summary,
    scale: `${backing.scaleX}x${backing.scaleY}`,
    contacts: contacts.map(({ ownerRgb: _ownerRgb, neighbourRgb: _neighbourRgb, ...contact }) => contact),
  };
}

function summarizeSpongeBackingResponse(flat, styled, repeated) {
  const response = (base, changed, returned, width = base.length / 3, height = 1) => {
    assert(base.length === changed.length && base.length === returned.length,
      'SPNG backing response geometry changed');
    let squared = 0;
    let peak = 0;
    let repeatPeak = 0;
    let changedSamples = 0;
    const buckets = new Float64Array(16);
    for (let offset = 0; offset < base.length; offset += 3) {
      const sample = offset / 3;
      const x = sample % width;
      const y = Math.floor(sample / width);
      const bucket = Math.min(3, Math.floor(y * 4 / Math.max(1, height))) * 4
        + Math.min(3, Math.floor(x * 4 / Math.max(1, width)));
      let sampleChanged = false;
      for (let channel = 0; channel < 3; channel++) {
        const delta = changed[offset + channel] - base[offset + channel];
        const repeat = returned[offset + channel] - base[offset + channel];
        squared += delta * delta;
        peak = Math.max(peak, Math.abs(delta));
        repeatPeak = Math.max(repeatPeak, Math.abs(repeat));
        buckets[bucket] += Math.abs(delta);
        sampleChanged ||= delta !== 0;
      }
      changedSamples += Number(sampleChanged);
    }
    const samples = Math.max(1, base.length / 3);
    return {
      rms: Math.sqrt(squared / Math.max(1, base.length)),
      peak,
      repeatPeak,
      changedRatio: changedSamples / samples,
      buckets,
    };
  };
  const body = response(
    flat.bodyRgb, styled.bodyRgb, repeated.bodyRgb, flat.bodyWidth, flat.bodyHeight,
  );
  const surface = response(flat.surfaceRgb, styled.surfaceRgb, repeated.surfaceRgb);
  const core = response(flat.coreRgb, styled.coreRgb, repeated.coreRgb);
  const ribs = response(flat.ribRgb, styled.ribRgb, repeated.ribRgb);
  const contactOwners = flat.contacts.map((contact, index) => response(
    contact.ownerRgb, styled.contacts[index].ownerRgb, repeated.contacts[index].ownerRgb,
  ));
  let passedPairs = 0;
  let poreContrast = 0;
  let poreRepeatPeak = 0;
  const luma = (rgb, offset) => rgb[offset] * 0.2126
    + rgb[offset + 1] * 0.7152 + rgb[offset + 2] * 0.0722;
  for (let offset = 0; offset < flat.poreCoreRgb.length; offset += 3) {
    const coreDelta = luma(styled.poreCoreRgb, offset) - luma(flat.poreCoreRgb, offset);
    const rimDelta = luma(styled.poreRimRgb, offset) - luma(flat.poreRimRgb, offset);
    const contrast = rimDelta - coreDelta;
    poreContrast += contrast;
    passedPairs += Number(contrast >= 1);
    for (let channel = 0; channel < 3; channel++) {
      poreRepeatPeak = Math.max(
        poreRepeatPeak,
        Math.abs(repeated.poreCoreRgb[offset + channel] - flat.poreCoreRgb[offset + channel]),
        Math.abs(repeated.poreRimRgb[offset + channel] - flat.poreRimRgb[offset + channel]),
      );
    }
  }
  const total = Math.max(1, body.buckets.reduce((sum, value) => sum + value, 0));
  return {
    rgbRms: round(body.rms, 4),
    rgbPeak: body.peak,
    changedSampleRatio: round(body.changedRatio, 5),
    surfaceRgbRms: round(surface.rms, 4),
    coreRgbRms: round(core.rms, 4),
    ribRgbRms: round(ribs.rms, 4),
    contactOwnerRgbRms: contactOwners.map(({ rms }) => round(rms, 4)),
    repeatRgbPeak: Math.max(
      body.repeatPeak, surface.repeatPeak, core.repeatPeak, ribs.repeatPeak,
      poreRepeatPeak, ...contactOwners.map(({ repeatPeak }) => repeatPeak),
    ),
    porePairPassRatio: round(passedPairs / Math.max(1, flat.poreCoreRgb.length / 3), 5),
    poreContrastMean: round(poreContrast / Math.max(1, flat.poreCoreRgb.length / 3), 4),
    responseProfile: Array.from(body.buckets, (value) => round(value / total, 5)),
  };
}

/** Focused semantic, atmosphere-volume, and RGB-identity proof for all 17 gases. */
async function auditGasIdentityGraphics(cdp, mode) {
  const started = performance.now();
  const stage = (name) => console.error(
    `[gas-identity-graphics:${mode}] ${name} ${Math.round(performance.now() - started)}ms`,
  );
  const blank = await waitForStablePageCapture(cdp, `${mode} initial blank gas-identity framebuffer`);
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.prepareGasIdentityGraphicsFixture !== 'function'
      || typeof audit.gasIdentityGraphicsAtlas !== 'function'
      || typeof audit.setGasIdentityStyling !== 'function') {
      throw new Error('Gas identity graphics audit API unavailable');
    }
    audit.prepareGasIdentityGraphicsFixture();
    return true;
  })()`);
  const rawAtlas = await waitFor(() => evaluate(cdp, `(() => {
    const atlas = window.__ANIFOR_INPUT_AUDIT__.gasIdentityGraphicsAtlas();
    const cards = Array.isArray(atlas) ? atlas : atlas?.cards;
    return cards?.length === 17 ? atlas : false;
  })()`), 15_000, `${mode} gas identity graphics fixture`);
  const atlas = normalizeGasIdentityGraphicsAtlas(rawAtlas);
  const expectedMaterials = [5, 15, 17, 39, 40, 41, 42, 63, 64, 65, 66, 87, 98, 114, 195, 205, 215];
  const expectedCodes = [
    'SMKE', 'WTRV', 'GAS', 'O2', 'H2', 'CO2', 'NBLE', 'BOYL', 'CAUS',
    'FOG', 'RFRG', 'CFLM', 'AMTR', 'WARP', 'BIZG', 'MORT', 'VRSG',
  ];
  assert(atlas.cards.length === 17
      && atlas.cards.every(({ material, code }, index) => (
        material === expectedMaterials[index] && code === expectedCodes[index]
      )),
  `${mode}: gas identity atlas order changed (${JSON.stringify(atlas.cards.map(
    ({ code, material }) => ({ code, material }),
  ))})`);

  const fieldStyles = await waitFor(() => evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.gasIdentityStyle !== 'function') {
      throw new Error('Gas identity field-style readback unavailable');
    }
    const snapshot = audit.gasIdentityGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const styles = cards.map((entry) => audit.gasIdentityStyle(
      entry.denseProbe.x + Math.floor(entry.denseProbe.width / 2),
      entry.denseProbe.y + Math.floor(entry.denseProbe.height / 2),
    ));
    return styles.every((style, index) => style === index + 1) ? styles : false;
  })()`), 15_000, `${mode} gas identity atmosphere styles`);
  assert(fieldStyles.every((style, index) => style === index + 1),
    `${mode}: gas identity atmosphere styles are not ordered 1..17 (${fieldStyles})`);

  const semanticState = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const snapshot = audit.gasIdentityGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const inside = (x, y, rect) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    return cards.map((entry) => {
      let cloudExact = true;
      for (let y = entry.cloudSeed.y; y < entry.cloudSeed.y + entry.cloudSeed.height; y++) {
        for (let x = entry.cloudSeed.x; x < entry.cloudSeed.x + entry.cloudSeed.width; x++) {
          const empty = inside(x, y, entry.authoredVoid) || inside(x, y, entry.openChannel);
          cloudExact = cloudExact && audit.cell(x, y) === (empty ? 0 : entry.material);
        }
      }
      return {
        code: entry.code,
        material: entry.material,
        cloudExact,
        denseProbeExact: exactRect(entry.denseProbe, entry.material),
        authoredVoidEmpty: exactRect(entry.authoredVoid, 0),
        openChannelEmpty: exactRect(entry.openChannel, 0),
        sparseWispsExact: entry.sparseWisps.every(
          (point) => audit.cell(point.x, point.y) === entry.material,
        ),
        wispGapEmpty: exactRect(entry.wispGap, 0),
        isolated: audit.cell(entry.isolated.x, entry.isolated.y),
        guardedBlankEmpty: exactRect(entry.guardedBlank, 0),
        liquidOwnerExact: exactRect(entry.liquidContact.owner, entry.material),
        liquidUnlikeExact: exactRect(
          entry.liquidContact.unlike, entry.liquidContact.unlikeMaterial,
        ),
        liquidUnlikeMaterial: entry.liquidContact.unlikeMaterial,
        solidOwnerExact: exactRect(entry.solidContact.owner, entry.material),
        solidUnlikeExact: exactRect(
          entry.solidContact.unlike, entry.solidContact.unlikeMaterial,
        ),
        solidUnlikeMaterial: entry.solidContact.unlikeMaterial,
      };
    });
  })()`);
  assert(semanticState.every((entry) => entry.cloudExact && entry.denseProbeExact
      && entry.authoredVoidEmpty && entry.openChannelEmpty && entry.sparseWispsExact
      && entry.wispGapEmpty && entry.isolated === entry.material && entry.guardedBlankEmpty
      && entry.liquidOwnerExact && entry.liquidUnlikeExact && entry.liquidUnlikeMaterial === 2
      && entry.solidOwnerExact && entry.solidUnlikeExact && entry.solidUnlikeMaterial === 23),
  `${mode}: gas identity fixture lost authored semantics (${JSON.stringify(semanticState)})`);
  stage('fixture-ready');

  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setGasIdentityStyling(false); true');
  const flat = await waitForStablePageCapture(cdp, `${mode} flat gas-identity framebuffer`);
  const flatBacking = await sampleGasIdentityBackingTopology(cdp);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setGasIdentityStyling(true); true');
  const styled = await waitForStablePageCapture(cdp, `${mode} styled gas-identity framebuffer`);
  const styledBacking = await sampleGasIdentityBackingTopology(cdp);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setGasIdentityStyling(false); true');
  const repeated = await waitForStablePageCapture(cdp, `${mode} repeated flat gas-identity framebuffer`);
  const repeatedBacking = await sampleGasIdentityBackingTopology(cdp);
  for (const [state, backing] of [
    ['flat', flatBacking], ['styled', styledBacking], ['repeated-flat', repeatedBacking],
  ]) assertGasIdentityBackingTopology(backing, `${mode} ${state}`);

  assert(flatBacking.cards.every((card, index) => (
    card.alphaSignature === styledBacking.cards[index].alphaSignature
      && card.alphaSignature === repeatedBacking.cards[index].alphaSignature
      && card.supportSignature === styledBacking.cards[index].supportSignature
      && card.supportSignature === repeatedBacking.cards[index].supportSignature
  )), `${mode}: gas identity styling changed backing alpha/support (${JSON.stringify({
    flat: compactGasIdentityTopology(flatBacking),
    styled: compactGasIdentityTopology(styledBacking),
    repeated: compactGasIdentityTopology(repeatedBacking),
  })})`);
  const controlLeaks = flatBacking.cards.flatMap((card, index) => {
    const changed = styledBacking.cards[index];
    const returned = repeatedBacking.cards[index];
    const leaks = [];
    if (!arraysEqual(card.liquidUnlikeRgb, changed.liquidUnlikeRgb)
      || !arraysEqual(card.liquidUnlikeRgb, returned.liquidUnlikeRgb)) leaks.push({
      control: 'Water',
      styled: summarizeExactRgbDifference(card.liquidUnlikeRgb, changed.liquidUnlikeRgb),
      repeated: summarizeExactRgbDifference(card.liquidUnlikeRgb, returned.liquidUnlikeRgb),
    });
    if (!arraysEqual(card.solidUnlikeRgb, changed.solidUnlikeRgb)
      || !arraysEqual(card.solidUnlikeRgb, returned.solidUnlikeRgb)) leaks.push({
      control: 'Metal',
      styled: summarizeExactRgbDifference(card.solidUnlikeRgb, changed.solidUnlikeRgb),
      repeated: summarizeExactRgbDifference(card.solidUnlikeRgb, returned.solidUnlikeRgb),
    });
    return leaks.map((leak) => ({ code: card.code, ...leak }));
  });
  assert(controlLeaks.length === 0,
    `${mode}: gas identity styling leaked into contact controls (${JSON.stringify(controlLeaks)})`);

  const backingResponses = summarizeGasIdentityBackingResponses(
    flatBacking, styledBacking, repeatedBacking,
  );
  assert(backingResponses.every(({ rgbRms, rgbPeak, repeatRgbPeak }) => (
    rgbRms >= 0.03 && rgbRms <= 12 && rgbPeak > 0 && rgbPeak <= 20 && repeatRgbPeak === 0
  )), `${mode}: gas identity response is absent, unbounded, or non-repeatable (${JSON.stringify(backingResponses)})`);
  assert(backingResponses.every(({ responseProfile }) => (
    responseProfile.length === 16
      && Math.abs(responseProfile.reduce((sum, value) => sum + value, 0) - 1) <= 0.001
  )), `${mode}: gas identity response profiles are not normalized 4x4 fields (${JSON.stringify(backingResponses)})`);
  assert(new Set(backingResponses.map(({ responseSignature }) => responseSignature)).size === 17,
    `${mode}: gas identities do not have 17 distinct backing responses (${JSON.stringify(backingResponses)})`);
  assert(backingResponses.every(({ haloRgbRms, haloRgbPeak, haloChangedSampleRatio }) => (
    haloRgbRms >= 0.01 && haloRgbRms <= 12 && haloRgbPeak > 0 && haloRgbPeak <= 20
      && haloChangedSampleRatio >= 0.10
  )), `${mode}: gas styling did not reshape the empty-semantic atmosphere halo (${JSON.stringify(backingResponses)})`);

  const volumeRegions = atlas.cards.map((entry) => ({
    name: `gas-identity-${entry.code}`,
    x: entry.cloudSeed.x + entry.cloudSeed.width / 2,
    y: entry.cloudSeed.y + entry.cloudSeed.height / 2,
    radiusX: entry.cloudSeed.width / 2 + 2,
    radiusY: entry.cloudSeed.height / 2 + 2,
    signature: true,
    silhouette: true,
    fastSupport: true,
  }));
  const atlasBounds = containingCellularRegion(atlas.cards.map(({ card }) => card));
  const responses = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: styled.capture.data,
    repeatedStraight: repeated.capture.data,
  }, [...volumeRegions, { name: 'gas-identity-atlas', ...atlasBounds }], flat.canvasRect);
  const atlasResponse = responses.at(-1);
  assert(atlasResponse.repeatRgbPeak === 0,
    `${mode}: gas identity flat→styled→flat framebuffer was not exact (${JSON.stringify(atlasResponse)})`);
  assert(responses.slice(0, 17).every((sample) => (
    sample.rgbRms > 0 && sample.rgbRms <= 12 && sample.rgbPeak > 0 && sample.rgbPeak <= 24
      && sample.repeatRgbPeak === 0
  )), `${mode}: a gas identity has no bounded composed response (${JSON.stringify(responses.slice(0, 17))})`);
  const [flatSupport, styledSupport] = await Promise.all([
    samplePageRegions(
      cdp, flat.capture.data, volumeRegions,
      blank.capture.data, blank.reference.data, flat.canvasRect,
    ),
    samplePageRegions(
      cdp, styled.capture.data, volumeRegions,
      blank.capture.data, blank.reference.data, flat.canvasRect,
    ),
  ]);
  assert(flatSupport.every((sample) => sample.visible > 0 && sample.worldArea > 0)
      && styledSupport.every((sample) => sample.visible > 0 && sample.worldArea > 0),
  `${mode}: a gas atmosphere volume is not visible (${JSON.stringify({ flatSupport, styledSupport })})`);
  stage('responses-ready');

  const cardSignatures = atlas.cards.map((entry, index) => ({
    index: entry.index,
    material: entry.material,
    code: entry.code,
    flatSignature: flatSupport[index].signature,
    styledSignature: styledSupport[index].signature,
    flatVisible: flatSupport[index].visible,
    styledVisible: styledSupport[index].visible,
    rgbRms: responses[index].rgbRms,
    rgbPeak: responses[index].rgbPeak,
    responseSignature: responses[index].responseSignature,
    backingRgbRms: backingResponses[index].rgbRms,
    backingRgbPeak: backingResponses[index].rgbPeak,
    backingChangedSampleRatio: backingResponses[index].changedSampleRatio,
    haloRgbRms: backingResponses[index].haloRgbRms,
    haloRgbPeak: backingResponses[index].haloRgbPeak,
    haloChangedSampleRatio: backingResponses[index].haloChangedSampleRatio,
    backingRepeatRgbPeak: backingResponses[index].repeatRgbPeak,
    backingResponseSignature: backingResponses[index].responseSignature,
    backingResponseProfile: backingResponses[index].responseProfile,
  }));
  const sumCards = (field) => flatBacking.cards.reduce((sum, card) => sum + card[field], 0);
  const ratioRange = (numerator, denominator) => {
    const values = flatBacking.cards.map((card) => card[numerator]
      / Math.max(0.0001, card[denominator]));
    return [round(Math.min(...values), 5), round(Math.max(...values), 5)];
  };
  const foldSignatures = (cards, field) => cards.reduce(
    (hash, card) => Math.imul(hash ^ card[field], 16777619) >>> 0, 2166136261,
  );
  return {
    cards: cardSignatures.length,
    cloudSeedCells: atlas.cards.reduce((sum, { cloudSeed, authoredVoid, openChannel }) => (
      sum + cloudSeed.width * cloudSeed.height
        - authoredVoid.width * authoredVoid.height
        - openChannel.width * openChannel.height
        + Math.max(0, Math.min(authoredVoid.x + authoredVoid.width, openChannel.x + openChannel.width)
          - Math.max(authoredVoid.x, openChannel.x))
          * Math.max(0, Math.min(authoredVoid.y + authoredVoid.height, openChannel.y + openChannel.height)
            - Math.max(authoredVoid.y, openChannel.y))
    ), 0),
    authoredVoidCells: atlas.authoredVoids.length,
    openChannelCells: atlas.openChannels.length,
    sparseWispCarriers: atlas.sparseWisps.length,
    wispGaps: atlas.wispGaps.length,
    isolatedControls: atlas.isolated.length,
    guardedBlanks: atlas.guardedBlanks.length,
    unlikeWaterContacts: atlas.liquidContacts.length,
    unlikeMetalContacts: atlas.solidContacts.length,
    exactRepeatedOff: atlasResponse.repeatRgbPeak === 0,
    topology: {
      cloudSupport: `${sumCards('cloudSupported')}/${sumCards('cloudExpected')}`,
      haloSupport: `${sumCards('haloSupported')}/${sumCards('haloExpected')}`,
      sparseWispSupport: `${sumCards('wispSupported')}/${sumCards('wispExpected')}`,
      guardedBlankTransparency:
        `${sumCards('guardedBlankTransparent')}/${sumCards('guardedBlankExpected')}`,
      waterContactSupport:
        `${sumCards('liquidUnlikeSupported')}/${sumCards('liquidUnlikeExpected')}`,
      metalContactSupport:
        `${sumCards('solidUnlikeSupported')}/${sumCards('solidUnlikeExpected')}`,
      voidToDenseAlphaRatio: ratioRange('centralVoidAlphaMean', 'denseAlphaMean'),
      channelToShoulderAlphaRatio:
        ratioRange('channelAlphaMean', 'channelShoulderAlphaMean'),
      gapToWispAlphaRatio: ratioRange('gapAlphaMean', 'wispAlphaMean'),
      alphaHashes: [flatBacking, styledBacking, repeatedBacking].map(
        (backing) => foldSignatures(backing.cards, 'alphaSignature'),
      ),
      supportHashes: [flatBacking, styledBacking, repeatedBacking].map(
        (backing) => foldSignatures(backing.cards, 'supportSignature'),
      ),
    },
    cardSignatures,
  };
}

function summarizeExactRgbDifference(left, right) {
  let squared = 0;
  let peak = 0;
  let changed = 0;
  for (let index = 0; index < left.length; index++) {
    const delta = right[index] - left[index];
    squared += delta * delta;
    peak = Math.max(peak, Math.abs(delta));
    changed += Number(delta !== 0);
  }
  return {
    rms: round(Math.sqrt(squared / Math.max(1, left.length)), 4),
    peak,
    changedChannels: changed,
  };
}

async function sampleGasIdentityBackingTopology(cdp) {
  return evaluate(cdp, `(() => {
    const world = document.querySelector('.world-canvas');
    if (!(world instanceof HTMLCanvasElement)) throw new Error('World canvas unavailable');
    const copy = document.createElement('canvas');
    copy.width = world.width;
    copy.height = world.height;
    const context = copy.getContext('2d', { willReadFrequently: true });
    if (!context) throw new Error('Gas identity backing sampler unavailable');
    context.drawImage(world, 0, 0);
    const pixels = context.getImageData(0, 0, copy.width, copy.height).data;
    const scaleX = copy.width / ${WORLD_WIDTH};
    const scaleY = copy.height / ${WORLD_HEIGHT};
    const rectPoints = (rect) => {
      const points = [];
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) points.push({ x, y });
      }
      return points;
    };
    const inside = ({ x, y }, rect) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const cellAlpha = ({ x, y }) => {
      const left = Math.floor(x * scaleX);
      const top = Math.floor(y * scaleY);
      const right = Math.max(left + 1, Math.floor((x + 1) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((y + 1) * scaleY));
      let peak = 0;
      let sum = 0;
      const values = [];
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        const alpha = pixels[(py * copy.width + px) * 4 + 3];
        peak = Math.max(peak, alpha);
        sum += alpha;
        values.push(alpha);
      }
      return { peak, mean: sum / Math.max(1, values.length), values };
    };
    const regionAlpha = (points) => {
      let peak = 0;
      let sum = 0;
      let samples = 0;
      let supported = 0;
      for (const point of points) {
        const alpha = cellAlpha(point);
        peak = Math.max(peak, alpha.peak);
        sum += alpha.values.reduce((subtotal, value) => subtotal + value, 0);
        samples += alpha.values.length;
        supported += Number(alpha.peak > 0);
      }
      return { peak, mean: sum / Math.max(1, samples), supported, cells: points.length };
    };
    const sampleRect = (rect) => {
      const left = Math.floor(rect.x * scaleX);
      const top = Math.floor(rect.y * scaleY);
      const right = Math.max(left + 1, Math.floor((rect.x + rect.width) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((rect.y + rect.height) * scaleY));
      const rgb = [];
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        const offset = (py * copy.width + px) * 4;
        rgb.push(pixels[offset], pixels[offset + 1], pixels[offset + 2]);
      }
      return { width: right - left, height: bottom - top, rgb };
    };
    const samplePoints = (points) => {
      const rgb = [];
      for (const { x, y } of points) {
        const left = Math.floor(x * scaleX);
        const top = Math.floor(y * scaleY);
        const right = Math.max(left + 1, Math.floor((x + 1) * scaleX));
        const bottom = Math.max(top + 1, Math.floor((y + 1) * scaleY));
        for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
          const offset = (py * copy.width + px) * 4;
          rgb.push(pixels[offset], pixels[offset + 1], pixels[offset + 2]);
        }
      }
      return rgb;
    };
    const snapshot = window.__ANIFOR_INPUT_AUDIT__.gasIdentityGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    return {
      width: copy.width,
      height: copy.height,
      scaleX,
      scaleY,
      cards: cards.map((entry) => {
        const key = ({ x, y }) => x + ',' + y;
        const voidPoints = rectPoints(entry.authoredVoid);
        const centralVoid = rectPoints({
          x: entry.authoredVoid.x + 1,
          y: entry.authoredVoid.y + 1,
          width: entry.authoredVoid.width - 2,
          height: entry.authoredVoid.height - 2,
        });
        const channelPoints = rectPoints(entry.openChannel);
        const channelCentre = Array.from({ length: entry.openChannel.height }, (_, offset) => ({
          x: entry.openChannel.x + Math.floor(entry.openChannel.width / 2),
          y: entry.openChannel.y + offset,
        }));
        // Compare the open channel against gas at the same vertical positions;
        // a dense probe elsewhere in the cloud is confounded by the field's
        // intentional vertical density gradient.
        const channelShoulders = Array.from(
          { length: entry.openChannel.height }, (_, offset) => ([
            { x: entry.openChannel.x - 1, y: entry.openChannel.y + offset },
            {
              x: entry.openChannel.x + entry.openChannel.width,
              y: entry.openChannel.y + offset,
            },
          ]),
        ).flat();
        const emptyKeys = new Set([...voidPoints, ...channelPoints].map(key));
        const cloudPoints = rectPoints(entry.cloudSeed).filter((point) => !emptyKeys.has(key(point)));
        const haloOuter = {
          x: entry.cloudSeed.x - 2,
          y: entry.cloudSeed.y - 2,
          width: entry.cloudSeed.width + 4,
          height: entry.cloudSeed.height + 4,
        };
        const haloPoints = rectPoints(haloOuter).filter((point) => !inside(point, entry.cloudSeed));
        const gapPoints = rectPoints(entry.wispGap);
        const guardPoints = rectPoints(entry.guardedBlank);
        const liquidOwner = rectPoints(entry.liquidContact.owner);
        const liquidUnlike = rectPoints(entry.liquidContact.unlike);
        const solidOwner = rectPoints(entry.solidContact.owner);
        const solidUnlike = rectPoints(entry.solidContact.unlike);
        const signatureMap = new Map();
        for (const point of [
          ...rectPoints(haloOuter), ...entry.sparseWisps, ...gapPoints, entry.isolated,
          ...guardPoints, ...liquidOwner, ...liquidUnlike, ...solidOwner, ...solidUnlike,
        ]) signatureMap.set(key(point), point);
        let alphaSignature = 2166136261;
        let supportSignature = 2166136261;
        for (const point of signatureMap.values()) {
          const alpha = cellAlpha(point);
          for (const value of alpha.values) {
            alphaSignature = Math.imul(alphaSignature ^ value, 16777619) >>> 0;
          }
          supportSignature = Math.imul(
            supportSignature ^ Number(alpha.peak > 0), 16777619,
          ) >>> 0;
        }
        const cloudAlpha = regionAlpha(cloudPoints);
        const denseAlpha = regionAlpha(rectPoints(entry.denseProbe));
        const centralVoidAlpha = regionAlpha(centralVoid);
        const channelAlpha = regionAlpha(channelCentre);
        const channelShoulderAlpha = regionAlpha(channelShoulders);
        const wispAlpha = regionAlpha(entry.sparseWisps);
        const gapAlpha = regionAlpha(gapPoints);
        const haloAlpha = regionAlpha(haloPoints);
        const guardAlpha = regionAlpha(guardPoints);
        const liquidOwnerAlpha = regionAlpha(liquidOwner);
        const liquidUnlikeAlpha = regionAlpha(liquidUnlike);
        const solidOwnerAlpha = regionAlpha(solidOwner);
        const solidUnlikeAlpha = regionAlpha(solidUnlike);
        return {
          index: entry.index,
          material: entry.material,
          code: entry.code,
          cloudExpected: cloudAlpha.cells,
          cloudSupported: cloudAlpha.supported,
          denseAlphaMean: denseAlpha.mean,
          centralVoidAlphaMean: centralVoidAlpha.mean,
          channelAlphaMean: channelAlpha.mean,
          channelShoulderAlphaMean: channelShoulderAlpha.mean,
          wispExpected: wispAlpha.cells,
          wispSupported: wispAlpha.supported,
          wispAlphaMean: wispAlpha.mean,
          gapAlphaMean: gapAlpha.mean,
          isolatedAlphaPeak: cellAlpha(entry.isolated).peak,
          haloExpected: haloAlpha.cells,
          haloSupported: haloAlpha.supported,
          haloAlphaMean: haloAlpha.mean,
          guardedBlankExpected: guardAlpha.cells,
          guardedBlankTransparent: guardAlpha.cells - guardAlpha.supported,
          liquidOwnerExpected: liquidOwnerAlpha.cells,
          liquidOwnerSupported: liquidOwnerAlpha.supported,
          liquidUnlikeExpected: liquidUnlikeAlpha.cells,
          liquidUnlikeSupported: liquidUnlikeAlpha.supported,
          solidOwnerExpected: solidOwnerAlpha.cells,
          solidOwnerSupported: solidOwnerAlpha.supported,
          solidUnlikeExpected: solidUnlikeAlpha.cells,
          solidUnlikeSupported: solidUnlikeAlpha.supported,
          alphaSignature,
          supportSignature,
          ...sampleRect(haloOuter),
          haloRgb: samplePoints(haloPoints),
          voidRgb: samplePoints(centralVoid),
          channelRgb: samplePoints(channelCentre),
          gapRgb: samplePoints(gapPoints),
          liquidUnlikeRgb: sampleRect(entry.liquidContact.unlike).rgb,
          solidUnlikeRgb: sampleRect(entry.solidContact.unlike).rgb,
        };
      }),
    };
  })()`);
}

function assertGasIdentityBackingTopology(backing, label) {
  assert(Number.isInteger(backing.scaleX) && Number.isInteger(backing.scaleY)
      && backing.scaleX > 0 && backing.scaleY > 0,
  `${label}: backing does not preserve integral world scaling (${backing.scaleX}x${backing.scaleY})`);
  const valid = backing.cards.length === 17 && backing.cards.every((card) => (
    card.cloudSupported === card.cloudExpected
    && card.denseAlphaMean > 0
    && card.centralVoidAlphaMean < card.denseAlphaMean * 0.99
    // The sparse field is composited through a fractional CSS-to-backing
    // footprint. A channel may quantize a fraction of one alpha byte above
    // its shoulder even while the authored opening remains visibly softer;
    // retain the ordering contract at meaningful precision rather than
    // treating that sub-byte capture phase as topology.
    && card.channelAlphaMean <= card.channelShoulderAlphaMean + 0.25
    && card.wispSupported === card.wispExpected
    && card.wispAlphaMean > 0
    && card.gapAlphaMean < card.wispAlphaMean * 0.99
    && card.isolatedAlphaPeak > 0
    && card.haloSupported >= card.haloExpected * 0.35
    && card.haloAlphaMean > 0
    && card.guardedBlankTransparent === card.guardedBlankExpected
    && card.liquidOwnerSupported === card.liquidOwnerExpected
    && card.liquidUnlikeSupported === card.liquidUnlikeExpected
    && card.solidOwnerSupported === card.solidOwnerExpected
    && card.solidUnlikeSupported === card.solidUnlikeExpected
  ));
  assert(valid,
    `${label}: backing changed gas topology or lost soft authored openings (${JSON.stringify(compactGasIdentityTopology(backing))})`);
}

function compactGasIdentityTopology(backing) {
  return {
    scale: `${backing.scaleX}x${backing.scaleY}`,
    cards: backing.cards.map(({
      rgb: _rgb, haloRgb: _haloRgb, voidRgb: _voidRgb, channelRgb: _channelRgb,
      gapRgb: _gapRgb, liquidUnlikeRgb: _liquidUnlikeRgb, solidUnlikeRgb: _solidUnlikeRgb,
      width: _width, height: _height, ...card
    }) => card),
  };
}

function summarizeGasIdentityBackingResponses(flat, styled, repeated) {
  assert(flat.cards.length === 17 && styled.cards.length === 17 && repeated.cards.length === 17,
    'Gas identity backing response atlas is incomplete');
  return flat.cards.map((base, cardIndex) => {
    const changed = styled.cards[cardIndex];
    const returned = repeated.cards[cardIndex];
    assert(changed.material === base.material && returned.material === base.material
        && changed.width === base.width && returned.width === base.width
        && changed.height === base.height && returned.height === base.height
        && changed.rgb.length === base.rgb.length && returned.rgb.length === base.rgb.length,
    `Gas identity backing response geometry changed for ${base.code}`);
    const summarize = (before, after, again) => {
      let squared = 0;
      let peak = 0;
      let repeatPeak = 0;
      let changedSamples = 0;
      for (let offset = 0; offset < before.length; offset += 3) {
        let sampleChanged = false;
        for (let channel = 0; channel < 3; channel++) {
          const delta = after[offset + channel] - before[offset + channel];
          const repeat = again[offset + channel] - before[offset + channel];
          squared += delta * delta;
          peak = Math.max(peak, Math.abs(delta));
          repeatPeak = Math.max(repeatPeak, Math.abs(repeat));
          sampleChanged ||= delta !== 0;
        }
        changedSamples += Number(sampleChanged);
      }
      return {
        rms: round(Math.sqrt(squared / Math.max(1, before.length)), 4),
        peak,
        repeatPeak,
        changedSampleRatio: round(changedSamples / Math.max(1, before.length / 3), 5),
      };
    };
    let squared = 0;
    let rgbPeak = 0;
    let repeatRgbPeak = 0;
    let changedSamples = 0;
    let responseSignature = 2166136261;
    const buckets = new Float64Array(16);
    for (let offset = 0; offset < base.rgb.length; offset += 3) {
      const sample = offset / 3;
      const x = sample % base.width;
      const y = Math.floor(sample / base.width);
      const bucket = Math.min(3, Math.floor(y * 4 / base.height)) * 4
        + Math.min(3, Math.floor(x * 4 / base.width));
      let sampleChanged = false;
      for (let channel = 0; channel < 3; channel++) {
        const delta = changed.rgb[offset + channel] - base.rgb[offset + channel];
        const repeat = returned.rgb[offset + channel] - base.rgb[offset + channel];
        squared += delta * delta;
        rgbPeak = Math.max(rgbPeak, Math.abs(delta));
        repeatRgbPeak = Math.max(repeatRgbPeak, Math.abs(repeat));
        buckets[bucket] += Math.abs(delta);
        sampleChanged ||= delta !== 0;
        responseSignature = Math.imul(responseSignature ^ (delta + 255), 16777619) >>> 0;
      }
      changedSamples += Number(sampleChanged);
    }
    const total = Math.max(1, buckets.reduce((sum, value) => sum + value, 0));
    const halo = summarize(base.haloRgb, changed.haloRgb, returned.haloRgb);
    return {
      material: base.material,
      code: base.code,
      rgbRms: round(Math.sqrt(squared / Math.max(1, base.rgb.length)), 4),
      rgbPeak,
      changedSampleRatio: round(changedSamples / Math.max(1, base.width * base.height), 5),
      repeatRgbPeak,
      responseSignature,
      responseProfile: Array.from(buckets, (value) => round(value / total, 5)),
      haloRgbRms: halo.rms,
      haloRgbPeak: halo.peak,
      haloRepeatRgbPeak: halo.repeatPeak,
      haloChangedSampleRatio: halo.changedSampleRatio,
    };
  });
}

async function sampleCellularBackingTopology(cdp) {
  return evaluate(cdp, `(() => {
    const world = document.querySelector('.world-canvas');
    if (!(world instanceof HTMLCanvasElement)) throw new Error('World canvas unavailable');
    const copy = document.createElement('canvas');
    copy.width = world.width;
    copy.height = world.height;
    const context = copy.getContext('2d', { willReadFrequently: true });
    if (!context) throw new Error('Cellular backing sampler unavailable');
    context.drawImage(world, 0, 0);
    const pixels = context.getImageData(0, 0, copy.width, copy.height).data;
    const scaleX = copy.width / ${WORLD_WIDTH};
    const scaleY = copy.height / ${WORLD_HEIGHT};
    const sampleCell = ({ x, y }) => {
      const left = Math.floor(x * scaleX);
      const top = Math.floor(y * scaleY);
      const right = Math.max(left + 1, Math.floor((x + 1) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((y + 1) * scaleY));
      let alphaPeak = 0;
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        alphaPeak = Math.max(alphaPeak, pixels[(py * copy.width + px) * 4 + 3]);
      }
      return { alphaPeak };
    };
    const sampleBody = (body) => {
      const rgb = [];
      for (let y = body.y; y < body.y + body.height; y++) {
        for (let x = body.x; x < body.x + body.width; x++) {
          const px = Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX));
          const py = Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY));
          const offset = (py * copy.width + px) * 4;
          rgb.push(pixels[offset], pixels[offset + 1], pixels[offset + 2]);
        }
      }
      return { width: body.width, height: body.height, rgb };
    };
    const snapshot = window.__ANIFOR_INPUT_AUDIT__.cellularGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const holes = cards.flatMap(({ hole }) => {
      const points = [];
      for (let y = hole.y; y < hole.y + hole.height; y++) {
        for (let x = hole.x; x < hole.x + hole.width; x++) points.push(sampleCell({ x, y }));
      }
      return points;
    });
    return {
      width: copy.width,
      height: copy.height,
      holes,
      isolated: cards.map(({ isolated }) => sampleCell(isolated)),
      cards: cards.map(({ preset, material, body }) => ({
        preset, material, ...sampleBody(body),
      })),
    };
  })()`);
}

function summarizeCellularBackingResponses(flat, styled, repeated) {
  assert(flat.cards.length === 24 && styled.cards.length === 24 && repeated.cards.length === 24,
    'Cellular backing response atlas is incomplete');
  return flat.cards.map((base, cardIndex) => {
    const changed = styled.cards[cardIndex];
    const returned = repeated.cards[cardIndex];
    assert(changed.preset === base.preset && returned.preset === base.preset
        && changed.material === base.material && returned.material === base.material
        && changed.width === base.width && returned.width === base.width
        && changed.height === base.height && returned.height === base.height
        && changed.rgb.length === base.rgb.length && returned.rgb.length === base.rgb.length,
    `Cellular backing response geometry changed for preset ${base.preset}`);
    let squared = 0;
    let rgbPeak = 0;
    let repeatRgbPeak = 0;
    let responseSignature = 2166136261;
    const buckets = new Float64Array(16);
    for (let offset = 0; offset < base.rgb.length; offset += 3) {
      const cell = offset / 3;
      const x = cell % base.width;
      const y = Math.floor(cell / base.width);
      const bucket = Math.min(3, Math.floor(y * 4 / base.height)) * 4
        + Math.min(3, Math.floor(x * 4 / base.width));
      for (let channel = 0; channel < 3; channel++) {
        const delta = changed.rgb[offset + channel] - base.rgb[offset + channel];
        const repeat = returned.rgb[offset + channel] - base.rgb[offset + channel];
        squared += delta * delta;
        rgbPeak = Math.max(rgbPeak, Math.abs(delta));
        repeatRgbPeak = Math.max(repeatRgbPeak, Math.abs(repeat));
        buckets[bucket] += Math.abs(delta);
        responseSignature = Math.imul(responseSignature ^ (delta + 255), 16777619) >>> 0;
      }
    }
    const total = Math.max(1, buckets.reduce((sum, value) => sum + value, 0));
    return {
      preset: base.preset,
      rgbRms: round(Math.sqrt(squared / Math.max(1, base.rgb.length)), 4),
      rgbPeak,
      repeatRgbPeak,
      responseSignature,
      responseProfile: Array.from(buckets, (value) => round(value / total, 5)),
    };
  });
}

function normalizeCellularGraphicsAtlas(snapshot) {
  const cards = (Array.isArray(snapshot) ? snapshot : snapshot?.cards ?? []).map((entry) => {
    const card = cellularRect(entry.card ?? entry);
    return {
      ...entry,
      card,
      body: cellularRect(entry.body),
      hole: cellularRect(entry.hole),
      guardedBlank: cellularRect(entry.guardedBlank),
      isolated: cellularPoint(entry.isolated),
      tendril: cellularPoints(entry.tendril),
    };
  });
  const holes = Array.isArray(snapshot)
    ? cards.flatMap(({ hole }) => cellularRectPoints(hole))
    : cellularPoints(snapshot?.holes);
  const isolated = cellularPoints(
    Array.isArray(snapshot) ? cards.map((entry) => entry.isolated) : snapshot?.isolated,
  );
  return { cards, holes, isolated };
}

function cellularRect(value) {
  assert(value && typeof value === 'object', `Invalid cellular graphics rectangle ${JSON.stringify(value)}`);
  const x = value.x ?? value.left;
  const y = value.y ?? value.top;
  const width = value.width ?? (value.right !== undefined ? value.right - x : undefined);
  const height = value.height ?? (value.bottom !== undefined ? value.bottom - y : undefined);
  assert([x, y, width, height].every(Number.isFinite)
      && width > 0 && height > 0,
  `Invalid cellular graphics rectangle ${JSON.stringify(value)}`);
  return { x, y, width, height };
}

function cellularPoint(value) {
  const x = Array.isArray(value) ? value[0] : value?.x;
  const y = Array.isArray(value) ? value[1] : value?.y;
  assert(Number.isFinite(x) && Number.isFinite(y),
    `Invalid cellular graphics point ${JSON.stringify(value)}`);
  return { x, y };
}

function cellularPoints(value) {
  if (!value) return [];
  if (Array.isArray(value) && value.length >= 2 && value.slice(0, 2).every(Number.isFinite)) {
    return [cellularPoint(value)];
  }
  return (Array.isArray(value) ? value : [value]).map(cellularPoint);
}

function cellularRectPoints(rect) {
  const points = [];
  for (let y = rect.y; y < rect.y + rect.height; y++) {
    for (let x = rect.x; x < rect.x + rect.width; x++) points.push({ x, y });
  }
  return points;
}

function containingCellularRegion(rectangles) {
  const left = Math.min(...rectangles.map(({ x }) => x));
  const top = Math.min(...rectangles.map(({ y }) => y));
  const right = Math.max(...rectangles.map(({ x, width }) => x + width));
  const bottom = Math.max(...rectangles.map(({ y, height }) => y + height));
  return {
    x: (left + right) / 2,
    y: (top + bottom) / 2,
    radiusX: (right - left) / 2,
    radiusY: (bottom - top) / 2,
  };
}

/** Focused release proof for the CSS-pixel camera/input contract. */
async function auditDesktopInput(cdp, mode, dpr) {
  const started = performance.now();
  const stage = (name) => console.error(
    `[desktop-input:${mode}] ${name} ${Math.round(performance.now() - started)}ms`,
  );
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  await waitForStableCanvas(cdp, 1280, 720, undefined, 6_000, `${mode} desktop-input geometry`);
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.clear();
    audit.resetView();
    audit.setRadius(0);
    audit.setMaterial(164);
    return true;
  })()`);
  await sleep(100);
  const initial = await metrics(cdp);
  assertGeometry(initial, `${mode} desktop-input initial`);
  assertContained(initial, `${mode} desktop-input initial`);
  stage('geometry-ready');

  const landmarks = [{ x: 17, y: 21 }, { x: 306, y: 192 }, { x: 594, y: 361 }];
  for (const landmark of landmarks) {
    const point = worldClient(initial.canvas, { x: landmark.x + 0.5, y: landmark.y + 0.5 });
    await mouseClick(cdp, point.x, point.y, 'left');
  }
  await sleep(100);
  const landmarkResult = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    return {
      cells: ${JSON.stringify(landmarks)}.map(({ x, y }) => audit.cell(x, y)),
      occupied: audit.occupiedCells(),
    };
  })()`);
  assert(landmarkResult.cells.every((cell) => cell === 164)
    && landmarkResult.occupied === landmarks.length,
  `${mode}: desktop radius-zero landmarks missed (${JSON.stringify(landmarkResult)})`);
  const landmarkFootprints = await capturePaintedFootprints(
    cdp, landmarks, `${mode} focused desktop landmarks`, 1.5, 1.2,
  );
  stage('landmarks-ready');

  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.clear(); true');
  const drag = { y: 88, start: 96, end: 120 };
  const dragStart = worldClient(initial.canvas, { x: drag.start + 0.5, y: drag.y + 0.5 });
  const dragEnd = worldClient(initial.canvas, { x: drag.end + 0.5, y: drag.y + 0.5 });
  await cdp.send('Input.dispatchMouseEvent', {
    type: 'mousePressed', x: dragStart.x, y: dragStart.y,
    button: 'left', buttons: 1, clickCount: 1,
  });
  await cdp.send('Input.dispatchMouseEvent', {
    type: 'mouseMoved', x: dragEnd.x, y: dragEnd.y, button: 'left', buttons: 1,
  });
  await cdp.send('Input.dispatchMouseEvent', {
    type: 'mouseReleased', x: dragEnd.x, y: dragEnd.y,
    button: 'left', buttons: 0, clickCount: 1,
  });
  await sleep(100);
  const dragResult = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const cells = [];
    for (let x = ${drag.start}; x <= ${drag.end}; x++) cells.push(audit.cell(x, ${drag.y}));
    return { cells, occupied: audit.occupiedCells() };
  })()`);
  const dragCells = drag.end - drag.start + 1;
  assert(dragResult.cells.every((cell) => cell === 164) && dragResult.occupied === dragCells,
    `${mode}: focused desktop left drag was discontinuous (${JSON.stringify(dragResult)})`);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.clear(); true');
  stage('drag-ready');

  const wheelGeometry = await metrics(cdp);
  const rawWheelAnchor = worldClient(wheelGeometry.canvas, { x: 431.25, y: 117.75 });
  const wheelAnchor = { x: Math.round(rawWheelAnchor.x), y: Math.round(rawWheelAnchor.y) };
  const wheelBefore = await screenWorld(cdp, wheelAnchor);
  await cdp.send('Input.dispatchMouseEvent', {
    type: 'mouseWheel', x: wheelAnchor.x, y: wheelAnchor.y,
    deltaX: 0, deltaY: -120, modifiers: 0,
  });
  await sleep(100);
  const wheelAfter = await screenWorld(cdp, wheelAnchor);
  const beforePan = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.viewState()');
  const wheelAnchorError = Math.hypot(
    wheelAfter.x - wheelBefore.x, wheelAfter.y - wheelBefore.y,
  );
  assert(beforePan.zoom > 1.2 && wheelAnchorError < 0.2,
    `${mode}: focused desktop wheel anchor failed (${wheelAnchorError.toFixed(4)} cells)`);
  stage('wheel-ready');

  await cdp.send('Input.dispatchMouseEvent', {
    type: 'mousePressed', x: wheelAnchor.x, y: wheelAnchor.y,
    button: 'middle', buttons: 4, clickCount: 1,
  });
  await cdp.send('Input.dispatchMouseEvent', {
    type: 'mouseMoved', x: wheelAnchor.x + 42, y: wheelAnchor.y + 27,
    button: 'middle', buttons: 4,
  });
  await cdp.send('Input.dispatchMouseEvent', {
    type: 'mouseReleased', x: wheelAnchor.x + 42, y: wheelAnchor.y + 27,
    button: 'middle', buttons: 0, clickCount: 1,
  });
  await sleep(100);
  const afterPan = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.viewState()');
  assert(Math.abs(afterPan.panX - beforePan.panX - 42) < 0.12
    && Math.abs(afterPan.panY - beforePan.panY - 27) < 0.12,
  `${mode}: focused desktop middle pan mismatch (${JSON.stringify({ beforePan, afterPan })})`);
  stage('pan-ready');

  const transformedGeometry = await metrics(cdp);
  const transformedCell = { x: 431, y: 118 };
  const transformedClient = worldClient(
    transformedGeometry.canvas,
    { x: transformedCell.x + 0.5, y: transformedCell.y + 0.5 },
  );
  const transformedBlank = await cdp.send('Page.captureScreenshot', {
    format: 'png', fromSurface: true,
  });
  await sleep(80);
  const transformedBlankReference = await cdp.send('Page.captureScreenshot', {
    format: 'png', fromSurface: true,
  });
  await mouseClick(cdp, transformedClient.x, transformedClient.y, 'left');
  await sleep(100);
  const transformedResult = await evaluate(cdp, `({
    cell: window.__ANIFOR_INPUT_AUDIT__.cell(${transformedCell.x}, ${transformedCell.y}),
    occupied: window.__ANIFOR_INPUT_AUDIT__.occupiedCells(),
  })`);
  assert(transformedResult.cell === 164 && transformedResult.occupied === 1,
    `${mode}: focused transformed paint missed (${JSON.stringify(transformedResult)})`);
  const transformedFootprint = (await capturePaintedFootprints(
    cdp, [transformedCell], `${mode} focused post-wheel/post-pan`, 1.5, 0.8, {
      baselineBase64: transformedBlank.data,
      baselineReferenceBase64: transformedBlankReference.data,
      captureCanvasRect: transformedGeometry.canvas,
    },
  ))[0];
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.clear(); true');
  stage('transformed-paint-ready');

  const transformedStrokeStart = { x: 412, y: 108 };
  const transformedStrokeEnd = { x: 436, y: 126 };
  const transformedStrokeGeometry = await metrics(cdp);
  const transformedStrokeStartClient = worldClient(
    transformedStrokeGeometry.canvas,
    { x: transformedStrokeStart.x + 0.5, y: transformedStrokeStart.y + 0.5 },
  );
  const transformedStrokeEndClient = worldClient(
    transformedStrokeGeometry.canvas,
    { x: transformedStrokeEnd.x + 0.5, y: transformedStrokeEnd.y + 0.5 },
  );
  const transformedStrokeBlank = await cdp.send('Page.captureScreenshot', { format: 'png', fromSurface: true });
  await sleep(80);
  const transformedStrokeBlankReference = await cdp.send('Page.captureScreenshot', {
    format: 'png', fromSurface: true,
  });
  await cdp.send('Input.dispatchMouseEvent', {
    type: 'mousePressed', x: transformedStrokeStartClient.x, y: transformedStrokeStartClient.y,
    button: 'left', buttons: 1, clickCount: 1,
  });
  await cdp.send('Input.dispatchMouseEvent', {
    type: 'mouseMoved', x: transformedStrokeEndClient.x, y: transformedStrokeEndClient.y,
    button: 'left', buttons: 1,
  });
  await cdp.send('Input.dispatchMouseEvent', {
    type: 'mouseReleased', x: transformedStrokeEndClient.x, y: transformedStrokeEndClient.y,
    button: 'left', buttons: 0, clickCount: 1,
  });
  await sleep(100);
  const transformedDiagonal = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const start = ${JSON.stringify(transformedStrokeStart)};
    const end = ${JSON.stringify(transformedStrokeEnd)};
    const steps = Math.max(Math.abs(end.x - start.x), Math.abs(end.y - start.y));
    const cells = Array.from({ length: steps + 1 }, (_, step) => ({
      x: Math.round(start.x + (end.x - start.x) * step / steps),
      y: Math.round(start.y + (end.y - start.y) * step / steps),
    }));
    return { cells, values: cells.map(({ x, y }) => audit.cell(x, y)), occupied: audit.occupiedCells() };
  })()`);
  assert(transformedDiagonal.values.every((cell) => cell === 164)
    && transformedDiagonal.occupied === transformedDiagonal.cells.length,
  `${mode}: focused transformed diagonal stroke missed exact cells (${JSON.stringify(transformedDiagonal)})`);
  const transformedDiagonalFootprints = await capturePaintedFootprints(cdp, [
    transformedStrokeStart,
    { x: 424, y: 117 },
    transformedStrokeEnd,
  ], `${mode} focused transformed diagonal stroke`, 1.5, 2.2, {
    baselineBase64: transformedStrokeBlank.data,
    baselineReferenceBase64: transformedStrokeBlankReference.data,
    captureCanvasRect: transformedStrokeGeometry.canvas,
  });
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.clear(); true');
  stage('transformed-stroke-ready');

  const resizeAnchor = { x: wheelAnchor.x + 42, y: wheelAnchor.y + 27 };
  const resizeAnchorBefore = await screenWorld(cdp, resizeAnchor);
  const resizeStartView = afterPan;
  await setDesktopMetrics(cdp, 880, 600, dpr);
  const compactGeometry = await waitForStableZoomedCamera(
    cdp, 880, 600, transformedGeometry, resizeStartView.zoom,
    6_000, `${mode} focused zoomed compact`,
  );
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const returnedGeometry = await waitForStableZoomedCamera(
    cdp, 1280, 720, compactGeometry, resizeStartView.zoom,
    6_000, `${mode} focused zoomed return`,
  );
  const returnedView = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.viewState()');
  const relativeAnchor = {
    x: (resizeAnchor.x - transformedGeometry.viewport.left) / transformedGeometry.viewport.width,
    y: (resizeAnchor.y - transformedGeometry.viewport.top) / transformedGeometry.viewport.height,
  };
  const returnedAnchor = {
    x: returnedGeometry.viewport.left + relativeAnchor.x * returnedGeometry.viewport.width,
    y: returnedGeometry.viewport.top + relativeAnchor.y * returnedGeometry.viewport.height,
  };
  const resizeAnchorAfter = await screenWorld(cdp, returnedAnchor);
  const resizeAnchorError = Math.hypot(
    resizeAnchorAfter.x - resizeAnchorBefore.x,
    resizeAnchorAfter.y - resizeAnchorBefore.y,
  );
  assertResizeAdjustedViewState(
    resizeStartView, transformedGeometry.canvas,
    returnedView, returnedGeometry.canvas,
    `${mode} focused breakpoint camera preservation`,
  );
  assert(resizeAnchorError < 0.2,
    `${mode}: focused breakpoint anchor drifted ${resizeAnchorError.toFixed(4)} cells (${JSON.stringify({
      resizeAnchor, returnedAnchor, resizeAnchorBefore, resizeAnchorAfter,
      beforeCanvas: transformedGeometry.canvas, compactCanvas: compactGeometry.canvas,
      returnedCanvas: returnedGeometry.canvas, resizeStartView, returnedView,
    })})`);
  stage('resize-ready');

  const liveScaleTransition = await auditLiveScaleTransition(
    cdp, mode, dpr, returnedGeometry, returnedView,
  );
  stage('live-scale-ready');
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.resetView(); true');
  const resetGeometry = await waitForStableCanvas(
    cdp, 1280, 720, undefined, 6_000, `${mode} focused reset geometry`,
  );
  const shortDesktop = await auditShortDesktop(cdp, mode, dpr, resetGeometry);
  stage('complete');

  return {
    backing: `${initial.backing.width}x${initial.backing.height}`,
    landmarkCells: landmarks.length,
    landmarkFootprints,
    continuousDragCells: dragCells,
    wheelAnchorErrorCells: round(wheelAnchorError, 5),
    middlePanDelta: {
      x: round(afterPan.panX - beforePan.panX, 3),
      y: round(afterPan.panY - beforePan.panY, 3),
    },
    transformedCell: `${transformedCell.x},${transformedCell.y}`,
    transformedFootprint,
    transformedDiagonalCells: transformedDiagonal.cells.length,
    transformedDiagonalFootprints,
    breakpointResizeAnchorErrorCells: round(resizeAnchorError, 5),
    liveScaleTransition,
    shortDesktop,
  };
}

async function auditMaterialAtlas(cdp, mode, dpr, screenshot, options = {}) {
  const outputScale = options.outputScale ?? 2;
  const reuseBlankDocument = options.reuseBlankDocument === true;
  const backendTimeout = outputScale === 8 ? 45_000 : 15_000;
  const captureTimeout = outputScale === 8 ? 45_000 : 12_000;
  await cdp.send('Emulation.setTouchEmulationEnabled', { enabled: false });
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const blankQuery = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: String(outputScale),
    auditStage: 'material-atlas-blank',
    ...(mode === 'canvas2d' ? { renderer: 'canvas2d' } : {}),
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${blankQuery}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const parameters = new URLSearchParams(location.search);
    return parameters.get('auditStage') === 'material-atlas-blank'
      && Boolean(window.__ANIFOR_INPUT_AUDIT__?.prepareMaterialAtlas);
  })()`), 15_000, `${mode} material-atlas blank audit API`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  backendTimeout, `${mode} material-atlas blank backend`);
  const blankGeometry = await metrics(cdp);
  assertGeometry(blankGeometry, `${mode} material-atlas blank`, outputScale);
  if (outputScale === 8) {
    const backend = await evaluate(cdp, `window.__ANIFOR_INPUT_AUDIT__.backend()`);
    assert(backend.requestedOutputScale === 8 && backend.outputScale === 8,
      `${mode}: material atlas did not retain true 8x WebGL (${JSON.stringify(backend)})`);
  }

  const baseline = await waitForStablePageCapture(
    cdp, `${mode} material-atlas blank framebuffer`, captureTimeout,
  );
  let manifest;
  if (reuseBlankDocument) {
    manifest = await evaluate(cdp, `(() => {
      const audit = window.__ANIFOR_INPUT_AUDIT__;
      audit.prepareMaterialAtlas();
      return audit.materialAtlas();
    })()`);
  } else {
    const query = new URLSearchParams({
      scene: 'render-lab', inputAudit: '1', renderScale: String(outputScale), auditStage: 'material-atlas',
      ...(mode === 'canvas2d' ? { renderer: 'canvas2d' } : {}),
    });
    await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
    await waitFor(() => evaluate(cdp, `(() => {
      const parameters = new URLSearchParams(location.search);
      return parameters.get('auditStage') === 'material-atlas'
        && Boolean(window.__ANIFOR_INPUT_AUDIT__?.prepareMaterialAtlas);
    })()`), 15_000, `${mode} material-atlas audit API`);
    await waitFor(() => evaluate(cdp,
      `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
    backendTimeout, `${mode} material-atlas backend`);
    manifest = await evaluate(cdp, `window.__ANIFOR_INPUT_AUDIT__.materialAtlas()`);
  }
  assert(manifest.length > 0, `${mode}: material atlas is empty`);
  assert(new Set(manifest.map(({ id }) => id)).size === manifest.length,
    `${mode}: material atlas contains duplicate IDs`);
  const ownership = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    return audit.materialAtlas().map((entry) => {
      let owned = 0;
      let foreign = 0;
      let guardOccupied = 0;
      for (let y = entry.y - entry.radius; y <= entry.y + entry.radius; y++) {
        for (let x = entry.x - entry.radius; x <= entry.x + entry.radius; x++) {
          const material = audit.cell(x, y);
          if (material === entry.id) owned++;
          else foreign++;
        }
      }
      const guard = entry.radius + 2;
      for (let offset = -guard; offset <= guard; offset++) {
        guardOccupied += Number(audit.cell(entry.x + offset, entry.y - guard) !== 0);
        guardOccupied += Number(audit.cell(entry.x + offset, entry.y + guard) !== 0);
        guardOccupied += Number(audit.cell(entry.x - guard, entry.y + offset) !== 0);
        guardOccupied += Number(audit.cell(entry.x + guard, entry.y + offset) !== 0);
      }
      return { id: entry.id, owned, foreign, guardOccupied };
    });
  })()`);
  const expectedOwned = (manifest[0].radius * 2 + 1) ** 2;
  const invalidOwners = ownership.filter((entry) => (
    entry.owned !== expectedOwned || entry.foreign !== 0 || entry.guardOccupied !== 0
  ));
  assert(invalidOwners.length === 0,
    `${mode}: material-atlas semantic ownership failed (${JSON.stringify(invalidOwners.slice(0, 8))})`);

  const rendered = await waitForStablePageCapture(
    cdp, `${mode} material-atlas framebuffer`, captureTimeout,
  );
  assertCanvasRectsEqual(baseline.canvasRect, rendered.canvasRect, `${mode} material-atlas blank/rendered`);
  const samples = await sampleMaterialAtlas(
    cdp, rendered.capture.data, baseline.capture.data, rendered.canvasRect, manifest,
  );
  const invisible = samples.filter((sample) => {
    const canonical = Number.parseInt(sample.expectedColor.slice(1), 16);
    const darkestCanonical = Math.max(canonical >> 16, canonical >> 8 & 0xff, canonical & 0xff) <= 36;
    return darkestCanonical
      ? sample.changedFraction < 0.45 || sample.meanDifference < 2 || sample.peakDifference < 3
      : sample.changedFraction < 0.70 || sample.meanDifference < 4 || sample.peakDifference < 5;
  });
  assert(invisible.length === 0,
    `${mode}: projected materials disappeared from composed output (${JSON.stringify(invisible)})`);
  if (screenshot) await writeFile(screenshot, Buffer.from(rendered.capture.data, 'base64'));
  return {
    outputScale,
    backing: `${blankGeometry.backing.width}x${blankGeometry.backing.height}`,
    projections: manifest.length,
    semanticCellsPerProjection: expectedOwned,
    visible: samples.length - invisible.length,
    minimumChangedFraction: round(Math.min(...samples.map(({ changedFraction }) => changedFraction)), 3),
    minimumMeanDifference: round(Math.min(...samples.map(({ meanDifference }) => meanDifference)), 3),
    minimumPeakDifference: Math.min(...samples.map(({ peakDifference }) => peakDifference)),
    samples,
    ...(screenshot ? { screenshot } : {}),
  };
}

async function sampleMaterialAtlas(cdp, renderedBase64, baselineBase64, canvasRect, manifest) {
  return evaluate(cdp, `(async () => {
    const load = async (data) => {
      const image = new Image();
      image.src = 'data:image/png;base64,' + data;
      await image.decode();
      const canvas = document.createElement('canvas');
      canvas.width = image.naturalWidth;
      canvas.height = image.naturalHeight;
      const context = canvas.getContext('2d', { willReadFrequently: true });
      if (!context) throw new Error('Material-atlas screenshot sampler unavailable');
      context.drawImage(image, 0, 0);
      return { image, context };
    };
    const rendered = await load(${JSON.stringify(renderedBase64)});
    const baseline = await load(${JSON.stringify(baselineBase64)});
    if (rendered.image.naturalWidth !== baseline.image.naturalWidth
      || rendered.image.naturalHeight !== baseline.image.naturalHeight) {
      throw new Error('Material-atlas screenshot geometry mismatch');
    }
    const bounds = ${JSON.stringify(canvasRect)};
    const scaleX = rendered.image.naturalWidth / innerWidth;
    const scaleY = rendered.image.naturalHeight / innerHeight;
    const worldScaleX = bounds.width / ${WORLD_WIDTH};
    const worldScaleY = bounds.height / ${WORLD_HEIGHT};
    return ${JSON.stringify(manifest)}.map((entry) => {
      const worldLeft = entry.x - entry.radius;
      const worldTop = entry.y - entry.radius;
      const worldSize = entry.radius * 2 + 1;
      const x = Math.max(0, Math.floor((bounds.left + worldLeft * worldScaleX) * scaleX));
      const y = Math.max(0, Math.floor((bounds.top + worldTop * worldScaleY) * scaleY));
      const width = Math.max(1, Math.ceil(worldSize * worldScaleX * scaleX));
      const height = Math.max(1, Math.ceil(worldSize * worldScaleY * scaleY));
      const foreground = rendered.context.getImageData(x, y, width, height).data;
      const empty = baseline.context.getImageData(x, y, width, height).data;
      let changed = 0;
      let difference = 0;
      let peakDifference = 0;
      const rgb = [0, 0, 0];
      let rgbCount = 0;
      for (let offset = 0; offset < foreground.length; offset += 4) {
        const delta = Math.max(
          Math.abs(foreground[offset] - empty[offset]),
          Math.abs(foreground[offset + 1] - empty[offset + 1]),
          Math.abs(foreground[offset + 2] - empty[offset + 2]),
        );
        difference += delta;
        peakDifference = Math.max(peakDifference, delta);
        if (delta < 3) continue;
        changed++;
        rgb[0] += foreground[offset];
        rgb[1] += foreground[offset + 1];
        rgb[2] += foreground[offset + 2];
        rgbCount++;
      }
      const pixels = Math.max(1, width * height);
      return {
        id: entry.id,
        name: entry.name,
        expectedColor: entry.color,
        changedFraction: Math.round(changed / pixels * 1000) / 1000,
        meanDifference: Math.round(difference / pixels * 1000) / 1000,
        peakDifference,
        composedRgb: rgb.map((value) => Math.round(value / Math.max(1, rgbCount))),
      };
    });
  })()`);
}

async function auditWebGLPresentationTiming(
  cdp, targetSamples = 30, sampleTimeout = 5_000, acceptanceTimeout = sampleTimeout,
  maximumAttempts = targetSamples + 45,
) {
  let timing = await evaluate(cdp,
    'window.__ANIFOR_INPUT_AUDIT__.webGLPresentationTiming()');
  assert(timing, 'WebGL presentation timing is unavailable');
  assert(timing.source === 'gpu-query' || timing.source === 'gpu-fence' || timing.source === 'gpu-finish'
    || timing.source === 'cpu-submission',
    `Unknown WebGL timing source ${timing.source}`);

  for (let attempt = 0; timing.usableSamples < targetSamples && attempt < maximumAttempts; attempt++) {
    const before = timing;
    // A 15M-fragment 8x request may wait for the previous presentation fence,
    // but acceptance and completion own one bounded attempt window. Passing a
    // short CDP timeout into each poll prevents Runtime.evaluate's global
    // fallback from escaping that renderer/audit deadline.
    const attemptDeadline = Date.now() + Math.max(sampleTimeout, acceptanceTimeout);
    const remainingAttemptMs = (label) => remainingDeadlineMs(attemptDeadline, label);
    await waitFor(() => evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.requestWebGLPresentationTimingSample()',
      Math.min(1_000, remainingAttemptMs(`WebGL timing sample ${attempt + 1} acceptance poll`))),
    remainingAttemptMs(`WebGL timing sample ${attempt + 1} acceptance`),
    `WebGL timing sample ${attempt + 1} accepted completed-frame request`);
    timing = await waitFor(() => evaluate(cdp, `(() => {
      const next = window.__ANIFOR_INPUT_AUDIT__.webGLPresentationTiming();
      return next && (next.source !== ${JSON.stringify(before.source)}
        || next.sequence > ${before.sequence}) ? next : null;
    })()`, Math.min(1_000, remainingAttemptMs(`WebGL presentation sample ${attempt + 1} poll`))),
    remainingAttemptMs(`WebGL presentation sample ${attempt + 1}`),
    `WebGL presentation sample ${attempt + 1}`);
  }

  assert(timing.usableSamples >= targetSamples,
    `WebGL presentation produced only ${timing.usableSamples}/${targetSamples} usable samples`
      + ` (${timing.discardedSamples} discarded, ${timing.source})`);
  for (const [label, value] of [
    ['median', timing.medianMs], ['p90', timing.p90Ms], ['maximum', timing.maximumMs],
  ]) assert(Number.isFinite(value) && value >= 0,
    `WebGL ${label} timing is invalid (${value}, ${timing.source})`);

  return {
    fixture: 'canonical render lab',
    source: timing.source,
    samples: timing.usableSamples,
    discardedSamples: timing.discardedSamples,
    medianMs: round(timing.medianMs),
    p90Ms: round(timing.p90Ms),
    maximumMs: round(timing.maximumMs),
  };
}

async function waitForNextWebGLPresentation(
  cdp, label, timeoutMs = 12_000, acceptanceTimeout = 30_000,
) {
  // `requestWebGLPresentationTimingSample` may only accept after an older
  // 15M-fragment frame retires. Give acceptance and the requested frame one
  // deadline, rather than allowing their individual budgets to add together.
  const deadline = Date.now() + Math.max(timeoutMs, acceptanceTimeout);
  const before = await evaluate(cdp,
    'window.__ANIFOR_INPUT_AUDIT__.webGLPresentationTiming()',
    Math.min(1_000, remainingDeadlineMs(deadline, `${label} initial timing read`)));
  assert(before, `${label}: WebGL presentation timing is unavailable`);
  await waitFor(() => evaluate(cdp,
    'window.__ANIFOR_INPUT_AUDIT__.requestWebGLPresentationTimingSample()',
    Math.min(1_000, remainingDeadlineMs(deadline, `${label} acceptance poll`))),
  remainingDeadlineMs(deadline, `${label} acceptance`), `${label} accepted completed-frame request`);
  return waitFor(() => evaluate(cdp, `(() => {
    const next = window.__ANIFOR_INPUT_AUDIT__.webGLPresentationTiming();
    return next && next.usableSamples > 0
      && (next.source !== ${JSON.stringify(before.source)}
        || (next.sequence > ${before.sequence}
          && next.usableSamples > ${before.usableSamples})) ? next : null;
  })()`, Math.min(1_000, remainingDeadlineMs(deadline, `${label} completion poll`))),
  remainingDeadlineMs(deadline, `${label} completion`), `${label} completed WebGL frame`);
}

function remainingDeadlineMs(deadline, label) {
  const milliseconds = deadline - Date.now();
  if (milliseconds <= 0) throw new Error(`${label} exceeded its shared deadline`);
  return milliseconds;
}

async function waitForEightXTerminalBackend(cdp, label, deadline) {
  return waitForEightX((timeoutMs) => evaluate(cdp, `(() => {
    const backend = window.__ANIFOR_INPUT_AUDIT__?.backend();
    if (!backend) return false;
    return backend.backend === 'webgl'
      || (backend.backend === 'canvas2d'
        && (backend.reason === 'webgl-timeout' || backend.reason === 'webgl-context-lost'))
      ? backend : false;
  })()`, timeoutMs), deadline, `${label} terminal backend`);
}

function assertEightXWebGLBackend(backend, label) {
  assert(backend.backend === 'webgl',
    `${label}: 8x promotion did not complete before its bounded fallback (${JSON.stringify(backend)})`);
}

async function auditCanvasFallback(cdp) {
  const geometry = await metrics(cdp);
  assertGeometry(geometry, 'Canvas fallback');
  assertContained(geometry, 'Canvas fallback');
  assertToolboxGeometry(geometry, 'Canvas fallback', DESKTOP_TOOL_FILTER_HEIGHT);
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const parameters = new URLSearchParams(location.search);
    return {
      backend: audit.backend(),
      auditStage: parameters.get('auditStage'),
      occupied: audit.occupiedCells(),
      status: document.querySelector('.status')?.textContent ?? '',
    };
  })()`);
  assert(fixture.backend.backend === 'canvas2d',
    `Canvas fallback unexpectedly selected ${JSON.stringify(fixture.backend)}`);
  if (fixture.auditStage === 'canonical') {
    assert(fixture.occupied > 40_000 && fixture.status.includes('paused render lab'),
      `Canvas fallback canonical fixture is incomplete (${JSON.stringify(fixture)})`);
  }
  const capture = await waitForStablePageCapture(cdp, 'Canvas fallback framebuffer');
  return {
    backing: `${geometry.backing.width}x${geometry.backing.height}`,
    cssCanvas: `${round(geometry.canvas.width, 2)}x${round(geometry.canvas.height, 2)}`,
    auditStage: fixture.auditStage,
    occupied: fixture.occupied,
    framebuffer: `${round(capture.canvasRect.width, 2)}x${round(capture.canvasRect.height, 2)}`,
  };
}

/**
 * A paused render lab must not repeatedly repack native state merely because a
 * temperature/presentation plane is available.  The shared counter observes
 * scheduling without requesting a WebGL timing frame (which would render).
 */
async function auditPausedPresentation(cdp, mode) {
  const initial = await waitFor(() => evaluate(cdp, `
    window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit() ?? null
  `), 5_000, `${mode} initial presentation refresh audit`);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.prepareDeutStateGraphicsFixture(); true');
  const prepared = await waitFor(() => evaluate(cdp, `(() => {
    const current = window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit();
    return current && current.dynamicSequence === ${initial.dynamicSequence + 1} ? current : null;
  })()`), 5_000, `${mode} prepared retained-state presentation`);
  const beforeMutation = await waitForIdlePresentationRefresh(
    cdp, `${mode} prepared paused presentation`,
  );
  const canvasBefore = mode === 'canvas2d'
    ? await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.canvasPresentationTiming()')
    : undefined;
  if (mode === 'canvas2d') assert(canvasBefore,
    'Canvas paused-presentation timing is unavailable after fixture setup');

  const mutation = await evaluate(cdp,
    'window.__ANIFOR_INPUT_AUDIT__.toggleRetainedPresentationProbe()');
  assert(mutation.material === await evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.cell(${mutation.x}, ${mutation.y})`)
    && mutation.before !== mutation.after
    && mutation.after === await evaluate(cdp,
      `window.__ANIFOR_INPUT_AUDIT__.presentationState(${mutation.x}, ${mutation.y})`),
  `${mode}: retained presentation probe changed matter or failed to retain its state (${JSON.stringify(mutation)})`);

  const published = await waitFor(() => evaluate(cdp, `(() => {
    const current = window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit();
    return current && current.sequence === ${beforeMutation.sequence + 1}
      && current.dynamicSequence === ${beforeMutation.dynamicSequence + 1} ? current : null;
  })()`), 5_000, `${mode} retained-state presentation publish`);
  const settled = await waitForIdlePresentationRefresh(
    cdp, `${mode} retained-state paused presentation`,
  );
  assert(settled.sequence === published.sequence
    && settled.dynamicSequence === published.dynamicSequence,
  `${mode}: paused presentation resumed work after its single retained-state publish (${JSON.stringify({ published, settled })})`);

  let canvasAdvanced;
  if (mode === 'canvas2d') {
    const canvasAfter = await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.canvasPresentationTiming()');
    assert(canvasAfter?.sequence > canvasBefore.sequence,
      `Canvas retained-state mutation did not reach the fallback presenter (${JSON.stringify({ canvasBefore, canvasAfter })})`);
    canvasAdvanced = canvasAfter.sequence - canvasBefore.sequence;
  }
  return {
    initial,
    prepared,
    beforeMutation,
    mutation,
    published,
    settled,
    canvasAdvanced,
  };
}

async function waitForIdlePresentationRefresh(cdp, label, stableForMs = 350) {
  let previous = await evaluate(cdp,
    'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
  assert(previous, `${label}: presentation refresh audit is unavailable`);
  let stableSince = performance.now();
  return waitFor(async () => {
    const current = await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
    if (!current) return null;
    if (current.sequence !== previous.sequence || current.dynamicSequence !== previous.dynamicSequence) {
      previous = current;
      stableSince = performance.now();
      return null;
    }
    return performance.now() - stableSince >= stableForMs ? current : null;
  }, 8_000, `${label} idle`);
}

async function auditCanvasGasLightingRefresh(cdp) {
  let timing = await evaluate(cdp,
    'window.__ANIFOR_INPUT_AUDIT__.canvasPresentationTiming()');
  assert(timing, 'Canvas gas-light refresh timing is unavailable');
  const durations = [];
  for (let sample = 0; sample < 20; sample++) {
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setGasFieldLighting(true); true');
    timing = await waitForCanvasPresentation(cdp, timing.sequence, `Canvas gas-light refresh ${sample + 1}`);
    assert(timing.rebuiltField === undefined,
      `Canvas gas-light refresh unexpectedly rebuilt ${timing.rebuiltField}`);
    durations.push(timing.durationMs);
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setGasFieldLighting(false); true');
    timing = await waitForCanvasPresentation(cdp, timing.sequence, `Canvas gas-light reset ${sample + 1}`);
  }
  durations.sort((left, right) => left - right);
  return {
    fixture: 'canonical atmosphere + emission field',
    samples: durations.length,
    medianMs: round(durations[Math.floor(durations.length / 2)]),
    p90Ms: round(durations[Math.floor((durations.length - 1) * 0.9)]),
    maximumMs: round(durations.at(-1)),
  };
}

async function auditDenseCanvasPresentation(cdp) {
  const initialSequence = await evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.canvasPresentationTiming()?.sequence ?? 0`);
  await evaluate(cdp, `window.__ANIFOR_INPUT_AUDIT__.prepareDenseSolidFixture(); true`);
  let timing = await waitForCanvasPresentation(cdp, initialSequence, 'dense Canvas fixture');

  const warmupFrames = 10;
  for (let warmup = 0; warmup < warmupFrames; warmup++) {
    await evaluate(cdp, `window.__ANIFOR_INPUT_AUDIT__.toggleDenseSolidProbe(); true`);
    timing = await waitForCanvasPresentation(cdp, timing.sequence, `dense Canvas warmup ${warmup + 1}`);
  }

  const targetSamples = 30;
  const durations = [];
  const stageSamples = [];
  let discardedFieldRebuilds = 0;
  for (let attempt = 0; durations.length < targetSamples && attempt < targetSamples + 15; attempt++) {
    await evaluate(cdp, `window.__ANIFOR_INPUT_AUDIT__.toggleDenseSolidProbe(); true`);
    timing = await waitForCanvasPresentation(cdp, timing.sequence, `dense Canvas sample ${attempt + 1}`);
    if (timing.rebuiltField !== undefined) {
      discardedFieldRebuilds++;
      continue;
    }
    assert(timing.volumePlaneUploads === 0 && timing.volumePlaneComposites === 0,
      `Canvas dense presentation retained invisible volume work (${JSON.stringify(timing)})`);
    durations.push(timing.durationMs);
    stageSamples.push(timing);
  }
  assert(durations.length === targetSamples,
    `Canvas dense presentation produced only ${durations.length}/${targetSamples} steady-state samples`);
  durations.sort((left, right) => left - right);
  return {
    fixture: `${WORLD_WIDTH}x${WORLD_HEIGHT} Metal`,
    warmupFrames,
    samples: durations.length,
    discardedFieldRebuilds,
    medianMs: round(durations[Math.floor(durations.length / 2)]),
    p90Ms: round(durations[Math.floor(durations.length * 0.9)]),
    maximumMs: round(durations.at(-1)),
    stages: summarizeCanvasPresentationStages(stageSamples),
  };
}

async function auditContourCanvasPresentation(cdp, denseTiming) {
  const initialSequence = await evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.canvasPresentationTiming()?.sequence ?? 0`);
  await evaluate(cdp, `window.__ANIFOR_INPUT_AUDIT__.prepareContourStressFixture(); true`);
  let timing = await waitForCanvasPresentation(cdp, initialSequence, 'Canvas contour fixture');

  // The fixture's liquid cells make every one of the 20x12 contour chunks
  // dirty during ordinary production styling. Toggle an RGB-only presentation
  // control to request repeat frames without manufacturing semantic churn.
  const warmupFrames = 10;
  let lightingEnabled = true;
  for (let warmup = 0; warmup < warmupFrames; warmup++) {
    lightingEnabled = !lightingEnabled;
    await evaluate(cdp,
      `window.__ANIFOR_INPUT_AUDIT__.setLiquidFieldLighting(${lightingEnabled}); true`);
    timing = await waitForCanvasPresentation(cdp, timing.sequence,
      `Canvas contour warmup ${warmup + 1}`);
  }

  const targetSamples = 30;
  const durations = [];
  const stageSamples = [];
  let discardedFieldRebuilds = 0;
  for (let attempt = 0; durations.length < targetSamples && attempt < targetSamples + 30; attempt++) {
    lightingEnabled = !lightingEnabled;
    await evaluate(cdp,
      `window.__ANIFOR_INPUT_AUDIT__.setLiquidFieldLighting(${lightingEnabled}); true`);
    timing = await waitForCanvasPresentation(cdp, timing.sequence,
      `Canvas contour sample ${attempt + 1}`);
    if (timing.rebuiltField !== undefined) {
      discardedFieldRebuilds++;
      continue;
    }
    durations.push(timing.durationMs);
    stageSamples.push(timing);
  }
  assert(durations.length === targetSamples,
    `Canvas contour presentation produced only ${durations.length}/${targetSamples} steady-state samples`);
  durations.sort((left, right) => left - right);
  const medianMs = durations[Math.floor(durations.length / 2)];
  const p90Ms = durations[Math.floor(durations.length * 0.9)];
  const maximumMs = durations.at(-1);
  return {
    fixture: '612x384 repeating connected 2x2 Water islands',
    expectedContourChunks: Math.ceil(WORLD_WIDTH / 32) * Math.ceil(WORLD_HEIGHT / 32),
    warmupFrames,
    samples: durations.length,
    discardedFieldRebuilds,
    medianMs: round(medianMs),
    p90Ms: round(p90Ms),
    maximumMs: round(maximumMs),
    stages: summarizeCanvasPresentationStages(stageSamples),
    // Same-process normalization is more useful than a host-specific absolute
    // number. Keep it diagnostic until repeated CI runs establish its variance.
    p90VsDense: round(p90Ms / Math.max(0.001, denseTiming.p90Ms)),
  };
}

function summarizeCanvasPresentationStages(samples) {
  const stages = {};
  for (const key of ['fieldMs', 'materialMs', 'contourMs', 'compositeMs']) {
    const values = samples.map((sample) => sample[key]).filter((value) => Number.isFinite(value));
    if (values.length !== samples.length) continue;
    values.sort((left, right) => left - right);
    stages[key] = {
      medianMs: round(values[Math.floor(values.length / 2)]),
      p90Ms: round(values[Math.floor(values.length * 0.9)]),
    };
  }
  return stages;
}

function waitForCanvasPresentation(cdp, afterSequence, label) {
  return waitFor(() => evaluate(cdp, `(() => {
    const timing = window.__ANIFOR_INPUT_AUDIT__.canvasPresentationTiming();
    return timing && timing.sequence > ${afterSequence} ? timing : null;
  })()`), 5_000, label);
}

async function auditShortDesktop(cdp, mode, dpr, previous) {
  const samples = [];
  let last = previous;
  for (const [width, height] of [[1280, 520], [1024, 500]]) {
    await setDesktopMetrics(cdp, width, height, dpr);
    const current = await waitForStableCanvas(cdp, width, height, last, 6_000, `${mode} short ${width}x${height}`);
    assertGeometry(current, `${mode} short ${width}x${height}`);
    assertContained(current, `${mode} short ${width}x${height}`);
    assertToolboxGeometry(current, `${mode} short ${width}x${height}`, DESKTOP_TOOL_FILTER_HEIGHT);
    assert(filterRows(current.ui.filterButtons) >= 3,
      `${mode}: short desktop tool filters did not form a vertical rail`);
    assert(current.ui.footer.top >= current.ui.workspace.bottom - 0.75,
      `${mode}: short desktop footer overlaps the workspace`);
    const filterReach = await evaluate(cdp, `(() => {
      const filters = document.querySelector('.tool-filters');
      if (!(filters instanceof HTMLElement)) throw new Error('Missing desktop filter rail');
      const before = filters.scrollTop;
      filters.scrollTop = filters.scrollHeight;
      const after = filters.scrollTop;
      filters.scrollTop = before;
      return {
        overflowX: getComputedStyle(filters).overflowX,
        overflowY: getComputedStyle(filters).overflowY,
        maximum: Math.max(0, filters.scrollHeight - filters.clientHeight),
        reached: after,
      };
    })()`);
    assert(filterReach.overflowX === 'hidden' && filterReach.overflowY === 'auto',
      `${mode}: short desktop filter rail does not use vertical scrolling`);
    assert(filterReach.maximum < 1 || filterReach.reached > 0,
      `${mode}: short desktop filter overflow cannot be reached`);
    const shellReach = await evaluate(cdp, `(() => {
      const shell = document.querySelector('.shell');
      const actions = document.querySelector('.actions');
      const footer = document.querySelector('.footer');
      if (!(shell instanceof HTMLElement) || !(actions instanceof HTMLElement)
        || !(footer instanceof HTMLElement)) throw new Error('Missing desktop shell geometry');
      shell.scrollTop = shell.scrollHeight;
      const actionsRect = actions.getBoundingClientRect();
      const footerRect = footer.getBoundingClientRect();
      const result = {
        overflow: getComputedStyle(shell).overflowY,
        maximum: Math.max(0, shell.scrollHeight - shell.clientHeight),
        reached: shell.scrollTop,
        actionsBottom: actionsRect.bottom,
        footerBottom: footerRect.bottom,
        viewportHeight: innerHeight,
      };
      shell.scrollTop = 0;
      return result;
    })()`);
    assert(shellReach.overflow === 'auto', `${mode}: short desktop shell is not scrollable`);
    assert(shellReach.maximum > 0 && shellReach.reached >= shellReach.maximum - 1,
      `${mode}: short desktop shell cannot reach its overflow`);
    assert(shellReach.actionsBottom <= shellReach.viewportHeight + 1
      && shellReach.footerBottom <= shellReach.viewportHeight + 1,
    `${mode}: short desktop controls or footer remain unreachable after scrolling`);
    samples.push({
      width, height,
      canvas: `${round(current.canvas.width, 2)}x${round(current.canvas.height, 2)}`,
      toolboxGap: round(current.ui.actions.top - current.ui.palette.bottom),
      filterOverflow: round(filterReach.maximum),
      shellScroll: round(shellReach.maximum),
    });
    last = current;
  }
  return samples;
}

async function auditPowderBodyDepth(cdp, mode, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const geometry = await waitForStableCanvas(
    cdp, 1280, 720, undefined, 20_000, `${mode} powder-body geometry`,
  );
  await waitForStablePageCapture(cdp, `${mode} settled powder-body fixture`, 20_000);
  const powderStyleCaptures = {};
  for (const style of ['grains', 'local', 'smooth']) {
    await evaluate(cdp, `(() => {
      const audit = window.__ANIFOR_INPUT_AUDIT__;
      if (typeof audit?.setPowderRenderStyle !== 'function') {
        throw new Error('Powder style audit API unavailable');
      }
      audit.setPowderRenderStyle('${style}');
      return true;
    })()`);
    powderStyleCaptures[style] = await waitForStablePageCapture(
      cdp, `${mode} focused ${style} powder slope`, 20_000,
    );
  }
  // The focused body-depth captures below retain the canonical Smooth view;
  // Grains and Local only exist here as fixed screenshot references.
  await evaluate(cdp, "window.__ANIFOR_INPUT_AUDIT__.setPowderRenderStyle('smooth'); true");
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setPowderBodyDepth(false); true');
  const flat = await waitForStablePageCapture(cdp, `${mode} focused flat powder body`, 20_000);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setPowderBodyDepth(true); true');
  const relieved = await waitForStablePageCapture(cdp, `${mode} focused relieved powder body`, 20_000);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setPowderBodyDepth(false); true');
  const repeatedFlat = await waitForStablePageCapture(
    cdp, `${mode} focused repeated flat powder body`, 20_000,
  );
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setPowderBodyDepth(true); true');
  const samples = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: relieved.capture.data,
    repeatedStraight: repeatedFlat.capture.data,
  }, [
    { name: 'clayBodyDepth', x: 148, y: 80, radiusX: 4, radiusY: 18 },
    { name: 'concreteBodyDepth', x: 163, y: 90, radiusX: 4, radiusY: 18 },
    { name: 'isolatedSand', x: 190.5, y: 176.5, radiusX: 1.5, radiusY: 1.5 },
    { name: 'clayDeepHole', x: 144.5, y: 62.5, radiusX: 0.45, radiusY: 0.45 },
    { name: 'concreteDeepHole', x: 159.5, y: 73.5, radiusX: 0.45, radiusY: 0.45 },
    { name: 'mineralPowderOptics', x: 405.5, y: 204.5, radiusX: 10, radiusY: 5 },
    { name: 'dustPowderOptics', x: 445.5, y: 204.5, radiusX: 10, radiusY: 5 },
    { name: 'crystalPowderOptics', x: 485.5, y: 204.5, radiusX: 10, radiusY: 5 },
    { name: 'sootyPowderOptics', x: 525.5, y: 204.5, radiusX: 10, radiusY: 5 },
    { name: 'metallicPowderOptics', x: 565.5, y: 204.5, radiusX: 10, radiusY: 5 },
  ], geometry.canvas);
  const byName = Object.fromEntries(samples.map((sample) => [sample.name, sample]));
  for (const name of ['clayBodyDepth', 'concreteBodyDepth']) {
    const sample = byName[name];
    assert(sample.rgbRms >= 0.35 && sample.chromaRms >= 0.08 && sample.rgbPeak <= 24,
      `${mode}: ${name} lost focused powder body depth (${JSON.stringify(samples)})`);
    const maximumCoreMean = name === 'clayBodyDepth' ? -0.5 : -0.08;
    assert(sample.signedMean <= maximumCoreMean,
      `${mode}: ${name} lost focused dense-core absorption (${JSON.stringify(samples)})`);
  }
  for (const name of ['isolatedSand', 'clayDeepHole', 'concreteDeepHole']) {
    assert(byName[name].rgbPeak <= 1,
      `${mode}: focused powder depth changed ${name} (${JSON.stringify(samples)})`);
  }
  for (const name of [
    'mineralPowderOptics', 'dustPowderOptics', 'crystalPowderOptics',
    'sootyPowderOptics', 'metallicPowderOptics',
  ]) {
    assert(byName[name].rgbRms >= 0.08 && byName[name].rgbPeak <= 24,
      `${mode}: ${name} lost bounded family bulk optics (${JSON.stringify(samples)})`);
  }
  assert(byName.crystalPowderOptics.responseRgb[2]
      >= byName.crystalPowderOptics.responseRgb[0] + 0.08,
  `${mode}: crystalline bulk lost its cool spectral retention (${JSON.stringify(samples)})`);
  assert(byName.metallicPowderOptics.responseRgb[2]
      >= byName.metallicPowderOptics.responseRgb[0] + 0.08,
  `${mode}: metallic bulk lost its warm-key/cool-shadow split (${JSON.stringify(samples)})`);
  assert(byName.sootyPowderOptics.rgbRms
      <= byName.mineralPowderOptics.rgbRms * 0.92,
  `${mode}: sooty bulk became as reflective as mineral powder (${JSON.stringify(samples)})`);
  assert(samples.every((sample) => sample.repeatRgbPeak <= 1),
    `${mode}: focused powder-body sequence was not deterministic (${JSON.stringify(samples)})`);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.clear(); true');
  const blank = await waitForStablePageCapture(cdp, `${mode} focused blank powder fixture`, 20_000);
  assertCanvasRectsEqual(geometry.canvas, blank.canvasRect, `${mode} powder slope/blank geometry`);
  for (const [style, capture] of Object.entries(powderStyleCaptures)) {
    assertCanvasRectsEqual(
      geometry.canvas, capture.canvasRect, `${mode} powder slope ${style}/canonical geometry`,
    );
  }
  const powderSlopeContinuity = await samplePowderSlopeContinuity(
    cdp,
    Object.fromEntries(Object.entries(powderStyleCaptures).map(([style, capture]) => [
      style, capture.capture.data,
    ])),
    blank.capture.data,
    geometry.canvas,
  );
  const { grains, local, smooth } = powderSlopeContinuity;
  assert([grains, local, smooth].every((sample) => sample.rows >= 80),
    `${mode}: shallow powder slope was not measurable (${JSON.stringify(powderSlopeContinuity)})`);
  // Smooth must follow the analytic settled slope with a bounded antialiased
  // lip; this intentionally does not demand the same maximum error from the
  // Local reference, whose semantic cell corner is the regression we expose.
  assert(smooth.rmsError <= 0.75 && smooth.maximumError <= 1.25
      && smooth.meanTransitionWidth >= 0.18 && smooth.meanTransitionWidth <= 0.80,
  `${mode}: Smooth shallow slope lost its bounded contour (${JSON.stringify(powderSlopeContinuity)})`);
  assert(smooth.rmsError <= local.rmsError * 0.90
      && smooth.maximumError <= local.maximumError * 0.90
      && smooth.meanTangentError <= local.meanTangentError * 0.98
      && smooth.meanCurvatureEnergy <= local.meanCurvatureEnergy * 0.95,
  `${mode}: Smooth shallow slope no longer improves Local continuity (${JSON.stringify(powderSlopeContinuity)})`);
  // Grains deliberately remains a square, discrete reference rather than
  // inheriting Smooth's lower analytic-error or staircase energy. Transition
  // width intentionally differs by backend because the Canvas and direct-mesh
  // rasterizers resolve a one-cell square through different coverage paths.
  assert(grains.rmsError >= smooth.rmsError * 1.15
      && grains.meanTransitionWidth <= smooth.meanTransitionWidth * 0.98
      && grains.meanTangentError >= smooth.meanTangentError * 1.02
      && grains.meanCurvatureEnergy >= smooth.meanCurvatureEnergy * 1.02,
  `${mode}: Grains no longer preserves a discrete shallow-slope reference (${JSON.stringify(powderSlopeContinuity)})`);
  const semanticSupport = await sampleSemanticCellSupport(cdp, {
    flat: flat.capture.data,
    relieved: relieved.capture.data,
  }, blank.capture.data, geometry.canvas, powderColumnCells());
  assert(semanticSupport.flat.occupiedRecall >= 0.985
    && semanticSupport.relieved.occupiedRecall >= 0.985
    && semanticSupport.relieved.occupiedRecall >= semanticSupport.flat.occupiedRecall - 0.01,
  `${mode}: focused powder body depth dropped notched-column cells (${JSON.stringify(semanticSupport)})`);
  assert(semanticSupport.flat.deepHoleLeak <= 0.10
    && semanticSupport.relieved.deepHoleLeak <= 0.10,
  `${mode}: focused powder body depth filled authored holes (${JSON.stringify(semanticSupport)})`);
  const supportRegions = [{
    name: 'powderFamilySupport',
    x: 485.5,
    y: 204.5,
    radiusX: 98,
    radiusY: 11,
    silhouette: true,
  }];
  const [flatSupport, relievedSupport] = await Promise.all([
    samplePageRegions(
      cdp, flat.capture.data, supportRegions,
      blank.capture.data, blank.reference.data, geometry.canvas,
    ),
    samplePageRegions(
      cdp, relieved.capture.data, supportRegions,
      blank.capture.data, blank.reference.data, geometry.canvas,
    ),
  ]);
  const familyCoreSupport = await samplePowderFamilyCoreSupport(cdp, {
    flat: flat.capture.data,
    relieved: relieved.capture.data,
  }, blank.capture.data, geometry.canvas, supportRegions[0]);
  // The raw blank-difference edge includes a one-pixel antialias fringe. A
  // bounded RGB-only body-depth response can move that threshold without
  // moving support. Compare the exact four-cardinal interior core instead:
  // it is still a composed framebuffer mask, rejects a real multi-pixel
  // silhouette edit, and semantic recall/deep-hole checks immediately above
  // remain the independent protection for fine structure.
  const familyCoreSupportTolerance = Math.max(
    4, Math.ceil(familyCoreSupport.flatCoreVisible * 0.0002),
  );
  assert(familyCoreSupport.coreMismatch <= familyCoreSupportTolerance
      // A body-depth RGB response can move the blank-difference threshold on a
      // few dark core pixels. The erosion/mismatch bound above still rejects a
      // real multi-pixel silhouette edit; require both independently measured
      // core counts to stay inside that same documented bound instead of the
      // contradictory exact-equality check.
      && Math.abs(familyCoreSupport.flatCoreVisible - familyCoreSupport.relievedCoreVisible)
        <= familyCoreSupportTolerance
      && familyCoreSupport.coreFraction >= 0.62,
  `${mode}: powder-family optics changed composed core support (${JSON.stringify({
    flatSupport, relievedSupport, familyCoreSupport, familyCoreSupportTolerance,
  })})`);
  return {
    backing: `${geometry.backing.width}x${geometry.backing.height}`,
    cssCanvas: `${round(geometry.canvas.width, 2)}x${round(geometry.canvas.height, 2)}`,
    samples,
    powderSlopeContinuity,
    semanticSupport,
    familySupport: {
      flat: flatSupport[0], relieved: relievedSupport[0], core: familyCoreSupport,
    },
  };
}

function assertPairedPowderBodyDepth(results) {
  const canvas = results.find((result) => result.backend === 'canvas2d')?.powderBodyDepth;
  const webgl = results.find((result) => result.backend === 'webgl')?.powderBodyDepth;
  if (!canvas || !webgl) return;
  for (const name of ['clayBodyDepth', 'concreteBodyDepth']) {
    const canvasSample = canvas.samples.find((sample) => sample.name === name);
    const webglSample = webgl.samples.find((sample) => sample.name === name);
    assert(canvasSample && webglSample, `focused paired powder-body sample missing ${name}`);
    const ratio = canvasSample.rgbRms / Math.max(0.04, webglSample.rgbRms);
    assert(ratio >= 0.30 && ratio <= 3.5,
      `focused Canvas/WebGL ${name} response diverged (${canvasSample.rgbRms}/${webglSample.rgbRms})`);
  }
  for (const name of [
    'mineralPowderOptics', 'dustPowderOptics', 'crystalPowderOptics',
    'sootyPowderOptics', 'metallicPowderOptics',
  ]) {
    const canvasSample = canvas.samples.find((sample) => sample.name === name);
    const webglSample = webgl.samples.find((sample) => sample.name === name);
    assert(canvasSample && webglSample, `focused paired powder-family sample missing ${name}`);
    const ratio = canvasSample.rgbRms / Math.max(0.04, webglSample.rgbRms);
    assert(ratio >= 0.30 && ratio <= 3.0,
      `focused Canvas/WebGL ${name} response diverged (${canvasSample.rgbRms}/${webglSample.rgbRms})`);
  }
}

async function auditLiquidOpticalDepth(cdp, mode, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const geometry = await waitForStableCanvas(
    cdp, 1280, 720, undefined, 20_000, `${mode} liquid-depth geometry`,
  );
  await waitForStablePageCapture(cdp, `${mode} settled liquid-depth fixture`, 20_000);
  // Depth is independently optional from the broad hue/macro layer. Hold the
  // latter flat so this focused proof catches a hidden dependency between the
  // two controls in either normal presenter.
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setLiquidVolumeChroma(false); true');
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setLiquidOpticalDepth(false); true');
  const flat = await waitForStablePageCapture(cdp, `${mode} focused flat liquid depth`, 20_000);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setLiquidOpticalDepth(true); true');
  const relieved = await waitForStablePageCapture(cdp, `${mode} focused optical liquid depth`, 20_000);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setLiquidOpticalDepth(false); true');
  const repeatedFlat = await waitForStablePageCapture(
    cdp, `${mode} focused repeated flat liquid depth`, 20_000,
  );
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setLiquidOpticalDepth(true); true');
  const samples = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: relieved.capture.data,
    repeatedStraight: repeatedFlat.capture.data,
  }, [
    { name: 'waterSurfaceDepth', x: 224, y: 202, radiusX: 5, radiusY: 4 },
    { name: 'oilSurfaceDepth', x: 263, y: 202, radiusX: 5, radiusY: 4 },
    { name: 'acidSurfaceDepth', x: 302, y: 202, radiusX: 5, radiusY: 4 },
    { name: 'waterDeepDepth', x: 224, y: 315, radiusX: 6, radiusY: 10 },
    { name: 'oilDeepDepth', x: 263, y: 315, radiusX: 6, radiusY: 10 },
    { name: 'acidDeepDepth', x: 302, y: 315, radiusX: 6, radiusY: 10 },
    { name: 'lavaDepthControl', x: 341, y: 315, radiusX: 6, radiusY: 10 },
    { name: 'isolatedLiquidDepthControl', x: 190.5, y: 164.5, radius: 2 },
    { name: 'unlikeLiquidDepthControl', x: 302.5, y: 172, radiusX: 0.45, radiusY: 6 },
  ], geometry.canvas);
  const byName = Object.fromEntries(samples.map((sample) => [sample.name, sample]));
  for (const family of ['water', 'oil']) {
    const surface = byName[`${family}SurfaceDepth`];
    const deep = byName[`${family}DeepDepth`];
    const minimumRms = family === 'water' ? 1.5 : 1.2;
    assert(deep.rgbRms >= minimumRms && deep.rgbPeak <= 24 && deep.signedMean <= -0.8,
      `${mode}: ${family} lost bounded deep optical absorption (${JSON.stringify(samples)})`);
    // With optional volume chroma deliberately off, the surface retains a small
    // quantized depth response of its own. Require a clearly larger raw RGB
    // response in the core, plus signed absorption; only Water needs the
    // one-byte-lower luma separation at the composed screenshot footprint.
    const minimumCoreSeparation = family === 'water' ? 0.20 : 0.30;
    assert(deep.rgbRms >= surface.rgbRms + 0.30
      && deep.signedMean <= surface.signedMean - minimumCoreSeparation,
    `${mode}: ${family} core no longer absorbs more than its surface (${JSON.stringify(samples)})`);
  }
  // Corrosive depth deliberately preserves Rec.709 luminance so chroma does not
  // manufacture false volume. Its valid core response is therefore a bounded
  // deep-vs-surface RGB/chroma separation, not a generic luma darkening.
  const acidSurface = byName.acidSurfaceDepth;
  const acidDeep = byName.acidDeepDepth;
  assert(acidDeep.rgbRms >= 2.0 && acidDeep.chromaRms >= 1.5 && acidDeep.rgbPeak <= 24,
    `${mode}: acid lost bounded deep chromatic optical absorption (${JSON.stringify(samples)})`);
  assert(acidDeep.rgbRms >= acidSurface.rgbRms + 0.30
    && acidDeep.chromaRms >= acidSurface.chromaRms + 0.30,
  `${mode}: acid core no longer separates from its surface (${JSON.stringify(samples)})`);
  for (const name of ['lavaDepthControl', 'isolatedLiquidDepthControl']) {
    assert(byName[name].rgbPeak <= 1,
    `${mode}: liquid optical depth changed ${name} (${JSON.stringify(samples)})`);
  }
  assert(byName.unlikeLiquidDepthControl.rgbPeak <= 3,
    `${mode}: liquid optical depth over-darkened an unlike seam (${JSON.stringify(samples)})`);
  assert(samples.every((sample) => sample.repeatRgbPeak <= 1),
    `${mode}: liquid optical-depth off-on-off sequence was not deterministic (${JSON.stringify(samples)})`);

  // The Water-only core glaze is deliberately separate from vertical optical
  // depth: it must give a deep, connected ordinary Water body a little volume
  // without changing droplets or unlike-liquid seams. Canvas has its own
  // equivalent body styling, so this isolates the normal WebGL contract.
  if (mode === 'webgl') {
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setAqueousSurfaceReflection(false); true');
    const aqueousFlat = await waitForStablePageCapture(cdp, 'webgl focused flat aqueous core', 20_000);
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setAqueousSurfaceReflection(true); true');
    const aqueousStyled = await waitForStablePageCapture(cdp, 'webgl focused aqueous core', 20_000);
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setAqueousSurfaceReflection(false); true');
    const aqueousRepeatedFlat = await waitForStablePageCapture(
      cdp, 'webgl focused repeated flat aqueous core', 20_000,
    );
    const aqueousSamples = await sampleBackdropRefractionRegions(cdp, {
      straight: aqueousFlat.capture.data,
      refracted: aqueousStyled.capture.data,
      repeatedStraight: aqueousRepeatedFlat.capture.data,
    }, [
      { name: 'waterDeepCore', x: 224, y: 315, radiusX: 6, radiusY: 10 },
      { name: 'isolatedLiquidDepthControl', x: 190.5, y: 164.5, radius: 2 },
      { name: 'unlikeLiquidDepthControl', x: 302.5, y: 172, radiusX: 0.45, radiusY: 6 },
    ], geometry.canvas);
    const aqueousByName = Object.fromEntries(aqueousSamples.map((sample) => [sample.name, sample]));
    const waterCore = aqueousByName.waterDeepCore;
    assert(waterCore.rgbRms >= 0.12 && waterCore.signedMean <= -0.10 && waterCore.rgbPeak <= 8,
      `webgl: aqueous core lost bounded Water-only volume (${JSON.stringify(aqueousSamples)})`);
    assert(aqueousByName.isolatedLiquidDepthControl.rgbPeak <= 1,
      `webgl: aqueous core changed an isolated droplet (${JSON.stringify(aqueousSamples)})`);
    assert(aqueousByName.unlikeLiquidDepthControl.rgbPeak <= 3,
      `webgl: aqueous core changed an unlike-liquid seam (${JSON.stringify(aqueousSamples)})`);
    assert(aqueousSamples.every((sample) => sample.repeatRgbPeak <= 1),
      `webgl: aqueous core off-on-off sequence was not deterministic (${JSON.stringify(aqueousSamples)})`);
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setAqueousSurfaceReflection(true); true');
  }

  // Acid has its own deep, luminance-neutral chroma body treatment. It is
  // deliberately behind the general Liquid Volume switch rather than the
  // aqueous-only reflection switch, so keep a separate WebGL off→on→off
  // proof here. The ordinary depth fixture above keeps volume chroma flat;
  // without this triplet the exact Acid core branch would never be exercised.
  let acidCoreSamples;
  if (mode === 'webgl') {
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setLiquidVolumeChroma(false); true');
    const acidCoreFlat = await waitForStablePageCapture(cdp, 'webgl focused flat acid core', 20_000);
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setLiquidVolumeChroma(true); true');
    const acidCoreStyled = await waitForStablePageCapture(cdp, 'webgl focused acid core', 20_000);
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setLiquidVolumeChroma(false); true');
    const acidCoreRepeatedFlat = await waitForStablePageCapture(
      cdp, 'webgl focused repeated flat acid core', 20_000,
    );
    acidCoreSamples = await sampleBackdropRefractionRegions(cdp, {
      straight: acidCoreFlat.capture.data,
      refracted: acidCoreStyled.capture.data,
      repeatedStraight: acidCoreRepeatedFlat.capture.data,
    }, [
      { name: 'acidDeepCore', x: 302, y: 315, radiusX: 6, radiusY: 10 },
      { name: 'acidSurfaceCore', x: 302, y: 202, radiusX: 5, radiusY: 4 },
      { name: 'isolatedLiquidDepthControl', x: 190.5, y: 164.5, radius: 2 },
      { name: 'unlikeLiquidDepthControl', x: 302.5, y: 172, radiusX: 0.45, radiusY: 6 },
      { name: 'lavaDepthControl', x: 341, y: 315, radiusX: 6, radiusY: 10 },
    ], geometry.canvas);
    const acidCoreByName = Object.fromEntries(acidCoreSamples.map((sample) => [sample.name, sample]));
    const acidCore = acidCoreByName.acidDeepCore;
    const acidSurfaceCore = acidCoreByName.acidSurfaceCore;
    assert(acidCore.rgbRms >= 0.08 && acidCore.chromaRms >= 0.05 && acidCore.rgbPeak <= 24,
      `webgl: Acid deep core lost its bounded chromatic volume (${JSON.stringify(acidCoreSamples)})`);
    assert(acidCore.rgbRms >= acidSurfaceCore.rgbRms + 0.02
      && acidCore.chromaRms >= acidSurfaceCore.chromaRms + 0.02,
    `webgl: Acid core no longer separates from its surface (${JSON.stringify(acidCoreSamples)})`);
    for (const name of ['isolatedLiquidDepthControl', 'unlikeLiquidDepthControl', 'lavaDepthControl']) {
      assert(acidCoreByName[name].rgbPeak <= 1,
        `webgl: Acid core leaked into ${name} (${JSON.stringify(acidCoreSamples)})`);
    }
    assert(acidCoreSamples.every((sample) => sample.repeatRgbPeak <= 1),
      `webgl: Acid core off-on-off sequence was not deterministic (${JSON.stringify(acidCoreSamples)})`);
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setLiquidVolumeChroma(true); true');
  }

  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.clear(); true');
  const blank = await waitForStablePageCapture(cdp, `${mode} focused blank liquid-depth fixture`, 20_000);
  const supportRegions = [
    { name: 'liquidDepthSupport', x: 282, y: 270, radiusX: 78, radiusY: 58, silhouette: true },
  ];
  const [flatSupport, relievedSupport] = await Promise.all([
    samplePageRegions(
      cdp, flat.capture.data, supportRegions,
      blank.capture.data, blank.reference.data, geometry.canvas,
    ),
    samplePageRegions(
      cdp, relieved.capture.data, supportRegions,
      blank.capture.data, blank.reference.data, geometry.canvas,
    ),
  ]);
  assert(Math.abs(flatSupport[0].visible - relievedSupport[0].visible)
      / Math.max(1, flatSupport[0].visible) <= 0.001
    && Math.abs(flatSupport[0].worldArea - relievedSupport[0].worldArea)
      / Math.max(0.001, flatSupport[0].worldArea) <= 0.001,
  `${mode}: liquid optical depth changed composed support (${JSON.stringify({ flatSupport, relievedSupport })})`);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setLiquidVolumeChroma(true); true');
  return {
    backing: `${geometry.backing.width}x${geometry.backing.height}`,
    cssCanvas: `${round(geometry.canvas.width, 2)}x${round(geometry.canvas.height, 2)}`,
    samples,
    acidCoreSamples,
    support: { flat: flatSupport[0], relieved: relievedSupport[0] },
  };
}

