  const grainAnchorAfter = await screenWorld(cdp, grainWheelAnchor);
  const grainAnchorError = Math.hypot(
    grainAnchorAfter.x - grainAnchorBefore.x,
    grainAnchorAfter.y - grainAnchorBefore.y,
  );
