function assertPairedDeviceIdentityGraphics(results) {
  const canvas = results.find((result) => result.backend === 'canvas2d')?.deviceIdentityGraphics;
  const webgl = results.find((result) => result.backend === 'webgl')?.deviceIdentityGraphics;
  if (!canvas || !webgl) return;
  for (const [label, expectedCards, minDistinct] of [
    ['mechanisms', 10, 10],
    ['electronics', 20, 12],
  ]) {
    const canvasLayer = canvas[label];
    const webglLayer = webgl[label];
    assert(canvasLayer.cards.length === expectedCards && webglLayer.cards.length === expectedCards
      && canvasLayer.occupied === webglLayer.occupied,
    `paired ${label} fixture topology diverged (${JSON.stringify({ canvasLayer, webglLayer })})`);
    assert(new Set(canvasLayer.samples.map((sample) => sample.responseSignature)).size >= minDistinct
      && new Set(webglLayer.samples.map((sample) => sample.responseSignature)).size >= minDistinct
      && canvasLayer.exactRepeatedOff && webglLayer.exactRepeatedOff,
    `paired ${label} lost distinct or repeatable body identities (${JSON.stringify({ canvasLayer, webglLayer })})`);
    for (const canvasSample of canvasLayer.samples) {
      const webglSample = webglLayer.samples.find((sample) => sample.name === canvasSample.name);
      assert(webglSample, `paired ${label} sample missing ${canvasSample.name}`);
      const ratio = canvasSample.rgbRms / Math.max(0.01, webglSample.rgbRms);
      assert(ratio >= 0.10 && ratio <= 10,
        `Canvas/WebGL ${label} ${canvasSample.name} response diverged (${canvasSample.rgbRms}/${webglSample.rgbRms})`);
    }
  }
}

function assertPairedFieldProfileGraphics(results) {
  const canvas = results.find((result) => result.backend === 'canvas2d')?.fieldProfileGraphics;
  const webgl = results.find((result) => result.backend === 'webgl')?.fieldProfileGraphics;
  if (!canvas || !webgl) return;
  assert(canvas.cards.length === 8 && webgl.cards.length === 8 && canvas.occupied === webgl.occupied,
    `paired Field-profile fixture topology diverged (${JSON.stringify({ canvas, webgl })})`);
  assert(new Set(canvas.samples.map((sample) => sample.responseSignature)).size === 8
    && new Set(webgl.samples.map((sample) => sample.responseSignature)).size === 8
    && canvas.exactRepeatedOff && webgl.exactRepeatedOff,
  `paired Field-profile motifs lost distinct or repeatable responses (${JSON.stringify({ canvas, webgl })})`);
  for (const canvasSample of canvas.samples) {
    const webglSample = webgl.samples.find((sample) => sample.name === canvasSample.name);
    assert(webglSample, `paired Field-profile sample missing ${canvasSample.name}`);
    const ratio = canvasSample.rgbRms / Math.max(0.01, webglSample.rgbRms);
    assert(ratio >= 0.10 && ratio <= 10,
      `Canvas/WebGL Field-profile ${canvasSample.name} response diverged (${canvasSample.rgbRms}/${webglSample.rgbRms})`);
  }
}

function assertPairedElectricDischargeGraphics(results) {
  const canvas = results.find((result) => result.backend === 'canvas2d')?.electricDischargeGraphics;
  const webgl = results.find((result) => result.backend === 'webgl')?.electricDischargeGraphics;
  if (!canvas || !webgl) return;
  assert(canvas.cards.length === 2 && webgl.cards.length === 2 && canvas.occupied === webgl.occupied,
    `paired electric-discharge fixture topology diverged (${JSON.stringify({ canvas, webgl })})`);
  assert(new Set(canvas.samples.map((sample) => sample.responseSignature)).size === 2
    && new Set(webgl.samples.map((sample) => sample.responseSignature)).size === 2
    && canvas.exactRepeatedOff && webgl.exactRepeatedOff,
  `paired electric-discharge motifs lost distinct or repeatable responses (${JSON.stringify({ canvas, webgl })})`);
  for (const canvasSample of canvas.samples) {
    const webglSample = webgl.samples.find((sample) => sample.name === canvasSample.name);
    assert(webglSample, `paired electric-discharge sample missing ${canvasSample.name}`);
    const ratio = canvasSample.rgbRms / Math.max(0.01, webglSample.rgbRms);
    // Canvas composites emissive matter through its bounded local fire plane,
    // so this exact RGB cue is intentionally quieter there than in canonical
    // WebGL. Require a real deterministic fallback response, but do not force
    // the recovery presenter to match WebGL's discharge radiance magnitude.
    assert(ratio >= 0.02 && ratio <= 10,
      `Canvas/WebGL electric-discharge ${canvasSample.name} response diverged (${canvasSample.rgbRms}/${webglSample.rgbRms})`);
  }
}

async function snapshotEightXCellularGraphics(cdp) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const snapshot = audit.cellularGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const inside = (x, y, rect) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    return {
      occupied: audit.occupiedCells(),
      cards: cards.map((entry) => {
        let bodyExact = true;
        for (let y = entry.body.y; y < entry.body.y + entry.body.height; y++) {
          for (let x = entry.body.x; x < entry.body.x + entry.body.width; x++) {
            bodyExact &&= audit.cell(x, y) === (inside(x, y, entry.hole) ? 0 : entry.material);
          }
        }
        return {
          material: entry.material,
          preset: entry.preset,
          code: entry.code,
          bodyExact,
          tendrilExact: entry.tendril.every(({ x, y }) => audit.cell(x, y) === entry.material),
          isolatedExact: audit.cell(entry.isolated.x, entry.isolated.y) === entry.material,
          guardExact: exactRect(entry.guardedBlank, 0),
        };
      }),
    };
  })()`);
}

function assertEightXCellularTopology(snapshot, label) {
  assert(snapshot.cards.length === 24 && snapshot.cards.every((card, preset) => (
    card.preset === preset && card.material === 171 + preset && card.bodyExact
      && card.tendrilExact && card.isolatedExact && card.guardExact
  )), `${label}: LIFE preset identity/topology changed (${JSON.stringify(snapshot)})`);
}

async function auditEightXCellularGraphics(cdp, canvasRect) {
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.prepareCellularGraphicsFixture !== 'function'
      || typeof audit.cellularGraphicsAtlas !== 'function'
      || typeof audit.setCellularMaterialStyling !== 'function') {
      throw new Error('True-8x cellular graphics API unavailable');
    }
    audit.resetView();
    audit.clear();
    return true;
  })()`);
  const blank = await captureSettledPage(cdp, 'renderScale=8 blank cellular framebuffer', 450);
  const rawAtlas = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareCellularGraphicsFixture();
    return audit.cellularGraphicsAtlas();
  })()`);
  const atlas = normalizeCellularGraphicsAtlas(rawAtlas);
  const prepared = await snapshotEightXCellularGraphics(cdp);
  assertEightXCellularTopology(prepared, 'renderScale=8 prepared cellular fixture');
  const live = await metrics(cdp);
  assert(live.backing.width === WORLD_WIDTH * 8 && live.backing.height === WORLD_HEIGHT * 8
      && live.outputScale === '8',
  `renderScale=8 cellular fixture lost true backing (${JSON.stringify(live.backing)})`);
  assertCanvasRectsEqual(canvasRect, live.canvas, 'renderScale=8 cellular fixture CSS geometry');

  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setCellularMaterialStyling(false); true');
  const flat = await captureSettledPage(cdp, 'renderScale=8 flat cellular framebuffer', 450);
  const flatTopology = await snapshotEightXCellularGraphics(cdp);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setCellularMaterialStyling(true); true');
  const styled = await captureSettledPage(cdp, 'renderScale=8 styled cellular framebuffer', 450);
  const styledTopology = await snapshotEightXCellularGraphics(cdp);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setCellularMaterialStyling(false); true');
  const repeated = await captureSettledPage(cdp, 'renderScale=8 repeated flat cellular framebuffer', 450);
  const repeatedTopology = await snapshotEightXCellularGraphics(cdp);
  assert(JSON.stringify(flatTopology) === JSON.stringify(prepared)
      && JSON.stringify(styledTopology) === JSON.stringify(prepared)
      && JSON.stringify(repeatedTopology) === JSON.stringify(prepared),
  'renderScale=8 cellular styling changed semantic topology');

  const regions = atlas.cards.map((entry) => ({
    name: entry.code,
    x: entry.body.x + entry.body.width / 2,
    y: entry.body.y + entry.body.height / 2,
    radiusX: Math.max(1, entry.body.width / 2 - 1),
    radiusY: Math.max(1, entry.body.height / 2 - 1),
    silhouette: true,
  }));
  const samples = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: styled.capture.data,
    repeatedStraight: repeated.capture.data,
  }, regions, canvasRect);
  assert(samples.length === 24 && samples.every((sample) => (
    sample.rgbRms >= 0.02 && sample.rgbRms <= 24
      && sample.rgbPeak > 0 && sample.rgbPeak <= 48 && sample.repeatRgbPeak <= 1
  )), `renderScale=8 cellular response is absent, unbounded, or unstable (${JSON.stringify(samples)})`);
  assert(new Set(samples.map((sample) => sample.responseSignature)).size === 24,
    `renderScale=8 LIFE presets lost distinct identity responses (${JSON.stringify(samples)})`);
  const [flatSupport, styledSupport] = await Promise.all([
    samplePageRegions(
      cdp, flat.capture.data, regions, blank.capture.data, blank.reference.data, canvasRect,
    ),
    samplePageRegions(
      cdp, styled.capture.data, regions, blank.capture.data, blank.reference.data, canvasRect,
    ),
  ]);
  // Semantics above and the static shader gate prove that LIFE style cannot
  // touch alpha/support. The compositor's colour-thresholded page mask may
  // still shift at a few antialiased CSS pixels; bound that display-only drift
  // to a half-percent of each card instead of interpreting it as geometry.
  assert(flatSupport.every((sample, index) => (
    Math.abs(sample.visible - styledSupport[index].visible) <= Math.max(2, Math.ceil(sample.visible * 0.005))
      && Math.abs(sample.worldArea - styledSupport[index].worldArea)
        <= Math.max(0.60, sample.worldArea * 0.005)
  )), `renderScale=8 cellular styling changed composed support (${JSON.stringify({ flatSupport, styledSupport })})`);
  return {
    cards: atlas.cards.map(({ material, preset, code }) => ({ material, preset, code })),
    occupied: prepared.occupied,
    samples,
    exactRepeatedOff: samples.every((sample) => sample.repeatRgbPeak <= 1),
  };
}

async function snapshotEightXExplosivePowders(cdp) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const snapshot = audit.explosivePowderGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const inside = (x, y, rect) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    return {
      occupied: audit.occupiedCells(),
      cards: cards.map((entry) => {
        let bodyExact = true;
        for (let y = entry.body.y; y < entry.body.y + entry.body.height; y++) {
          for (let x = entry.body.x; x < entry.body.x + entry.body.width; x++) {
            const empty = inside(x, y, entry.hole)
              || entry.openNotch.some((point) => point.x === x && point.y === y);
            bodyExact &&= audit.cell(x, y) === (empty ? 0 : entry.material);
          }
        }
        return {
          material: entry.material,
          code: entry.code,
          bodyExact,
          thinExact: exactRect(entry.thinColumn, entry.material),
          isolatedExact: audit.cell(entry.isolated.x, entry.isolated.y) === entry.material,
          guardExact: exactRect(entry.guardedBlank, 0),
          contactOwnerExact: exactRect(entry.contact.owner, entry.material),
          contactUnlikeExact: exactRect(entry.contact.unlike, entry.contact.unlikeMaterial),
        };
      }),
    };
  })()`);
}

function assertEightXExplosivePowderTopology(snapshot, label) {
  const materials = [14, 30, 31, 33, 84, 85, 86, 88, 89, 90, 91, 92, 94, 96];
  assert(snapshot.cards.length === materials.length && snapshot.cards.every((card, index) => (
    card.material === materials[index] && card.bodyExact && card.thinExact
      && card.isolatedExact && card.guardExact && card.contactOwnerExact && card.contactUnlikeExact
  )), `${label}: explosive-powder identity/topology changed (${JSON.stringify(snapshot)})`);
}

async function auditEightXExplosivePowderGraphics(cdp, canvasRect) {
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.prepareExplosivePowderGraphicsFixture !== 'function'
      || typeof audit.explosivePowderGraphicsAtlas !== 'function'
      || typeof audit.setExplosivePowderStyling !== 'function') {
      throw new Error('True-8x explosive-powder graphics API unavailable');
    }
    audit.resetView();
    audit.clear();
    return true;
  })()`);
  const blank = await captureSettledPage(cdp, 'renderScale=8 blank explosive-powder framebuffer', 450);
  const atlas = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareExplosivePowderGraphicsFixture();
    audit.setPowderRenderStyle('smooth');
    return audit.explosivePowderGraphicsAtlas();
  })()`);
  const prepared = await snapshotEightXExplosivePowders(cdp);
  assertEightXExplosivePowderTopology(prepared, 'renderScale=8 prepared explosive-powder fixture');
  const live = await metrics(cdp);
  assert(live.backing.width === WORLD_WIDTH * 8 && live.backing.height === WORLD_HEIGHT * 8
      && live.outputScale === '8',
  `renderScale=8 explosive-powder fixture lost true backing (${JSON.stringify(live.backing)})`);
  assertCanvasRectsEqual(canvasRect, live.canvas, 'renderScale=8 explosive-powder fixture CSS geometry');

  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setExplosivePowderStyling(false); true');
  const flat = await captureSettledPage(cdp, 'renderScale=8 flat explosive-powder framebuffer', 450);
  const flatTopology = await snapshotEightXExplosivePowders(cdp);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setExplosivePowderStyling(true); true');
  const styled = await captureSettledPage(cdp, 'renderScale=8 styled explosive-powder framebuffer', 450);
  const styledTopology = await snapshotEightXExplosivePowders(cdp);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setExplosivePowderStyling(false); true');
  const repeated = await captureSettledPage(cdp, 'renderScale=8 repeated flat explosive-powder framebuffer', 450);
  const repeatedTopology = await snapshotEightXExplosivePowders(cdp);
  assert(JSON.stringify(flatTopology) === JSON.stringify(prepared)
      && JSON.stringify(styledTopology) === JSON.stringify(prepared)
      && JSON.stringify(repeatedTopology) === JSON.stringify(prepared),
  'renderScale=8 explosive-powder styling changed semantic topology');

  const cards = Array.isArray(atlas) ? atlas : atlas.cards;
  const regions = cards.map((entry) => ({
    name: entry.code,
    x: entry.body.x + entry.body.width / 2,
    y: entry.body.y + entry.body.height / 2,
    radiusX: Math.max(1, entry.body.width / 2 - 1),
    radiusY: Math.max(1, entry.body.height / 2 - 1),
    silhouette: true,
  }));
  const samples = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: styled.capture.data,
    repeatedStraight: repeated.capture.data,
  }, regions, canvasRect);
  assert(samples.length === 14 && samples.every((sample) => (
    sample.rgbRms >= 0.02 && sample.rgbRms <= 24
      && sample.rgbPeak > 0 && sample.rgbPeak <= 48 && sample.repeatRgbPeak <= 1
  )), `renderScale=8 explosive-powder response is absent, unbounded, or unstable (${JSON.stringify(samples)})`);
  assert(new Set(samples.map((sample) => sample.responseSignature)).size === 14,
    `renderScale=8 explosive powders lost distinct identity responses (${JSON.stringify(samples)})`);
  const [flatSupport, styledSupport] = await Promise.all([
    samplePageRegions(
      cdp, flat.capture.data, regions, blank.capture.data, blank.reference.data, canvasRect,
    ),
    samplePageRegions(
      cdp, styled.capture.data, regions, blank.capture.data, blank.reference.data, canvasRect,
    ),
  ]);
  // The compact identity layer changes RGB only, which the exact semantic
  // snapshots above prove independently. At the fit-view screenshot footprint
  // a saturated RGB response can move the display-threshold classifier by one
  // CSS pixel (roughly half a world cell), without changing alpha or support.
  // Keep that bounded presentation jitter explicit instead of mistaking it for
  // a topology mutation; larger coverage changes remain release failures.
  assert(flatSupport.every((sample, index) => Math.abs(sample.visible - styledSupport[index].visible) <= 2
      && Math.abs(sample.worldArea - styledSupport[index].worldArea) <= 0.60),
  `renderScale=8 explosive-powder styling changed composed support (${JSON.stringify({ flatSupport, styledSupport })})`);
  return {
    cards: cards.map(({ material, code }) => ({ material, code })),
    occupied: prepared.occupied,
    samples,
    exactRepeatedOff: samples.every((sample) => sample.repeatRgbPeak <= 1),
  };
}

/**
 * Canonical direct-mesh proof for static source/sink/channel/force identity.
 * The render lab already owns this scene, so do not replace it with a second
 * fixture or require a Canvas capture.  The style is RGB-only: page captures
 * prove the composed result while the broad support probe catches accidental
 * coverage changes without allocating a true-8x backing ImageData copy.
 */
async function auditEightXRoleGraphics(cdp, canvasRect) {
  const probeState = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.setRoleMaterialStyling !== 'function'
      || typeof audit.roleMaterialStylingEnabled !== 'function') {
      throw new Error('True-8x role-graphics API unavailable');
    }
    return (${JSON.stringify(ROLE_GRAPHICS_REGIONS)}).map(({ name, x, y }) => ({
      name, material: audit.cell(x, y), rendered: audit.renderedCell(x, y), wall: audit.wall(x, y),
    }));
  })()`);
  const expectedRoleMaterials = [127, 126, 159, 164, 130, 115];
  assert(probeState.slice(0, expectedRoleMaterials.length).every((probe, index) => (
    probe.material === expectedRoleMaterials[index]
      && probe.rendered === expectedRoleMaterials[index]
      && probe.wall === 0
  )), `renderScale=8 semantic role fixture changed (${JSON.stringify(probeState)})`);
  const live = await metrics(cdp);
  assert(live.backing.width === WORLD_WIDTH * 8 && live.backing.height === WORLD_HEIGHT * 8
      && live.outputScale === '8',
  `renderScale=8 role graphics lost true backing (${JSON.stringify(live.backing)})`);
  assertCanvasRectsEqual(canvasRect, live.canvas, 'renderScale=8 role graphics CSS geometry');

  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setRoleMaterialStyling(false); true');
  const flatControl = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.roleMaterialStylingEnabled()');
  const flat = await captureSettledPage(cdp, 'renderScale=8 flat semantic-role framebuffer', 450);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setRoleMaterialStyling(true); true');
  const styledControl = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.roleMaterialStylingEnabled()');
  const styled = await captureSettledPage(cdp, 'renderScale=8 styled semantic-role framebuffer', 450);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setRoleMaterialStyling(false); true');
  const repeatedControl = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.roleMaterialStylingEnabled()');
  const repeated = await captureSettledPage(cdp, 'renderScale=8 repeated flat semantic-role framebuffer', 450);
  const samples = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: styled.capture.data,
    repeatedStraight: repeated.capture.data,
  }, ROLE_GRAPHICS_REGIONS, canvasRect);
  if (screenshotRequest) {
    await writeFile(variantScreenshotPath(screenshotRequest, 'role-flat'), Buffer.from(flat.capture.data, 'base64'));
    await writeFile(variantScreenshotPath(screenshotRequest, 'role-styled'), Buffer.from(styled.capture.data, 'base64'));
    await writeFile(variantScreenshotPath(screenshotRequest, 'role-repeated'), Buffer.from(repeated.capture.data, 'base64'));
  }
  const byName = Object.fromEntries(samples.map((sample) => [sample.name, sample]));
  assert(!flatControl && styledControl && !repeatedControl,
    `renderScale=8 role control did not reach the presenter (${JSON.stringify({ flatControl, styledControl, repeatedControl })})`);
  for (const name of [
    'converter', 'cloneEmitter', 'poweredCloneEmitter',
    'portalSinkChannel', 'acceleratorForce',
  ]) {
    const sample = byName[name];
    assert(sample.rgbRms >= 0.015 && sample.rgbPeak > 0 && sample.rgbPeak <= 32,
      `renderScale=8 ${name} lost bounded role identity (${JSON.stringify(samples)})`);
  }
  assert(byName.cloneEmitter.responseRgb[0] > byName.cloneEmitter.responseRgb[2] + 0.01
      && byName.poweredCloneEmitter.responseRgb[0]
        > byName.poweredCloneEmitter.responseRgb[2] + 0.01,
  `renderScale=8 emitters lost warm role identity (${JSON.stringify(samples)})`);
  assert(byName.portalSinkChannel.responseRgb[2]
      > byName.portalSinkChannel.responseRgb[0] + 0.01
    && byName.acceleratorForce.responseRgb[2]
      > byName.acceleratorForce.responseRgb[0] + 0.01,
  `renderScale=8 sink/channel/force roles lost cool identity (${JSON.stringify(samples)})`);
  assert(byName.deviceControl.rgbPeak <= 1,
    `renderScale=8 role styling leaked into device control (${JSON.stringify(samples)})`);
  assert(samples.every((sample) => sample.repeatRgbPeak <= 1),
    `renderScale=8 semantic role off-on-off sequence was not deterministic (${JSON.stringify(samples)})`);

  const supportRegion = [{
    name: 'semanticRoleSupport8x', x: 486, y: 291,
    radiusX: 100, radiusY: 28, silhouette: true, fastSupport: true,
  }];
  // These are composed page pixels rather than semantic cells.  Without a
  // backing read or a second page/fixture, the raw alpha/luma support mask is
  // sufficient for the broad existing role strip; the exact off/on screenshots
  // above separately detect its RGB-only response.
  const [flatSupport, styledSupport] = await Promise.all([
    samplePageRegions(cdp, flat.capture.data, supportRegion, undefined, undefined, canvasRect),
    samplePageRegions(cdp, styled.capture.data, supportRegion, undefined, undefined, canvasRect),
  ]);
  assert(flatSupport[0].visible === styledSupport[0].visible
      && Math.abs(flatSupport[0].worldArea - styledSupport[0].worldArea) <= 0.60,
  `renderScale=8 role styling changed composed support (${JSON.stringify({ flatSupport, styledSupport })})`);
  return {
    samples,
    probeState,
    support: {
      flatVisible: flatSupport[0].visible,
      styledVisible: styledSupport[0].visible,
      flatWorldArea: flatSupport[0].worldArea,
      styledWorldArea: styledSupport[0].worldArea,
    },
  };
}

/**
 * True-8x direct-mesh thermal proof over the ordinary render-lab cards. The
 * response is RGB-only: preserve the existing semantic owners and composed
 * support while proving cold blue and hot warm material interpretation.
 */
async function auditEightXThermalMaterialGraphics(cdp, canvasRect) {
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.setThermalMaterialStyling !== 'function') {
      throw new Error('True-8x thermal-material API unavailable');
    }
    return [
      [30, 370], [70, 370], [110, 370],
      [166, 370], [206, 370], [246, 370],
      [445, 229], [539, 229],
    ].map(([x, y]) => ({ material: audit.cell(x, y), temperature: audit.temperature(x, y) }));
  })()`);
  assert(fixture.map(({ material }) => material).join(',') === '23,23,23,1,1,1,24,12'
      && fixture.map(({ temperature }) => temperature).join(',')
        === '1200,2952,18000,1200,2952,18000,18000,1200',
  `renderScale=8 thermal fixture changed (${JSON.stringify(fixture)})`);
  const live = await metrics(cdp);
  assert(live.backing.width === WORLD_WIDTH * 8 && live.backing.height === WORLD_HEIGHT * 8
      && live.outputScale === '8',
  `renderScale=8 thermal graphics lost true backing (${JSON.stringify(live.backing)})`);
  assertCanvasRectsEqual(canvasRect, live.canvas, 'renderScale=8 thermal graphics CSS geometry');

  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setThermalMaterialStyling(false); true');
  const neutral = await captureSettledPage(cdp, 'renderScale=8 neutral thermal-material framebuffer', 450);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setThermalMaterialStyling(true); true');
  const styled = await captureSettledPage(cdp, 'renderScale=8 styled thermal-material framebuffer', 450);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setThermalMaterialStyling(false); true');
  const repeated = await captureSettledPage(cdp, 'renderScale=8 repeated neutral thermal-material framebuffer', 450);
  const regions = [
    { name: 'metalCold8x', x: 30, y: 370, radiusX: 9, radiusY: 5 },
    { name: 'metalAmbient8x', x: 70, y: 370, radiusX: 9, radiusY: 5 },
    { name: 'metalHot8x', x: 110, y: 370, radiusX: 9, radiusY: 5 },
    { name: 'sandCold8x', x: 166, y: 370, radiusX: 9, radiusY: 5 },
    { name: 'sandAmbient8x', x: 206, y: 370, radiusX: 9, radiusY: 5 },
    { name: 'sandHot8x', x: 246, y: 370, radiusX: 9, radiusY: 5 },
    { name: 'glassHotBackdrop8x', x: 445, y: 229, radiusX: 7, radiusY: 5 },
    { name: 'iceColdBackdrop8x', x: 539, y: 229, radiusX: 3, radiusY: 5 },
  ];
  const responseSamples = await sampleLightingDifferenceRegions(cdp, {
    lit: styled.capture.data,
    unlit: neutral.capture.data,
  }, regions, canvasRect);
  const response = Object.fromEntries(responseSamples.map((sample) => [sample.name, sample]));
  for (const family of ['metal', 'sand']) {
    const cold = response[`${family}Cold8x`];
    const ambient = response[`${family}Ambient8x`];
    const hot = response[`${family}Hot8x`];
    assert(ambient.peakMagnitude <= 1,
      `renderScale=8 ambient ${family} is not a thermal no-op (${JSON.stringify(ambient)})`);
    assert(cold.coverage >= 0.55 && cold.responseRgb[2] >= 1.5
      && cold.responseRgb[2] >= cold.responseRgb[0] + 2 && cold.peakMagnitude <= 32,
    `renderScale=8 cold ${family} lost bounded blue response (${JSON.stringify(cold)})`);
    assert(hot.coverage >= 0.55 && hot.responseRgb[0] >= 1.5
      && hot.responseRgb[0] >= hot.responseRgb[2] + 3 && hot.peakMagnitude <= 32,
    `renderScale=8 hot ${family} lost bounded warm response (${JSON.stringify(hot)})`);
  }
  // The wall-backed translucent cards are intentionally smaller than the
  // broad opaque material cards, so retain a practical but still directional
  // signal threshold rather than requiring normal-backend magnitude parity.
  assert(response.glassHotBackdrop8x.coverage >= 0.45
      && response.glassHotBackdrop8x.responseRgb[0] >= 1.0
      && response.glassHotBackdrop8x.responseRgb[0]
        >= response.glassHotBackdrop8x.responseRgb[2] + 2
      && response.glassHotBackdrop8x.peakMagnitude <= 32,
  `renderScale=8 hot wall-backed Glass lost warm response (${JSON.stringify(response.glassHotBackdrop8x)})`);
  // The Ice card is a deliberately narrow translucent sliver over a wall. At
  // 8x its cold shift covers only the owned high-contrast facets, so coverage
  // is much smaller than the broad material cards; require that measured
  // footprint plus a strongly directional, bounded blue response instead of
  // inventing normal-scale coverage parity for the compact direct compositor.
  assert(response.iceColdBackdrop8x.coverage >= 0.05
      && response.iceColdBackdrop8x.responseRgb[2] >= 1.0
      && response.iceColdBackdrop8x.responseRgb[2]
        >= response.iceColdBackdrop8x.responseRgb[0] + 2
      && response.iceColdBackdrop8x.peakMagnitude <= 32,
  `renderScale=8 cold wall-backed Ice lost blue response (${JSON.stringify(response.iceColdBackdrop8x)})`);
  const repeatSamples = await sampleBackdropRefractionRegions(cdp, {
    straight: neutral.capture.data,
    refracted: styled.capture.data,
    repeatedStraight: repeated.capture.data,
  }, regions, canvasRect);
  assert(repeatSamples.every((sample) => sample.repeatRgbPeak <= 1),
    `renderScale=8 thermal off-on-off sequence was not deterministic (${JSON.stringify(repeatSamples)})`);

  const supportRegions = regions.map((region) => ({
    ...region, silhouette: true, fastSupport: true,
  }));
  const [neutralSupport, styledSupport] = await Promise.all([
    samplePageRegions(cdp, neutral.capture.data, supportRegions, undefined, undefined, canvasRect),
    samplePageRegions(cdp, styled.capture.data, supportRegions, undefined, undefined, canvasRect),
  ]);
  const support = neutralSupport.map((sample, index) => ({
    name: sample.name,
    neutralVisible: sample.visible,
    styledVisible: styledSupport[index].visible,
    neutralWorldArea: sample.worldArea,
    styledWorldArea: styledSupport[index].worldArea,
  }));
  assert(support.every((sample) => sample.neutralVisible === sample.styledVisible
      && Math.abs(sample.neutralWorldArea - sample.styledWorldArea) <= 0.60),
  `renderScale=8 thermal styling changed composed support (${JSON.stringify(support)})`);
  return { fixture, responseSamples, repeatSamples, support };
}

/**
 * True-8x direct gas-volume lighting proof. The atmosphere field remains the
 * sole owner of gas alpha and topology; this toggle may change RGB relief only.
 */
async function auditEightXGasVolumeRelief(cdp, canvasRect) {
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.setGasFieldLighting !== 'function'
      || typeof audit.atmosphereSupportAudit !== 'function') {
      throw new Error('True-8x gas-volume relief API unavailable');
    }
    const signature = (() => {
      let hash = 2166136261;
      for (let y = 0; y < 190; y++) for (let x = 350; x < 612; x++) {
        hash = Math.imul(hash ^ audit.cell(x, y), 16777619);
      }
      return hash >>> 0;
    })();
    return { support: audit.atmosphereSupportAudit(), semanticSignature: signature };
  })()`);
  const live = await metrics(cdp);
  assert(live.backing.width === WORLD_WIDTH * 8 && live.backing.height === WORLD_HEIGHT * 8
      && live.outputScale === '8',
  `renderScale=8 gas-volume relief lost true backing (${JSON.stringify(live.backing)})`);
  assertCanvasRectsEqual(canvasRect, live.canvas, 'renderScale=8 gas-volume relief CSS geometry');

  const state = () => evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    let hash = 2166136261;
    for (let y = 0; y < 190; y++) for (let x = 350; x < 612; x++) {
      hash = Math.imul(hash ^ audit.cell(x, y), 16777619);
    }
    return { support: audit.atmosphereSupportAudit(), semanticSignature: hash >>> 0 };
  })()`);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setGasFieldLighting(false); true');
  const flat = await captureSettledPage(cdp, 'renderScale=8 flat gas-volume-relief framebuffer', 450);
  const flatState = await state();
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setGasFieldLighting(true); true');
  const lit = await captureSettledPage(cdp, 'renderScale=8 lit gas-volume-relief framebuffer', 450);
  const litState = await state();
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setGasFieldLighting(false); true');
  const repeated = await captureSettledPage(cdp, 'renderScale=8 repeated flat gas-volume-relief framebuffer', 450);
  const repeatedState = await state();
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setGasFieldLighting(true); true');
  assert(JSON.stringify(fixture) === JSON.stringify(flatState)
      && JSON.stringify(fixture) === JSON.stringify(litState)
      && JSON.stringify(fixture) === JSON.stringify(repeatedState),
  `renderScale=8 gas relief mutated semantic gas or atmosphere alpha (${JSON.stringify({
    fixture, flatState, litState, repeatedState,
  })})`);

  const regions = [
    { name: 'smokeGasRelief8x', x: 382, y: 40, radius: 9 },
    { name: 'oxygenGasRelief8x', x: 486, y: 32, radius: 10 },
    { name: 'nobleGasRelief8x', x: 544, y: 54, radius: 9 },
    { name: 'fogGasRelief8x', x: 430, y: 171, radiusX: 30, radiusY: 10 },
    { name: 'waterGasReliefControl8x', x: 238, y: 79, radius: 10 },
    { name: 'metalGasReliefControl8x', x: 405, y: 229, radius: 6 },
  ];
  const samples = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: lit.capture.data,
    repeatedStraight: repeated.capture.data,
  }, regions, canvasRect);
  const byName = Object.fromEntries(samples.map((sample) => [sample.name, sample]));
  for (const name of [
    'smokeGasRelief8x', 'oxygenGasRelief8x', 'nobleGasRelief8x', 'fogGasRelief8x',
  ]) {
    const sample = byName[name];
    assert(sample.rgbPeak <= 24 && sample.repeatRgbPeak <= 1,
      `renderScale=8 ${name} gas relief was unbounded or non-repeatable (${JSON.stringify(samples)})`);
  }
  assert(byName.smokeGasRelief8x.rgbRms >= 0.01
      && byName.nobleGasRelief8x.rgbRms >= 0.01,
  `renderScale=8 gas-volume relief did not change canonical Smoke/Noble RGB (${JSON.stringify(samples)})`);
  assert(byName.waterGasReliefControl8x.rgbPeak <= 1
      && byName.metalGasReliefControl8x.rgbPeak <= 1,
  `renderScale=8 gas-volume relief leaked into liquid/solid controls (${JSON.stringify(samples)})`);

  const supportRegions = regions.slice(0, 4).map((region) => ({
    ...region, silhouette: true, fastSupport: true,
  }));
  const [flatSupport, litSupport] = await Promise.all([
    samplePageRegions(cdp, flat.capture.data, supportRegions, undefined, undefined, canvasRect),
    samplePageRegions(cdp, lit.capture.data, supportRegions, undefined, undefined, canvasRect),
  ]);
  const screenSupport = flatSupport.map((sample, index) => ({
    name: sample.name,
    flatVisible: sample.visible,
    litVisible: litSupport[index].visible,
    flatWorldArea: sample.worldArea,
    litWorldArea: litSupport[index].worldArea,
  }));
  assert(screenSupport.every((sample) => sample.flatVisible === sample.litVisible
      && Math.abs(sample.flatWorldArea - sample.litWorldArea) <= 0.60),
  `renderScale=8 gas-volume relief changed composed support (${JSON.stringify(screenSupport)})`);
  return { fixture, samples, screenSupport };
}

async function snapshotEightXUnusualPowders(cdp) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const snapshot = audit.unusualPowderGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const inside = (x, y, rect) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    return {
      occupied: audit.occupiedCells(),
      cards: cards.map((entry) => {
        let bodyExact = true;
        for (let y = entry.body.y; y < entry.body.y + entry.body.height; y++) {
          for (let x = entry.body.x; x < entry.body.x + entry.body.width; x++) {
            const empty = inside(x, y, entry.hole)
              || entry.openNotch.some((point) => point.x === x && point.y === y);
            bodyExact &&= audit.cell(x, y) === (empty ? 0 : entry.material);
          }
        }
        return {
          material: entry.material,
          code: entry.code,
          bodyExact,
          thinExact: exactRect(entry.thinColumn, entry.material),
          isolatedExact: audit.cell(entry.isolated.x, entry.isolated.y) === entry.material,
          guardExact: exactRect(entry.guardedBlank, 0),
          contactOwnerExact: exactRect(entry.contact.owner, entry.material),
          contactUnlikeExact: exactRect(entry.contact.unlike, entry.contact.unlikeMaterial),
        };
      }),
    };
  })()`);
}

function assertEightXUnusualPowderTopology(
  snapshot, label, materials = [43, 44, 45, 46, 47, 48, 49, 51, 198, 217],
) {
  assert(snapshot.cards.length === materials.length && snapshot.cards.every((card, index) => (
    card.material === materials[index] && card.bodyExact && card.thinExact
      && card.isolatedExact && card.guardExact && card.contactOwnerExact && card.contactUnlikeExact
  )), `${label}: unusual-powder identity/topology changed (${JSON.stringify(snapshot)})`);
}

async function auditEightXUnusualPowderGraphics(cdp, canvasRect, options = {}) {
  const materials = options.materials ?? [43, 44, 45, 46, 47, 48, 49, 51, 198, 217];
  const expectedCount = materials.length;
  const powderLabel = options.label ?? 'unusual-powder';
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.prepareUnusualPowderGraphicsFixture !== 'function'
      || typeof audit.unusualPowderGraphicsAtlas !== 'function'
      || typeof audit.setUnusualPowderStyling !== 'function'
      || typeof audit.setPowderRenderStyle !== 'function') {
      throw new Error('True-8x unusual-powder graphics API unavailable');
    }
    audit.resetView();
    audit.clear();
    return true;
  })()`);
  const blank = await captureSettledPage(cdp, `renderScale=8 blank ${powderLabel} framebuffer`, 450);
  const rawAtlas = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareUnusualPowderGraphicsFixture();
    audit.setPowderRenderStyle('smooth');
    return audit.unusualPowderGraphicsAtlas();
  })()`);
  const atlas = normalizeUnusualPowderGraphicsAtlas(rawAtlas);
  const prepared = await snapshotEightXUnusualPowders(cdp);
  assertEightXUnusualPowderTopology(prepared, `renderScale=8 prepared ${powderLabel} fixture`, materials);
  const live = await metrics(cdp);
  assert(live.backing.width === WORLD_WIDTH * 8 && live.backing.height === WORLD_HEIGHT * 8
      && live.outputScale === '8',
  `renderScale=8 ${powderLabel} fixture lost true backing (${JSON.stringify(live.backing)})`);
  assertCanvasRectsEqual(canvasRect, live.canvas, `renderScale=8 ${powderLabel} fixture CSS geometry`);

  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setUnusualPowderStyling(false); true');
  const flat = await captureSettledPage(cdp, `renderScale=8 flat ${powderLabel} framebuffer`, 450);
  const flatTopology = await snapshotEightXUnusualPowders(cdp);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setUnusualPowderStyling(true); true');
  const styled = await captureSettledPage(cdp, `renderScale=8 styled ${powderLabel} framebuffer`, 450);
  const styledTopology = await snapshotEightXUnusualPowders(cdp);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setUnusualPowderStyling(false); true');
  const repeated = await captureSettledPage(cdp, `renderScale=8 repeated flat ${powderLabel} framebuffer`, 450);
  const repeatedTopology = await snapshotEightXUnusualPowders(cdp);
  assert(JSON.stringify(flatTopology) === JSON.stringify(prepared)
      && JSON.stringify(styledTopology) === JSON.stringify(prepared)
      && JSON.stringify(repeatedTopology) === JSON.stringify(prepared),
  `renderScale=8 ${powderLabel} styling changed semantic topology`);

  const regions = atlas.cards.map((entry) => ({
    name: entry.code,
    x: entry.body.x + entry.body.width / 2,
    y: entry.body.y + entry.body.height / 2,
    radiusX: Math.max(1, entry.body.width / 2 - 1),
    radiusY: Math.max(1, entry.body.height / 2 - 1),
    silhouette: true,
  }));
  const samples = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: styled.capture.data,
    repeatedStraight: repeated.capture.data,
  }, regions, canvasRect);
  assert(samples.length === expectedCount && samples.every((sample) => (
    sample.rgbRms >= 0.02 && sample.rgbRms <= 24
      && sample.rgbPeak > 0 && sample.rgbPeak <= 48 && sample.repeatRgbPeak <= 1
  )), `renderScale=8 ${powderLabel} response is absent, unbounded, or unstable (${JSON.stringify(samples)})`);
  assert(new Set(samples.map((sample) => sample.responseSignature)).size === expectedCount,
    `renderScale=8 ${powderLabel} owners lost distinct identity responses (${JSON.stringify(samples)})`);
  const [flatSupport, styledSupport] = await Promise.all([
    samplePageRegions(
      cdp, flat.capture.data, regions, blank.capture.data, blank.reference.data, canvasRect,
    ),
    samplePageRegions(
      cdp, styled.capture.data, regions, blank.capture.data, blank.reference.data, canvasRect,
    ),
  ]);
  assert(flatSupport.every((sample, index) => (
    Math.abs(sample.visible - styledSupport[index].visible) <= Math.max(2, Math.ceil(sample.visible * 0.005))
      && Math.abs(sample.worldArea - styledSupport[index].worldArea)
        <= Math.max(0.60, sample.worldArea * 0.005)
  )), `renderScale=8 ${powderLabel} styling changed composed support (${JSON.stringify({ flatSupport, styledSupport })})`);

  const verifyReferenceStyle = async (style, label) => {
    await evaluate(cdp, `(() => {
      const audit = window.__ANIFOR_INPUT_AUDIT__;
      audit.setPowderRenderStyle('${style}');
      audit.setUnusualPowderStyling(false);
      return true;
    })()`);
    const off = await captureSettledPage(cdp, `renderScale=8 flat ${label} unusual-powder framebuffer`, 450);
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setUnusualPowderStyling(true); true');
    const on = await captureSettledPage(cdp, `renderScale=8 styled ${label} unusual-powder framebuffer`, 450);
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setUnusualPowderStyling(false); true');
    const returned = await captureSettledPage(cdp, `renderScale=8 repeated ${label} unusual-powder framebuffer`, 450);
    const reference = await sampleBackdropRefractionRegions(cdp, {
      straight: off.capture.data,
      refracted: on.capture.data,
      repeatedStraight: returned.capture.data,
    }, regions, canvasRect);
    assert(reference.every((sample) => sample.rgbPeak <= 1 && sample.repeatRgbPeak <= 1),
      `renderScale=8 ${powderLabel} styling escaped ${label} reference mode (${JSON.stringify(reference)})`);
    return reference;
  };
  const grainsReference = await verifyReferenceStyle('grains', 'Grains');
  const localReference = await verifyReferenceStyle('local', 'Local');
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.setPowderRenderStyle('smooth');
    audit.setUnusualPowderStyling(true);
    return true;
  })()`);

  return {
    cards: atlas.cards.map(({ material, code }) => ({ material, code })),
    occupied: prepared.occupied,
    samples,
    grainsReference,
    localReference,
    exactRepeatedOff: samples.every((sample) => sample.repeatRgbPeak <= 1),
  };
}

/** Canonical direct-mesh release gate for the common Earth/mineral powder group. */
async function auditEightXEarthenPowderGraphics(cdp, canvasRect) {
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.__eightXEarthenPowderAliasRestore = {
      prepare: audit.prepareUnusualPowderGraphicsFixture,
      atlas: audit.unusualPowderGraphicsAtlas,
      toggle: audit.setUnusualPowderStyling,
    };
    audit.prepareUnusualPowderGraphicsFixture = audit.prepareEarthenPowderGraphicsFixture;
    audit.unusualPowderGraphicsAtlas = audit.earthenPowderGraphicsAtlas;
    audit.setUnusualPowderStyling = audit.setEarthenPowderStyling;
    return true;
  })()`);
  try {
    return await auditEightXUnusualPowderGraphics(cdp, canvasRect, {
      materials: [6, 21, 26, 28],
      label: 'earthen-powder',
    });
  } finally {
    await evaluate(cdp, `(() => {
      const audit = window.__ANIFOR_INPUT_AUDIT__;
      const saved = audit.__eightXEarthenPowderAliasRestore;
      if (saved) {
        audit.prepareUnusualPowderGraphicsFixture = saved.prepare;
        audit.unusualPowderGraphicsAtlas = saved.atlas;
        audit.setUnusualPowderStyling = saved.toggle;
        delete audit.__eightXEarthenPowderAliasRestore;
      }
      return true;
    })()`);
  }
}

